-- publication). Idempotent.

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"SFAR/ADARPEF — RFE, validated 22/05/2026","title":"Regional anesthesia in pediatric surgery","short":"SFAR/ADARPEF, \"Regional anesthesia in pediatric surgery\" (\"Anesthésie locorégionale en chirurgie pédiatrique\"), RFE (formalized expert recommendations), validated by the SFAR Clinical Guidelines Committee (17/03/2026), the SFAR Board of Directors (21/05/2026) and the ADARPEF Board of Directors (22/05/2026) — very recent document found through a web search (absent from this site's usual index at the date of its publication). CLINICALLY UPDATES the fiche \"Regional anesthesia in pediatrics\" (SFAR/ADARPEF RFE 2010), kept on this site for its historical value — cited as a reference by this new document. Covers 5 fields: localization methods and drugs (ultrasound guidance, alpha-2 and dexamethasone adjuvants), head surgery (cleft lip/palate, craniotomy), thoracic and spinal surgery (thoracotomy/thoracoscopy, spinal fusion and intrathecal morphine), abdominal and external genital surgery (deep abdominal/abdominal wall, inguinal/umbilical approach, former preterm infant, circumcision/hypospadias), and hip surgery. 34 recommendations (GRADE 1: 5, GRADE 2: 7, expert opinion: 17, no recommendation: 5), population 0 to 15 years (0 to 18 years for scoliosis and thoracoplasty) including neonates — count verified as exactly identical to the one announced by the source document itself in its \"Summary of results\" section.","society":"SFAR / ADARPEF","version":"2026","validated":"SFAR Board of Directors (21/05/2026) and ADARPEF Board of Directors (22/05/2026)","methodology":"GRADE grid — GRADE 1 (strong recommendation), GRADE 2 (weak recommendation), AE (expert opinion), no recommendation (chip \"0/\") — 34 recommendations (GRADE 1: 5, GRADE 2: 7, AE: 17, 0/: 5), all numerically graded recommendations are worded FOR the intervention (no \"1-\"/\"2-\" in this document)"}$mgjson$::jsonb, $mgjson${"v":1,"key":"alr_pediatrique_2026","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Field 1 — Localization methods & drugs","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Very recent document</b> (validated by the SFAR Board 21/05/2026, ADARPEF Board 22/05/2026) — found outside this repository's usual process (absent from <code>library_final.json</code> at the date of its publication), through a web search. <b>CLINICALLY UPDATES</b> the fiche \"Regional anesthesia in pediatrics\" (SFAR/ADARPEF RFE 2010), kept on this site for its historical value. <b>Population:</b> children aged 0 to 15 years (0 to 18 years for scoliosis and thoracoplasty), including neonates.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"2+"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>GRADE grid</b> — <b>1+</b>: strong recommendation FOR the intervention; <b>2+</b>: weak/optional recommendation FOR the intervention (no \"against\" recommendation graded numerically in this document); <b>AE</b>: expert opinion; <b>0/</b>: no recommendation (insufficient data). Count announced by the source itself (34 recommendations: GRADE 1: 5, GRADE 2: 7, AE: 17, absence: 5) — verified by an exact recount of the body of the text.","style":"badge_head"}]]},{"t":"section","text":"Field 1 — Localization methods & drugs used","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Ultrasound guidance — peripheral","style":"cell_b"},{"t":"p","html":"It is recommended to use ultrasound guidance to improve the analgesic efficacy of peripheral regional anesthesia.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ultrasound guidance — caudal","style":"cell_b"},{"t":"p","html":"It is recommended to use ultrasound guidance for caudal epidural anesthesia, in order to improve the safety of the procedure (make it easier to perform and reduce its complications).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ultrasound guidance — lumbar/spine","style":"cell_b"},{"t":"p","html":"The literature data are insufficient to make a recommendation concerning the use of ultrasound to perform lumbar or thoracic epidural anesthesia, or spinal anesthesia in children.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Adjuvants — alpha-2","style":"cell_b"},{"t":"p","html":"It is recommended to use clonidine or dexmedetomidine by the regional route at a dose of 1 µg/kg when prolonged analgesic efficacy is desired.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Adjuvants — combination","style":"cell_b"},{"t":"p","html":"Pediatric data are insufficient to assess the efficacy and safety of combining an alpha-2 agonist administered by the regional route with an agent of the same class used by another route of administration.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Adjuvants — dexamethasone","style":"cell_b"},{"t":"p","html":"It is recommended to use intravenous dexamethasone when prolonged analgesic efficacy is desired.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Adjuvants — dosing","style":"cell_b"},{"t":"p","html":"When the use of dexamethasone is decided, the experts suggest intravenous administration at a dose of 0.15 to 0.2 mg/kg (maximum 0.5 mg/kg, total dose capped at 10 mg).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Adjuvants — combination","style":"cell_b"},{"t":"p","html":"No pediatric data allow the combination of dexamethasone with an alpha-2 agonist to be justified or contraindicated in order to improve the analgesic efficacy of regional anesthesia.","style":"cell"},{"t":"chip","label":"0/"}]]}]},{"title":"Fields 2-3 — Head surgery, thorax & spine","items":[{"t":"section","text":"Field 2 — Head surgery","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Cleft lip/palate","style":"cell_b"},{"t":"p","html":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing cleft lip and/or palate surgery.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Cleft lip","style":"cell_b"},{"t":"p","html":"The experts suggest favoring the suprazygomatic maxillary nerve block or the infraorbital block to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Cleft palate / cleft lip and palate","style":"cell_b"},{"t":"p","html":"The experts suggest favoring the suprazygomatic maxillary nerve block to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Craniotomy","style":"cell_b"},{"t":"p","html":"It is recommended to perform a scalp block or infiltration with local anesthetics to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Field 3 — Thoracic and spinal surgery","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Thoracic","style":"cell_b"},{"t":"p","html":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing thoracic surgery.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Thoracotomy","style":"cell_b"},{"t":"p","html":"The experts suggest favoring epidural anesthesia or the paravertebral block to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Thoracoscopy","style":"cell_b"},{"t":"p","html":"The experts suggest favoring the paravertebral block to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Chronic pain — thorax","style":"cell_b"},{"t":"p","html":"The experts suggest performing regional anesthesia in addition to a multimodal analgesia protocol to limit the occurrence of chronic postoperative pain.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Spinal fusion","style":"cell_b"},{"t":"p","html":"It is recommended to perform an intrathecal morphine injection to improve analgesia during the first 24h after surgery.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Spinal fusion — dosing","style":"cell_b"},{"t":"p","html":"The experts suggest a dose of 3 to 5 µg/kg of intrathecal morphine, not exceeding 250 µg, to improve analgesia during the first 24h after surgery.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Spinal fusion — beyond 24h","style":"cell_b"},{"t":"p","html":"The experts suggest performing epidural anesthesia if the objective is to ensure postoperative regional analgesia beyond the first 24 hours.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Spinal fusion — alternative","style":"cell_b"},{"t":"p","html":"The experts suggest performing an erector spinae plane block to improve postoperative analgesia when neither intrathecal morphine injection nor epidural anesthesia is feasible.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Spinal fusion — combination","style":"cell_b"},{"t":"p","html":"The literature data are insufficient to make a recommendation concerning the combination of intrathecal morphine injection and regional anesthesia to improve analgesia beyond the first 24 postoperative hours.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Chronic pain — spine","style":"cell_b"},{"t":"p","html":"The experts suggest performing an intrathecal morphine injection, with or without regional anesthesia, in addition to a multimodal analgesia protocol to limit the occurrence of chronic postoperative pain.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Fields 4-5 — Abdomen, genitalia, hip & sources","items":[{"t":"section","text":"Field 4 — Abdominal & external genital surgery","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Deep abdominal","style":"cell_b"},{"t":"p","html":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing deep abdominal surgery.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Deep abdominal","style":"cell_b"},{"t":"p","html":"The experts suggest choosing regional anesthesia according to the type of surgery (dedicated practical sheet).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Abdominal wall","style":"cell_b"},{"t":"p","html":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing abdominal wall surgery.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Inguinal approach","style":"cell_b"},{"t":"p","html":"For surgery by the inguinal approach (inguinal hernia, cryptorchidism), the experts suggest favoring a quadratus lumborum block, a posterior transversus abdominis plane block or an ilioinguinal-iliohypogastric block.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Umbilical approach","style":"cell_b"},{"t":"p","html":"For surgery by the umbilical approach, the experts suggest favoring a rectus sheath block.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Former preterm infant","style":"cell_b"},{"t":"p","html":"In the former preterm infant undergoing inguinal hernia surgery before 60 weeks post-conceptional age, the experts suggest favoring a strategy that includes regional anesthesia to reduce the risk of postoperative complications.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"External genitalia","style":"cell_b"},{"t":"p","html":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing external genital surgery.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Circumcision","style":"cell_b"},{"t":"p","html":"The experts suggest performing a penile block or a pudendal block to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Hypospadias/scrotal approach","style":"cell_b"},{"t":"p","html":"The experts suggest performing a pudendal block to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 5 — Hip surgery","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Hip surgery","style":"cell_b"},{"t":"p","html":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing hip surgery.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Hip — major surgery","style":"cell_b"},{"t":"p","html":"The experts suggest favoring lumbar epidural analgesia to improve perioperative analgesia.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Hip — minor surgery","style":"cell_b"},{"t":"p","html":"The literature does not allow one regional anesthesia technique to be favored over another.","style":"cell"},{"t":"chip","label":"0/"}]]},{"t":"section","text":"Sources and disclaimer","color":"grey"},{"t":"p","html":"<b>Source document:</b> SFAR/ADARPEF, \"Regional anesthesia in pediatric surgery\" (\"Anesthésie locorégionale en chirurgie pédiatrique\"), Formalized Expert Recommendations (RFE), validated by the SFAR Clinical Guidelines Committee (17/03/2026), the SFAR Board of Directors (21/05/2026) and the ADARPEF Board of Directors (22/05/2026).","style":"source"},{"t":"p","html":"<b>Source URL:</b> https://sfar.org/anesthesie-locoregionale-en-chirurgie-pediatrique/","style":"source"},{"t":"p","html":"<b>Coverage:</b> the 34 recommendations of the document (Fields 1 to 5) are reproduced in full (GRADE 1: 5, GRADE 2: 7, expert opinion: 17, no recommendation: 5) — count identical to the one announced by the source itself in its \"Summary of results\" section. Clinically updates/supersedes the fiche \"Regional anesthesia in pediatrics\" (SFAR/ADARPEF RFE 2010, kept on this site for its historical value — cited as reference [1] by this new document). Two \"practical sheets\" cited by cross-reference (choice of adjuvants, choice of technique by type of abdominal surgery) are not included in the downloaded source document and are therefore not reproduced here. Detailed scientific rationale (same document, not reproduced) not included.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this fiche is an independent summary of the 34 recommendations of this reference document. It does not replace the full text or the scientific rationale. This fiche is neither published nor validated by the SFAR or the ADARPEF.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"Échoguidage — périphérique","ref_en":"Ultrasound guidance — peripheral","grade":"1+","fr":"Il est recommandé d'utiliser l'échoguidage pour améliorer l'efficacité analgésique de l'anesthésie locorégionale périphérique.","en":"It is recommended to use ultrasound guidance to improve the analgesic efficacy of peripheral regional anesthesia."},{"ref":"Adjuvants — alpha-2","grade":"1+","fr":"Il est recommandé d'utiliser la clonidine ou la dexmédétomidine par voie locorégionale à la posologie de 1 µg/kg lorsqu'une efficacité analgésique prolongée est souhaitée.","en":"It is recommended to use clonidine or dexmedetomidine by the regional route at a dose of 1 µg/kg when prolonged analgesic efficacy is desired."},{"ref":"Fente labiale/palatine","ref_en":"Cleft lip/palate","grade":"1+","fr":"Il est recommandé de réaliser une anesthésie locorégionale pour améliorer l'analgésie périopératoire chez l'enfant opéré d'une fente labiale et/ou palatine.","en":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing cleft lip and/or palate surgery."},{"ref":"Arthrodèse vertébrale","ref_en":"Spinal fusion","grade":"1+","fr":"Il est recommandé de réaliser une injection de morphine par voie intrathécale pour améliorer l'analgésie des premières 24h postopératoires.","en":"It is recommended to perform an intrathecal morphine injection to improve analgesia during the first 24h after surgery."},{"ref":"Abdominale profonde","ref_en":"Deep abdominal","grade":"1+","fr":"Il est recommandé de réaliser une anesthésie locorégionale pour améliorer l'analgésie périopératoire chez l'enfant opéré de chirurgie abdominale profonde.","en":"It is recommended to perform regional anesthesia to improve perioperative analgesia in children undergoing deep abdominal surgery."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER : le signe « + » des puces « 1+ » / « 2+ » n'est pas imprimé par la source (elle porte « GRADE 1 (recommandation forte) » / « GRADE 2 (recommandation faible) » sans signe ; sa légende parle de « pour/contre l'intervention »). Il a été ajouté lors de la construction de la fiche française au motif que toutes les recommandations gradées sont formulées « pour » l'intervention. Le cahier des charges (§4.1) interdit tout grade déduit : valider ou remplacer par « GRADE 1 » / « GRADE 2 ». La version anglaise recopie les puces à l'identique.","À VÉRIFIER : 5 recommandations « absence de recommandation » (puce 0/) n'ont pas de numéro R dans la source (questions annexes greffées à une recommandation numérotée) ; la fiche les présente en lignes séparées sans référence numérique — d'où des points clés identifiés par leur catégorie et non par un numéro. Confirmer le rattachement de chaque ligne à sa recommandation source.","À VÉRIFIER (doses, contrôle positif) : les doses ont été retrouvées mot pour mot dans sources/alr_pediatrique_2026.txt — clonidine / dexmédétomidine 1 µg/kg par voie locorégionale (l. 911, 2501) ; dexaméthasone IV 0,15 à 0,2 mg/kg, maximum 0,5 mg/kg, dose totale plafonnée à 10 mg (l. 1010, 2517-2518) ; morphine intrathécale 3 à 5 µg/kg sans dépasser 250 µg (l. 1606, 2577) ; ancien prématuré < 60 semaines post-conceptionnelles. Remarque de l'audit : pour la dexaméthasone, le « maximum 0,5 mg/kg » est supérieur à la fourchette 0,15-0,2 mg/kg ; la formulation est identique dans la source (l. 1010 et 2517-2518) — cohérence interne à confirmer par le relecteur. Le contrôle automatique FR/EN des nombres et unités ne relève aucun écart. À reconfronter à la source lors de la relecture médicale (population pédiatrique : erreur de dose = criticité maximale, CDC §9.3).","À VÉRIFIER : deux « fiches pratiques » citées par renvoi dans la source (choix des adjuvants ; choix de la technique par type de chirurgie abdominale) ne sont pas dans le PDF téléchargé et ne sont pas reproduites — les recommandations qui y renvoient (« dédiée fiche pratique ») sont traduites telles quelles ; rechercher ces fiches sur sfar.org avant publication.","À VÉRIFIER : notes internes de l'atelier (« trouvé via recherche web », « absent de library_final.json », renvoi « fiche 2010 conservée sur ce site ») dans l'introduction, la couverture et la méta ; traduites telles quelles, à retirer avant publication.","À VÉRIFIER : terminologie — « posthectomie » rendu « circumcision » ; « ancien prématuré » → « former preterm infant » ; « bloc ilio-inguinal ilio-hypogastrique » → « ilioinguinal-iliohypogastric block » ; « bloc de la gaine des muscles grands droits » → « rectus sheath block » ; « plan des muscles érecteurs du rachis » → « erector spinae plane block »."]$mgjson$::jsonb, '2026-05-22', 'ac9bcff7aac2be325450f16db706656a7c4af0bef02de03a9f03f1714a2c9255', true
from public.documents d where d.fiche_key = 'alr_pediatrique_2026'
on conflict (document_id, lang) do update set
  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"GRADE","title":"Antibiotic prophylaxis — general recommendations","short":"The 11 general recommendations (Field 1) of the RFE: timing of administration before incision, intraoperative redosing and rhythm by drug, duration (limited to the intraoperative period in the vast majority of cases), dose adjustment in obese patients (cephalosporins, amoxicillin-clavulanate, clindamycin, gentamicin, vancomycin, teicoplanin), and screening/targeted prophylaxis in patients colonized with ESBL-producing Enterobacterales (ESBL-E) before colorectal surgery. Deliberately limited scope: excludes Fields 2-3 (18 discipline-specific adult and pediatric tables of dosing by procedure, ~85 pages) — see the full text for the choice and dose for a given procedure.","society":"SFAR / SPILF (32 sociétés savantes associées) — RFE 2024","version":"V3.0 of 04/05/2026 (original V1.0 08/12/2023)","validated":"SFAR Board of Directors 30/06/2023 (Fields 1-2); SFAR Board of Directors 20/05/2026 (Field 3, pediatric)","methodology":"GRADE"}$mgjson$::jsonb, $mgjson${"v":1,"key":"antibioprophylaxie","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Introduction, methodology, scope & legend","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Field:</b> antibiotic prophylaxis (drug prevention of surgical site infection, SSI) in surgery and interventional medicine — adult and pediatric patients, clean and clean-contaminated surgery (Altemeier classes 1-2). RFE of the SFAR and of the French-language Infectious Diseases Society (Société de Pathologie Infectieuse de Langue Française, SPILF), in association with 32 learned societies of surgery and interventional medicine. V3.0 of 04/05/2026 (original V1.0 of 08/12/2023; pediatric Field 3 added in V3.0).<br/><br/><b>Methodology:</b> GRADE® method — qualitative and quantitative analysis of the literature (bibliographic search MEDLINE/Cochrane/clinicaltrials.gov, January 2000 to March 2023, PRISMA methodology), collective rating using the GRADE Grid (validation at ≥ 70 % converging opinions and &lt; 20 % opposing opinions). A single \"major\" outcome measure: surgical site infection.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Scope of this fiche — partial, explicit disclosure:</b> the source document covers <b>3 fields</b>: <b>Field 1</b> — 11 general recommendations, applicable to any procedure regardless of the discipline (the full subject of this fiche); <b>Field 2</b> — 9 discipline-specific tables for <b>adults</b> (neurosurgery/interventional neuroradiology; ENT/ophthalmology/maxillofacial surgery; cardiac surgery/interventional cardiology/rhythmology/vascular surgery; thoracic surgery/thoracic endoscopy/interventional radiology; plastic and reconstructive/gender-affirming/burn surgery; gynecologic and obstetric surgery; orthopedic and trauma surgery; digestive and bariatric surgery/digestive endoscopy and interventional medicine; urologic surgery); <b>Field 3</b> — 9 discipline-specific tables for <b>pediatrics and neonates</b>, broadly covering the same disciplines as Field 2, with two differences: the gynecologic and obstetric surgery of Field 2 has <b>no</b> dedicated pediatric table, replaced by a specific table for <b>neonatal surgery</b>. Fields 2 and 3 are <b>tables of dosing by procedure</b> (drug, dose, route, redosing interval), consulted case by case in the operating room — they total about 85 pages and do not lend themselves to a single narrative summary fiche. <b>This fiche therefore does NOT cover Fields 2 and 3</b>: for the choice and dosing of antibiotic prophylaxis for a given procedure, refer directly to the corresponding discipline table in the full text.","style":"body_sm"}},{"t":"section","text":"Legend (GRADE grades of the source)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"GRADE 1"},{"t":"p","html":"\"Strong\" overall level of evidence — strong recommendation (\"it is recommended to…\" / \"it is not recommended to…\").","style":"badge_head"}],[{"t":"chip","label":"GRADE 2"},{"t":"p","html":"Moderate or low overall level of evidence — optional recommendation (\"it is probably recommended to…\" / \"it is probably not recommended to…\").","style":"badge_head"}],[{"t":"chip","label":"AE"},{"t":"p","html":"Expert opinion — insufficient literature to grade; formalized consensus of the expert group (\"the experts suggest…\").","style":"badge_head"}]]},{"t":"p","html":"<i>Reminder from the source:</i> the weaker the strength of the recommendation (expert opinion &lt; GRADE 2 &lt; GRADE 1), the more a reasoned, multidisciplinary local adaptation may depart from it. This reference document does not address the definition of beta-lactam allergy, nor the prevention of infective endocarditis (see the dedicated 2023 European recommendations).","style":"note"}]},{"title":"Timing of administration & intraoperative redosing","items":[[{"t":"section","text":"When to administer antibiotic prophylaxis?","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Level","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"It is recommended to administer antibiotic prophylaxis with a cephalosporin (or its alternatives in case of allergy, excluding vancomycin) no earlier than 60 minutes before and no later than before the surgical incision or the start of the interventional procedure, to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"GRADE 1"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"When vancomycin is used, the experts suggest starting its intravenous administration over 60 minutes in non-obese patients no earlier than 60 minutes before, and no later than 30 minutes before the incision or the start of the procedure, to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"AE"}]]}],{"t":"p","html":"<b>Details:</b> optimal timing within the 60 minutes preceding the incision (no demonstrated difference between 60-30 min and 30-0 min); administration before induction makes it easier to attribute a possible allergic reaction. Vancomycin: optimal timing 60-30 min before the incision; dilution ≤ 5 mg/mL and prophylactic antihistamine reduce infusion-related adverse effects.","style":"note"},[{"t":"section","text":"Intraoperative redosing","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Level","style":"head_w_c"}],[{"t":"p","html":"R1.3.1","style":"cell_b"},{"t":"p","html":"It is recommended to readminister one or several intraoperative dose(s) of antibiotic prophylaxis if the surgery or interventional procedure is prolonged, to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"GRADE 1"}],[{"t":"p","html":"R1.3.2","style":"cell_b"},{"t":"p","html":"It is probably recommended to readminister this (these) dose(s), at half the initial dose, every 2 half-lives of the antibiotic used, to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"GRADE 2"}]]}],{"t":"p","html":"<b>Intraoperative redosing rhythm</b> (dose = half the initial dose):","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Every 2 h","style":"head_w"},{"t":"p","html":"Every 4 h","style":"head_w"},{"t":"p","html":"Every 8 h","style":"head_w"},{"t":"p","html":"No redosing","style":"head_w"}],[{"t":"p","html":"Cefoxitin (1 g)<br/>Cefuroxime (0.75 g)<br/>Amoxicillin/clavulanate (1 g)","style":"cell"},{"t":"p","html":"Cefazolin (1 g)<br/>Clindamycin (450 mg)","style":"cell"},{"t":"p","html":"Vancomycin (10 mg/kg)","style":"cell"},{"t":"p","html":"Gentamicin, metronidazole, teicoplanin<br/>(very long half-life)","style":"cell"}]]},{"t":"p","html":"<i>Readministration also to be discussed in case of major intraoperative bleeding and/or infusion of large volumes and/or transfusion of several packed red blood cell units, even if the normally planned interval has not been reached (expert opinion, no consensual threshold formulated in a recommendation).</i>","style":"note"}]},{"title":"Duration & adjustment in the obese patient","items":[[{"t":"section","text":"Duration of antibiotic prophylaxis","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Level","style":"head_w_c"}],[{"t":"p","html":"R1.4","style":"cell_b"},{"t":"p","html":"It is not recommended, in the vast majority of cases (and except for the exceptions mentioned in each discipline table), to prolong the administration of antibiotic prophylaxis beyond the end of surgery, to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"GRADE 1"}]]}],{"t":"p","html":"<b>Details:</b> with rare exceptions (cardiac surgery, orthognathic surgery — old/contradictory data), no demonstrated superiority of prolonged administration. If a prolongation is exceptionally discussed (not to be confused with preemptive or empirical antibiotic therapy), do not exceed 48 postoperative hours.","style":"note"},[{"t":"section","text":"Adjustment in the obese patient","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Level","style":"head_w_c"}],[{"t":"p","html":"R1.5.1","style":"cell_b"},{"t":"p","html":"It is probably not recommended to increase the unit dose of cephalosporin in the obese patient to reduce the incidence of SSI, except in particular cases (notably BMI &gt; 50 kg/m²).","style":"cell"},{"t":"chip","label":"GRADE 2"}],[{"t":"p","html":"R1.5.2","style":"cell_b"},{"t":"p","html":"The experts suggest not increasing the unit dose of amoxicillin-clavulanate in the obese patient, except in particular cases (notably BMI &gt; 50 kg/m²).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.6","style":"cell_b"},{"t":"p","html":"For alternatives to beta-lactams in case of allergy, the experts suggest using BMI-adapted doses in the obese patient (details below), to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"AE"}]]}],{"t":"p","html":"<b>Rationale R1.5.1/R1.5.2:</b> cephalosporins (cefazolin, cefoxitin, cefuroxime) and amoxicillin are hydrophilic — their volume of distribution does not increase in proportion to fat mass. A 2 g bolus of cefazolin reaches the pharmacokinetic target in the obese patient until the end of surgery or 4 h after injection (most extensive PK/PD data), with no demonstrated clinical benefit of a higher dose (3 g) on the incidence of SSI in several cohorts. For cefoxitin (2 g), concentrations remain above the target until 2 h after injection (redosing interval); for cefuroxime, the available data (1.5 g bolus) likewise show satisfactory concentrations for at least 2 h.","style":"note"},{"t":"p","html":"<b>R1.6 — detailed doses in the obese patient (alternatives to beta-lactams):</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Drug","style":"head_w"},{"t":"p","html":"Dose in the obese patient","style":"head_w"}],[{"t":"p","html":"Clindamycin","style":"cell"},{"t":"p","html":"900 mg for BMI 30-45 kg/m²; 1200 mg for BMI 46-60 kg/m²; 1600 mg for BMI &gt; 60 kg/m²","style":"cell"}],[{"t":"p","html":"Gentamicin","style":"cell"},{"t":"p","html":"6 to 7 mg/kg of adjusted weight (same as in the non-obese, calculated on adjusted weight = ideal weight + 0.4 × [total weight − ideal weight])","style":"cell"}],[{"t":"p","html":"Vancomycin","style":"cell"},{"t":"p","html":"20 mg/kg of total weight (as in the non-obese)","style":"cell"}],[{"t":"p","html":"Teicoplanin","style":"cell"},{"t":"p","html":"Not recommended in the obese patient (no data in this population)","style":"cell"}]]}]},{"title":"Patient colonized with ESBL-E & traceability","items":[[{"t":"section","text":"Patient with rectal colonization with ESBL-E (colorectal surgery)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Level","style":"head_w_c"}],[{"t":"p","html":"R1.7.1","style":"cell_b"},{"t":"p","html":"In centers where the prevalence of digestive colonization with ESBL-producing Enterobacterales (ESBL-E) in patients undergoing colorectal surgery is ≥ 10 %, the experts suggest screening for rectal ESBL-E colonization in the month preceding surgery, to adapt antibiotic prophylaxis and reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.7.2","style":"cell_b"},{"t":"p","html":"If screening is positive, the experts suggest administering, for colorectal surgery, targeted antibiotic prophylaxis active against the identified ESBL-E strain, to reduce the incidence of SSI.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.7.3","style":"cell_b"},{"t":"p","html":"The experts suggest multidisciplinary management (anesthesiologist-intensivist, surgeon, infectious disease specialist or infectious disease referent, microbiologist) to individualize antibiotic prophylaxis in patients with rectal ESBL-E colonization undergoing colorectal surgery.","style":"cell"},{"t":"chip","label":"AE"}]]}],{"t":"p","html":"<b>Details:</b> in ESBL-E carriers, targeted antibiotic prophylaxis: ertapenem 2 g slow IV as a single dose, or an alternative effective against the strain (cefoxitin, amoxicillin/clavulanate, piperacillin/tazobactam) — systematic administration of a carbapenem is <b>not</b> synonymous with targeted antibiotic prophylaxis, several alternatives exist. Carriage threshold retained: 10 % (by analogy with the WHO definition of \"high\" colonization, in the absence of a prospectively validated threshold).","style":"note"},{"t":"section","text":"Sources and traceability","color":"grey"},{"t":"p","html":"<b>Source document:</b> \"Antibiotic prophylaxis in surgery and interventional medicine, adult and pediatric\" (\"Antibioprophylaxie en chirurgie et médecine interventionnelle adulte et pédiatrique\") — Formalized Expert Recommendations (RFE) of the French Society of Anesthesia and Intensive Care Medicine (SFAR) and of the French-language Infectious Diseases Society (SPILF), in association with 32 learned societies (AFU, SFR/RI, SFCR, SFO, SFSCMFCO, SFORL, ADARPEF, SOFCOT, SPLF, SFCTCV, SFC, CNGOF, SCVE, SFNC, SFB, SOFCPRE, SFED, SFCD, ACHBT, CARO, GPIP, SFOP, SOFOP, SFCP, SFCPP, SFUPA, AFOP, GFHFNP, SFNCP, SFN, and others). Coordinators: Marc Leone (SFAR, Marseille), Mathilde de Queiroz (SFAR, Lyon, pediatric part), Rémy Gauzit (SPILF, Paris). Organizers: Marc Garnier (Clermont-Ferrand), Maxime Nguyen (Dijon, pediatric part).","style":"source"},{"t":"p","html":"<b>Validation:</b> Fields 1-2 (introduction, general recommendations, adult tables) — SFAR Clinical Guidelines Committee (CRC) 15/06/2023, SFAR Board of Directors 30/06/2023, SPILF guidelines committee 06/09/2023, then boards of directors of the associated societies between September and December 2023 (tacit validation on 30/11/2023 for the others). Field 3 (pediatric tables) — SFAR CRC 26/03/2026, SFAR Board of Directors 20/05/2026, SPILF 02/03/2026, GPIP 27/01/2026, then boards of directors of the associated pediatric societies between December 2025 and March 2026.","style":"source"},{"t":"p","html":"<b>Version history:</b> V1.0 (08/12/2023, original version); V1.1-V2.0 (Dec. 2023 - May 2024, corrections of typos and clarifications in the discipline tables); <b>V3.0 (04/05/2026)</b> — addition of recommendation R1.5.2 (amoxicillin-clavulanate dose in the obese), clarification of R1.6, and addition of Field 3 (9 pediatric and neonatal tables); V3.1 (10/07/2026) — amendment of a neonatal digestive surgery diagram. This fiche reflects V3.0/V3.1.","style":"source"},{"t":"p","html":"<b>Methodology:</b> GRADE® method — bibliographic search MEDLINE/Cochrane/clinicaltrials.gov (January 2000 - March 2023), PRISMA methodology, GRADE Grid rating by the experts (agreement retained at ≥ 70 % converging opinions and &lt; 20 % opposing opinions; expert opinions systematically subjected to the same 70 % threshold). The 11 recommendations of Field 1 all obtained strong agreement.","style":"source"},{"t":"p","html":"<b>Coverage:</b> this fiche reproduces all <b>11 recommendations of Field 1</b> (general recommendations) — timing of administration, intraoperative redosing, duration, adjustment in the obese, patient colonized with ESBL-E — with their key rationale. It <b>explicitly excludes</b> Fields 2 and 3 (18 discipline-specific adult and pediatric tables of dosing by procedure, ~85 pages): see the scope panel on page 1 and refer to the full text for the choice and dose of antibiotic prophylaxis for a given procedure.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this document is an independent summary fiche, produced as a memory aid, limited to Field 1 (general recommendations) of the SFAR/SPILF RFE 2024 (V3.0 of 04/05/2026). It does not replace the full text (complete rationale, bibliographic references, discipline tables of Fields 2-3) and is neither published nor validated by the SFAR, the SPILF or the associated learned societies. In case of doubt, refer to the full text and/or to a specialist opinion (infectious disease specialist, antibiotic stewardship referent).","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"R1.1","grade":"GRADE 1","fr":"Il est recommandé d'administrer l'antibioprophylaxie par céphalosporine (ou ses alternatives en cas d'allergie, hors vancomycine) au plus tôt 60 minutes avant et au plus tard avant l'incision chirurgicale ou le début de la procédure interventionnelle, pour diminuer l'incidence d'ISO.","en":"It is recommended to administer antibiotic prophylaxis with a cephalosporin (or its alternatives in case of allergy, excluding vancomycin) no earlier than 60 minutes before and no later than before the surgical incision or the start of the interventional procedure, to reduce the incidence of SSI."},{"ref":"R1.3.1","grade":"GRADE 1","fr":"Il est recommandé de réadministrer une à plusieurs dose(s) peropératoire(s) d'antibioprophylaxie en cas de prolongation de la chirurgie ou de l'acte interventionnel, pour diminuer l'incidence d'ISO.","en":"It is recommended to readminister one or several intraoperative dose(s) of antibiotic prophylaxis if the surgery or interventional procedure is prolonged, to reduce the incidence of SSI."},{"ref":"R1.4","grade":"GRADE 1","fr":"Il n'est pas recommandé, dans la très grande majorité des cas (et hors exceptions mentionnées dans chaque tableau disciplinaire), de prolonger l'administration de l'antibioprophylaxie au-delà de la fin de la chirurgie, pour diminuer l'incidence d'ISO.","en":"It is not recommended, in the vast majority of cases (and except for the exceptions mentioned in each discipline table), to prolong the administration of antibiotic prophylaxis beyond the end of surgery, to reduce the incidence of SSI."},{"ref":"R1.5.1","grade":"GRADE 2","fr":"Il n'est probablement pas recommandé d'augmenter la dose unitaire de céphalosporine chez le patient obèse pour diminuer l'incidence d'ISO, en dehors de cas particuliers (notamment IMC &gt; 50 kg/m²).","en":"It is probably not recommended to increase the unit dose of cephalosporin in the obese patient to reduce the incidence of SSI, except in particular cases (notably BMI &gt; 50 kg/m²)."},{"ref":"R1.7.2","grade":"AE","fr":"En cas de positivité du dépistage, les experts suggèrent d'administrer, pour une chirurgie colo-rectale, une antibioprophylaxie ciblée active sur la souche d'E-BLSE identifiée, pour diminuer l'incidence d'ISO.","en":"If screening is positive, the experts suggest administering, for colorectal surgery, targeted antibiotic prophylaxis active against the identified ESBL-E strain, to reduce the incidence of SSI."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER (date de la version en vigueur) : la fiche française indique « V3.0 du 04/05/2026 (V1.0 originale 08/12/2023) » dans sa méta mais son historique cite aussi une V3.1 du 10/07/2026 (amendement d'un schéma de chirurgie digestive néonatale, hors périmètre de la fiche) et « cette fiche reflète la V3.0/V3.1 » ; la bibliothèque indique 2023-12. La date de publication retenue ici pour l'ordre de traitement est celle de la V3.1 (2026-07-10) ; à confirmer sur la page source (date de la version en vigueur, CDC §4.2).","À VÉRIFIER (périmètre partiel, déjà signalé dans la fiche) : seuls les 11 items du Champ 1 (recommandations générales) sont repris ; les Champs 2 et 3 (18 tableaux de posologie par procédure, adultes et pédiatriques/néonatals) sont exclus. Le relecteur doit décider si une fiche partielle peut être publiée telle quelle (verrou de publication : recommandations complètes du document ou périmètre partiel expressément affiché).","À VÉRIFIER : la colonne « Niveau » utilise les libellés de la source sans signe (GRADE 1, GRADE 2, AE) — recopiés à l'identique en anglais ; la légende (« il est recommandé » = fort ; « il est probablement recommandé » = optionnel ; « les experts suggèrent » = avis d'experts) est traduite mot à mot pour préserver la correspondance des formulations.","À VÉRIFIER : sigles traduits — ISO → SSI (surgical site infection), E-BLSE → ESBL-E (ESBL-producing Enterobacterales), IMC → BMI, CGR → packed red blood cells, CRC → Clinical Guidelines Committee, CA → Board of Directors ; noms de sociétés (SFAR, SPILF, etc.) conservés, avec la dénomination anglaise de la SFAR/SPILF en première occurrence. La liste des 32 sociétés associées est laissée en sigles français.","À VÉRIFIER (doses) : toutes les doses et intervalles (céfoxitine 1 g, céfuroxime 0,75 g, céfazoline 1 g / 2 g, clindamycine 450 mg / 900-1200-1600 mg selon l'IMC, vancomycine 10 mg/kg puis 20 mg/kg, gentamicine 6 à 7 mg/kg de poids ajusté, ertapénème 2 g) sont recopiés à l'identique ; le contrôle automatique FR/EN des nombres et unités ne relève aucun écart. À reconfronter à la source lors de la relecture médicale.","À VÉRIFIER (droits) : le tableau du rythme de réinjection et le tableau des doses chez l'obèse reprennent des tableaux de la source (CDC §12.4 : pas de reproduction à l'identique) — statut juridique à valider.","À VÉRIFIER (incohérences internes de la fiche française, relevées par l'audit de traduction, reprises à l'identique) : (a) le panneau de périmètre annonce « à deux différences près » entre les Champs 2 et 3 mais n'en énonce qu'une (pas de tableau pédiatrique de gynécologie-obstétrique, remplacé par la chirurgie néonatale) ; (b) l'avertissement cite « RFE SFAR/SPILF 2024 » alors que la validation date de 2023 et la V1.0 de décembre 2023."]$mgjson$::jsonb, '2026-07-10', 'cc1a141bb9da5737c204081af938183aa329a9f5f8ef440fb39896f40a067fd9', true
from public.documents d where d.fiche_key = 'antibioprophylaxie'
on conflict (document_id, lang) do update set
  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"GRADE","title":"Anticoagulants & invasive procedures","short":"Peri-procedural management of anticoagulants for a scheduled invasive procedure.","society":"SFAR / GIHP — RFE 2026","version":"20 April 2026","validated":"SFAR Board of Directors on 18/03/2026","methodology":"GRADE"}$mgjson$::jsonb, $mgjson${"v":1,"key":"anticoagulants","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"General principles & discontinuation intervals","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>General principle (R1 — GRADE 1+, strong agreement):</b> peri-procedural management of anticoagulants is decided by crossing 3 elements: the <b>bleeding risk of the procedure</b>, the <b>patient's thromboembolic risk</b>, and the <b>consequences of postponing</b> the procedure if both risks are high.","style":"body"}},{"t":"section","text":"Grade legend (GRADE methodology)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Recommended (strong)","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Not recommended (strong)","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Suggested (optional)","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Suggested not to do","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Expert opinion","style":"badge_head"}]]},{"t":"section","text":"Definitions — Bleeding risk of the procedure","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"<b>Low risk</b>","style":"cell_b"},{"t":"p","html":"Infrequent, low-intensity or easily controlled bleeding. Feasible under curative anticoagulation.","style":"cell"}],[{"t":"p","html":"<b>High risk</b>","style":"cell_b"},{"t":"p","html":"Requires discontinuation of the anticoagulant: bleeding is increased in the anticoagulated patient.","style":"cell"}],[{"t":"p","html":"<b>Neuraxial procedures</b>","style":"cell_b"},{"t":"p","html":"Lumbar puncture, spinal anesthesia, epidural, combined spinal-epidural (excluding spine surgery) — considered at very high bleeding risk.","style":"cell"}]]},{"t":"section","text":"LOW bleeding-risk procedure — no discontinuation","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"2.1","style":"cell_b"},{"t":"p","html":"VKA: continue the treatment; check the INR in the week preceding the procedure (absence of overdose).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"2.2","style":"cell_b"},{"t":"p","html":"DOACs (apixaban, dabigatran, edoxaban, rivaroxaban): skip the dose of the evening before AND that of the morning of the procedure (whatever the regimen), resume at usual doses ≥ 6h after the procedure.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"HIGH bleeding-risk procedure — pre-procedural discontinuation intervals","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Anticoagulant","style":"head_w"},{"t":"p","html":"Last dose / injection before the procedure (D0)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"VKA — Warfarin (Coumadine®)","style":"cell"},{"t":"p","html":"D-6, then INR check the day before (target ≤ 1.5; ≤ 1.2 if neurosurgery/neuraxial)","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"VKA — Fluindione (Préviscan®)","style":"cell"},{"t":"p","html":"D-5, then INR check the day before","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"VKA — Acenocoumarol (Sintrom®)","style":"cell"},{"t":"p","html":"D-4, then INR check the day before","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Anti-Xa DOACs (apixaban, edoxaban, rivaroxaban)","style":"cell"},{"t":"p","html":"D-3 if normal renal function; D-5 if very high bleeding risk (intracranial neurosurgery, neuraxial)","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dabigatran","style":"cell"},{"t":"p","html":"D-3 (normal renal function); adapt if CKD (see renal table)","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"LMWH curative dose","style":"cell"},{"t":"p","html":"24h before the procedure","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"UFH subcutaneous curative dose","style":"cell"},{"t":"p","html":"24h before the procedure","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"UFH continuous IV infusion (syringe pump) curative dose","style":"cell"},{"t":"p","html":"6h before the procedure","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Fondaparinux curative dose","style":"cell"},{"t":"p","html":"D-4","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"* If INR > safety threshold the day before: vitamin K 2 to 5 mg PO (oral route preferred to IV: anaphylactic risk described with the IV route), INR check the next day.","style":"note"},{"t":"p","html":"* Post-procedural resumption (high bleeding risk): VKA within the first 24 hours, usual dosage, without loading dose (R4.1, GRADE 2+, Strong — upgraded to 1+ for AF specifically, see p.2). DOACs ideally between 48h and 72h, without heparin bridging (R4.5/R5.6/R7.10, GRADE 2+, Strong). If resumption is not possible: curative-dose heparin 48-72h later (R4.2/R4.6, GRADE 2+, Strong). Post-procedural venous thromboprophylaxis recommended in the meantime (R4.7, GRADE 1+, Strong).","style":"note"}]},{"title":"Summary by indication — Atrial fibrillation & mechanical valve","items":[{"t":"section","text":"Atrial fibrillation (AF) — patient on DOAC","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"5.1","style":"cell_b"},{"t":"p","html":"History of ischemic stroke: postpone the procedure beyond the 3rd month after the stroke if possible (except vital/functional emergency).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"3.3/5.5","style":"cell_b"},{"t":"p","html":"High bleeding risk: DOAC discontinuation, last dose at D-3 (normal GFR), without heparin bridging.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"5.6","style":"cell_b"},{"t":"p","html":"Resumption of curative treatment with the usual DOAC, ideally between 48h and 72h, without heparin bridging.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"4.7","style":"cell_b"},{"t":"p","html":"Post-procedural venous thromboprophylaxis while awaiting resumption of curative treatment.","style":"cell"},{"t":"chip","label":"1+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"Atrial fibrillation (AF) — patient on VKA","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"3.1/3.2","style":"cell_b"},{"t":"p","html":"VKA discontinuation before a high-risk procedure (intervals p.1) + INR check the day before; vitamin K if needed.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"5.2","style":"cell_b"},{"t":"p","html":"Without history of stroke/TIA/systemic embolism: NO pre-procedural heparin bridging.","style":"cell"},{"t":"chip","label":"1-"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"5.3","style":"cell_b"},{"t":"p","html":"With history of stroke/TIA/systemic embolism: pre-procedural bridging with curative-dose LMWH (1st injection evening of D-3, last one at the latest the morning of D-1), without systematic anti-Xa monitoring.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"4.1","style":"cell_b"},{"t":"p","html":"Resumption of VKA within the first 24 hours after the procedure, usual dosage, without loading dose, without heparin bridging.","style":"cell"},{"t":"chip","label":"1+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"4.2","style":"cell_b"},{"t":"p","html":"If VKA resumption is not possible <24h: curative-dose heparin (LMWH preferred), ideally 48-72h after the procedure.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"Mechanical heart valve (VKA)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"6.1","style":"cell_b"},{"t":"p","html":"Systematic pre-procedural bridging with curative-dose LMWH twice daily (1st injection evening of D-3, last one morning of D-1), without anti-Xa monitoring.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"6.2","style":"cell_b"},{"t":"p","html":"Schedule the procedure in the morning so as not to prolong the anticoagulant interruption.","style":"cell"},{"t":"chip","label":"AE"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"6.3","style":"cell_b"},{"t":"p","html":"Bileaflet aortic valve, sinus rhythm, without thrombotic history: no post-procedural heparin bridging if VKA resumed <24h.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"6.4","style":"cell_b"},{"t":"p","html":"Other cases: post-procedural heparin bridging (LMWH twice daily), ideally started 48-72h after, stopped at the 1st INR ≥ 2.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]}]},{"title":"Summary by indication — Venous thromboembolism","items":[{"t":"section","text":"Venous thromboembolism (VTE) — risk stratification","color":"navy"},{"t":"panel","tone":"default","content":{"t":"table","rows":[[{"t":"p","html":"<b>Very high</b>","style":"cell_b"},{"t":"p","html":"PE or proximal DVT < 1 month","style":"cell"}],[{"t":"p","html":"<b>High</b>","style":"cell_b"},{"t":"p","html":"PE or proximal DVT of 1 to 3 months","style":"cell"}],[{"t":"p","html":"<b>To be assessed</b>","style":"cell_b"},{"t":"p","html":"APS, CTEPH, major thrombophilia, ongoing HIT, recurrence on treatment → <b>multidisciplinary discussion</b>","style":"cell"}],[{"t":"p","html":"<b>Moderate</b>","style":"cell_b"},{"t":"p","html":"Other cases","style":"cell"}]]}},{"t":"p","html":"Postpone the procedure beyond the 1st month (ideally > 3 months) after PE/proximal DVT if possible (R7.2, GRADE 2+, Strong).","style":"note"},{"t":"section","text":"VTE — patient on DOAC","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"3.3","style":"cell_b"},{"t":"p","html":"High bleeding risk, non-complex case: DOAC discontinuation, last dose at D-3 (normal GFR), without bridging.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.8","style":"cell_b"},{"t":"p","html":"PE/proximal DVT < 1 month: personalized multidisciplinary strategy.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.9","style":"cell_b"},{"t":"p","html":"Other cases of VTE: interrupt the DOAC without pre-procedural heparin bridging.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.10","style":"cell_b"},{"t":"p","html":"Resumption of curative treatment with the usual DOAC, ideally 48-72h later, without heparin bridging.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"4.6","style":"cell_b"},{"t":"p","html":"If curative treatment cannot be resumed with the usual DOAC, start anticoagulation with curative-dose heparins (LMWH preferably), ideally 48-72h after the procedure.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"VTE — patient on VKA","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"7.4","style":"cell_b"},{"t":"p","html":"PE/proximal DVT < 3 months: pre-procedural bridging with curative-dose LMWH (1st injection evening of D-3, last one at the latest the morning of D-1).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.5","style":"cell_b"},{"t":"p","html":"Moderate recurrence risk: NO pre-procedural heparin bridging.","style":"cell"},{"t":"chip","label":"2-"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.6","style":"cell_b"},{"t":"p","html":"PE/DVT < 3 months or known protein C/S deficiency: post-procedural bridging with curative-dose heparin, started 48-72h later, stopped at the 1st INR ≥ 2.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.7","style":"cell_b"},{"t":"p","html":"Other cases: no post-procedural bridging if VKA resumed < 24h.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"VTE — vena cava filter & mechanical thromboprophylaxis","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"7.11","style":"cell_b"},{"t":"p","html":"PE/proximal DVT < 1 month + high bleeding-risk procedure: discuss an optional pre-procedural vena cava filter.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.12","style":"cell_b"},{"t":"p","html":"Planned filter removal as soon as curative anticoagulation is resumed (ideally < 3 months).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.13","style":"cell_b"},{"t":"p","html":"Symptomatic distal DVT: postpone the procedure beyond the 1st month following the thrombosis if this does not generate a major vital/functional risk.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.14","style":"cell_b"},{"t":"p","html":"High bleeding AND thromboembolic risk: intermittent pneumatic compression intra- and post-procedure, in combination with pharmacological prophylaxis.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"7.15","style":"cell_b"},{"t":"p","html":"Graduated elastic compression stockings: NOT recommended whatever the thromboembolic risk.","style":"cell"},{"t":"chip","label":"1-"},{"t":"p","html":"Strong","style":"cell_c"}]]}]},{"title":"Adaptation to renal failure","items":[{"t":"section","text":"Chronic kidney disease (CKD) — stages (CKD-EPI)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Stage","style":"head_w"},{"t":"p","html":"eGFR (mL/min/1.73m²)","style":"head_w_c"}],[{"t":"p","html":"Moderate CKD (3)","style":"cell"},{"t":"p","html":"30 – 49","style":"cell_c"}],[{"t":"p","html":"Severe CKD (4)","style":"cell"},{"t":"p","html":"15 – 29","style":"cell_c"}],[{"t":"p","html":"End-stage CKD (5 / 5D)","style":"cell"},{"t":"p","html":"< 15","style":"cell_c"}]]},{"t":"p","html":"VKA and UFH: handling unchanged whatever the CKD stage (non-renal elimination). DOACs and LMWH: see tables below.","style":"note"},{"t":"section","text":"DOAC pre-procedural discontinuation interval according to eGFR (AF)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Drug","style":"head_w"},{"t":"p","html":"eGFR","style":"head_w_c"},{"t":"p","html":"Low risk","style":"head_w_c"},{"t":"p","html":"High risk","style":"head_w_c"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Apixaban / Edoxaban / Rivaroxaban","style":"cell"},{"t":"p","html":"≥ 50","style":"cell_c"},{"t":"p","html":"No discontinuation\n(skip the evening of D-1 + the morning dose)","style":"cell_c"},{"t":"p","html":"D-3","style":"cell_c"},{"t":"chip","label":"2+"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"30 – 49","style":"cell_c"},{"t":"p","html":"same","style":"cell_c"},{"t":"p","html":"D-3","style":"cell_c"},{"t":"chip","label":"2+"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"15 – 29","style":"cell_c"},{"t":"p","html":"same","style":"cell_c"},{"t":"p","html":"D-5","style":"cell_c"},{"t":"chip","label":"AE"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"< 15","style":"cell_c"},{"t":"p","html":"No DOAC / no validated dosing","style":"cell_c"},{"t":"p","html":"—","style":"cell_c"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Dabigatran","style":"cell"},{"t":"p","html":"≥ 50","style":"cell_c"},{"t":"p","html":"same","style":"cell_c"},{"t":"p","html":"D-3","style":"cell_c"},{"t":"chip","label":"2+"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"30 – 49","style":"cell_c"},{"t":"p","html":"same","style":"cell_c"},{"t":"p","html":"D-5","style":"cell_c"},{"t":"chip","label":"2+"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"< 30","style":"cell_c"},{"t":"p","html":"Not recommended","style":"cell_c"},{"t":"p","html":"—","style":"cell_c"},{"t":"chip","label":"1-"}]]},{"t":"p","html":"Applicable if the DOAC is prescribed at the dose adapted to eGFR. After the procedure: resumption according to the same modalities as the general population, whatever the CKD stage.","style":"note"},{"t":"section","text":"DOAC dosing in AF according to eGFR","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"eGFR (mL/min)","style":"head_w_c"},{"t":"p","html":"Apixaban","style":"head_w_c"},{"t":"p","html":"Rivaroxaban","style":"head_w_c"},{"t":"p","html":"Edoxaban","style":"head_w_c"},{"t":"p","html":"Dabigatran","style":"head_w_c"}],[{"t":"p","html":"≥ 50","style":"cell_c"},{"t":"p","html":"5 mg x2*","style":"cell_c"},{"t":"p","html":"20 mg/day","style":"cell_c"},{"t":"p","html":"60 mg/day","style":"cell_c"},{"t":"p","html":"150 mg x2","style":"cell_c"}],[{"t":"p","html":"30 – 49","style":"cell_c"},{"t":"p","html":"5 mg x2*","style":"cell_c"},{"t":"p","html":"15 mg/day","style":"cell_c"},{"t":"p","html":"30 mg/day","style":"cell_c"},{"t":"p","html":"110 mg x2","style":"cell_c"}],[{"t":"p","html":"15 – 29","style":"cell_c"},{"t":"p","html":"2.5 mg x2","style":"cell_c"},{"t":"p","html":"15 mg/day","style":"cell_c"},{"t":"p","html":"30 mg/day","style":"cell_c"},{"t":"p","html":"Not recommended","style":"cell_c"}],[{"t":"p","html":"< 15","style":"cell_c"},{"t":"p","html":"2.5 mg x2 (off-label)","style":"cell_c"},{"t":"p","html":"15 mg/day (off-label)","style":"cell_c"},{"t":"p","html":"Not recommended","style":"cell_c"},{"t":"p","html":"Not recommended","style":"cell_c"}]]},{"t":"p","html":"* 2.5 mg x2 for apixaban if ≥ 2 factors among: age > 80 years, weight < 60 kg, serum creatinine > 133 µmol/L.","style":"note"},{"t":"section","text":"VKA-to-heparin bridging according to CKD stage (Q10)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"CKD stage (eGFR)","style":"head_w"},{"t":"p","html":"Pre-procedural heparin bridging modalities","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Severe/end-stage<br/>(&lt; 30 mL/min)","style":"cell_b"},{"t":"p","html":"Continuous IV UFH (syringe pump) started the evening of D-3, stopped 6h before the procedure (monitoring/adjustment identical to the general population).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"","style":"cell_b"},{"t":"p","html":"Alternative (notably out-of-hospital management): calcium UFH SC 333 IU/kg the evening of D-3, then 250 IU/kg/12h, last injection the morning of D-1, without laboratory monitoring.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Severe<br/>(15-29 mL/min)","style":"cell_b"},{"t":"p","html":"LMWH as an alternative to UFH: tinzaparin 175 IU/kg x1/day OR enoxaparin 100 IU/kg x1/day — 1st injection the evening of D-3, last one the evening of D-2 (2 doses in total, no injection the day before), without laboratory monitoring.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"End-stage<br/>(&lt; 15 mL/min)","style":"cell_b"},{"t":"p","html":"Tinzaparin 175 IU/kg x1/day as an alternative to UFH — 1st injection the evening of D-3, last one the evening of D-2 (2 injections in total), without laboratory monitoring. Other LMWHs are not recommended.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"CKD stage (eGFR)","style":"head_w"},{"t":"p","html":"Post-procedural bridging (curative heparin, ideally 48-72h later)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Severe/end-stage<br/>(&lt; 30 mL/min)","style":"cell_b"},{"t":"p","html":"Curative-dose UFH, dosing regimen and monitoring identical to the general population.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Severe<br/>(15-29 mL/min)","style":"cell_b"},{"t":"p","html":"LMWH as an alternative to UFH: tinzaparin 175 IU/kg x1/day or enoxaparin 100 IU/kg x1/day.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"End-stage<br/>(&lt; 15 mL/min)","style":"cell_b"},{"t":"p","html":"Tinzaparin 175 IU/kg x1/day as an alternative to UFH, with measurement of anti-Xa activity 4 to 6h after the 3rd injection (target ≤1.5 IU/mL) — contact the reference hemostasis laboratory if exceeded.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"CKD stage (eGFR)","style":"head_w"},{"t":"p","html":"Post-procedural venous thromboprophylaxis (while awaiting curative treatment)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Severe/end-stage<br/>(&lt; 30 mL/min)","style":"cell_b"},{"t":"p","html":"Calcium heparin SC 5 000 IU x2/day.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Severe<br/>(15-29 mL/min)","style":"cell_b"},{"t":"p","html":"LMWH as an alternative to UFH: tinzaparin 4 500 IU x1/day or enoxaparin 2 000 IU x1/day.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"End-stage<br/>(&lt; 15 mL/min)","style":"cell_b"},{"t":"p","html":"Tinzaparin 4 500 IU x1/day as an alternative to UFH.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"DOACs in severe CKD (eGFR 30-49): discontinuation without bridging or assay, last dose at D-3 (anti-Xa) or D-5 (dabigatran) before a high-risk procedure (R10.3.1, GRADE 2+, Strong). eGFR &lt;30: discontinuation without bridging or assay, last dose of anti-Xa DOACs at D-5 (R10.3.2, Expert opinion, Strong). DOACs at low bleeding risk: skip the evening before + the morning whatever the CKD stage (R10.2, GRADE 2+, Strong).","style":"note"}]},{"title":"Appendix — Bleeding-risk classification by specialty","items":[{"t":"section","text":"Appendix — Bleeding-risk classification by specialty","color":"navy"},{"t":"p","html":"Faithful reproduction of the classification tables established by each learned society partnering in the RFE (source: full text, appendices p.79-116). This classification guides the choice of \"low / high / very high\" used in the discontinuation-interval tables (p.1). It may be adapted locally.","style":"note"},{"t":"section","text":"Regional anesthesia (RA)  —  Dedicated ESAIC/ESRA, ASRA recommendations","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk<br/>(no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(anticoagulant discontinuation)","style":"head_w_c"}],[{"t":"p","html":"Superficial peripheral blocks (axillary block, femoral block, popliteal sciatic block, erector spinae block...)","style":"cell"},{"t":"p","html":"Deep peripheral blocks (paravertebral block, infraclavicular block, posterior lumbar plexus block...)","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Epidural, spinal anesthesia, combined spinal-epidural (very high risk — see Q3)","style":"cell"}]]},{"t":"p","html":"Resumption of curative anticoagulation not indicated with an epidural catheter in place; possible ≥24h after its removal. No robust data to classify deep peripheral blocks as very high risk: management identical to other high-risk procedures (VKA: INR≤1.5; DOAC: D-3 excluding CKD).","style":"note"},{"t":"section","text":"Interventional radiology  —  French Federation of Interventional Radiology (FRI)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk<br/>(no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(anticoagulant discontinuation)","style":"head_w_c"}],[{"t":"p","html":"Superficial abscess punctures/drainage","style":"cell"},{"t":"p","html":"Percutaneous liver or kidney biopsy","style":"cell"}],[{"t":"p","html":"Superficial biopsies (thyroid, breast, lymph node, soft tissue)","style":"cell"},{"t":"p","html":"Deep lung/pleural biopsy under CT","style":"cell"}],[{"t":"p","html":"Placement/exchange of tunneled venous catheters / implantable port (compressible site)","style":"cell"},{"t":"p","html":"Deep bone biopsy (spine, pelvis)","style":"cell"}],[{"t":"p","html":"Removal of implantable port","style":"cell"},{"t":"p","html":"Drainage of deep abscesses (hepatic, retroperitoneal, pelvic...)","style":"cell"}],[{"t":"p","html":"Diagnostic phlebography / cavography without thrombolysis","style":"cell"},{"t":"p","html":"Percutaneous nephrostomy","style":"cell"}],[{"t":"p","html":"Placement / removal of vena cava filter","style":"cell"},{"t":"p","html":"Percutaneous (transhepatic) biliary drainage","style":"cell"}],[{"t":"p","html":"Peripheral joint infiltration","style":"cell"},{"t":"p","html":"Therapeutic arterial embolization (hemorrhage, TACE, fibroids, prostate...)","style":"cell"}],[{"t":"p","html":"Spinal infiltration if posterior articular","style":"cell"},{"t":"p","html":"Splenic embolization","style":"cell"}],[{"t":"p","html":"Simple angioplasty of hemodialysis fistula (without prolonged thrombolysis)","style":"cell"},{"t":"p","html":"Complex portal procedures (TIPS, portal puncture, recanalization)","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Percutaneous tumor ablations (RFA, MWA, cryoablation)","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Endovascular thrombolysis / thrombectomy","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Vertebroplasty/kyphoplasty, peripheral bone consolidation","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Spinal infiltration if epidural — very high risk*","style":"cell"}]]},{"t":"p","html":"* Procedures at risk of severe neurological complication: preferably INR≤1.2 (VKA) or zero DOAC concentration (last dose at D-5).","style":"note"},{"t":"section","text":"Rheumatology — percutaneous musculoskeletal procedures  —  French Society of Rheumatology (SFR)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk<br/>(no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(anticoagulant discontinuation)","style":"head_w_c"}],[{"t":"p","html":"Posterior joint puncture-infiltration*","style":"cell"},{"t":"p","html":"Hip (coxofemoral) joint puncture-infiltration","style":"cell"}],[{"t":"p","html":"Infiltration of the medial branch of the posterior ramus*","style":"cell"},{"t":"p","html":"Trituration of a peripheral joint","style":"cell"}],[{"t":"p","html":"Peripheral joint puncture-infiltration other than coxofemoral","style":"cell"},{"t":"p","html":"Superficial blind canal infiltration","style":"cell"}],[{"t":"p","html":"Sacroiliac infiltration","style":"cell"},{"t":"p","html":"IM injection including botulinum toxins, deep site (e.g. gluteal)","style":"cell"}],[{"t":"p","html":"Periarticular infiltrations","style":"cell"},{"t":"p","html":"Digital aponeurotomy","style":"cell"}],[{"t":"p","html":"Superficial guided canal infiltration","style":"cell"},{"t":"p","html":"Synovial, temporal artery, muscle, bone biopsy","style":"cell"}],[{"t":"p","html":"Pulley infiltration","style":"cell"},{"t":"p","html":"Lumbar puncture, blood patch, epidural spinal infiltration†","style":"cell"}],[{"t":"p","html":"Subcutaneous injection","style":"cell"},{"t":"p","html":"Radiofrequency neurotomy†","style":"cell"}],[{"t":"p","html":"Intramuscular injection (including botulinum toxin) superficial site","style":"cell"},{"t":"p","html":"Vertebroplasty/kyphoplasty†","style":"cell"}],[{"t":"p","html":"Acupuncture","style":"cell"},{"t":"p","html":"Disco-vertebral puncture-biopsy†","style":"cell"}],[{"t":"p","html":"Palmar aponeurotomy","style":"cell"},{"t":"p","html":"Deep canal infiltration†","style":"cell"}],[{"t":"p","html":"Accessory salivary gland biopsy","style":"cell"},{"t":"p","html":"","style":"cell"}]]},{"t":"p","html":"* to be adjusted according to the patient's morphology. † procedures to be considered at very high bleeding risk (possible severe neurological complication).","style":"note"},{"t":"section","text":"Cardiac invasive procedures  —  French Society of Cardiology (SFC)","color":"navy"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Particularity:</b> certain cardiac procedures (endocavitary ablation for flutter/AF, pacemakers/defibrillators, TriClip) are performed <b>without discontinuing anticoagulants</b> (DOAC: no dose the morning and the day before; VKA: in the therapeutic range) because the peri-procedural thrombotic risk is directly increased.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Without discontinuing anticoagulants","style":"head_w_c"},{"t":"p","html":"Anticoagulant discontinuation (hemostasis correction)","style":"head_w_c"}],[{"t":"p","html":"Endocavitary catheter ablation for flutter and AF (supraventricular)","style":"cell"},{"t":"p","html":"Endocavitary catheter ablation other than atrial arrhythmias","style":"cell"}],[{"t":"p","html":"Electrophysiological studies","style":"cell"},{"t":"p","html":"Epicardial arrhythmia ablation","style":"cell"}],[{"t":"p","html":"Percutaneous coronary intervention","style":"cell"},{"t":"p","html":"Extravascular defibrillators (subcostal approach)","style":"cell"}],[{"t":"p","html":"Pacemakers and defibrillators of all types","style":"cell"},{"t":"p","html":"Electrical cardioversion","style":"cell"}],[{"t":"p","html":"Percutaneous tricuspid repair (TriClip)","style":"cell"},{"t":"p","html":"Percutaneous mitral repair (MitraClip)","style":"cell"}],[{"t":"p","html":"Percutaneous tricuspid valve replacement (TTVR)","style":"cell"},{"t":"p","html":"Percutaneous aortic valve replacement (TAVI, all approaches)","style":"cell"}],[{"t":"p","html":"Percutaneous closure of patent foramen ovale","style":"cell"},{"t":"p","html":"Percutaneous mitral valve replacement (TMVR)","style":"cell"}],[{"t":"p","html":"Percutaneous closure of atrial septal defect","style":"cell"},{"t":"p","html":"Percutaneous closure of ventricular septal defect","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Percutaneous closure of paravalvular leak","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Endomyocardial biopsy","style":"cell"}]]},{"t":"p","html":"TAVI: the POPular PAUSE TAVI trial showed the superiority of pre-procedural interruption (DOAC D-2, VKA D-3/D-5) with resumption the same day in the absence of vascular complication. Left atrial appendage closure: see indication (often a definitive contraindication to anticoagulants).","style":"note"},{"t":"section","text":"Thoracic and cardiovascular surgery  —  SFCTCV & French Society of Vascular and Endovascular Surgery (SCVE)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"","style":"cell_b"},{"t":"p","html":"Low risk<br/>(DOAC: no dose morning/day before — VKA: therapeutic range)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(discontinuation for hemostasis correction)","style":"head_w_c"}],[{"t":"p","html":"Thoracic surgery","style":"cell_b"},{"t":"p","html":"All procedures (including chest tube placement)","style":"cell"},{"t":"p","html":"—","style":"cell"}],[{"t":"p","html":"Cardiac surgery","style":"cell_b"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"All procedures under CPB. Placement of epicardial pacemaker/ICD, lead change, removal of steel wires, reoperation of the Scarpa area (false aneurysm)","style":"cell"}],[{"t":"p","html":"Vascular and endovascular surgery","style":"cell_b"},{"t":"p","html":"Superficial and deep endovenous procedures, minor amputations, embolizations","style":"cell"},{"t":"p","html":"All open venous and arterial surgery, endovascular treatment of abdominal aortic aneurysms, peripheral arterial angioplasties, hemodialysis access","style":"cell"}]]},{"t":"p","html":"CPB: cardiopulmonary bypass. Resumption of curative anticoagulation after vascular surgery to be adjusted: earlier after distal peripheral bypasses, later in case of extensive dissections or redo approaches (Scarpa).","style":"note"},{"t":"section","text":"Oral surgery — classification of procedures  —  French Society of Oral Surgery (SFCO)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Procedures","style":"head_w"},{"t":"p","html":"Preventive measures","style":"head_w"}],[{"t":"p","html":"No risk","style":"cell_b"},{"t":"p","html":"Local anesthesia, scaling, periodontal debridement","style":"cell"},{"t":"p","html":"Simple hemostasis by compression","style":"cell"}],[{"t":"p","html":"Low risk","style":"cell_b"},{"t":"p","html":"Simple extraction, multiple extractions ≤2 quadrants (1 side), implants with flap 1 quadrant, sinus lift by crestal approach, implant uncovering, incision/drainage, biopsy","style":"cell"},{"t":"p","html":"Conventional surgical hemostasis*, tranexamic acid, minimally invasive surgery, flapless/navigated","style":"cell"}],[{"t":"p","html":"High risk","style":"cell_b"},{"t":"p","html":"Multiple extractions >2 quadrants, impacted tooth/teeth, multiple/zygomatic implants, sinus lift by lateral approach, onlay bone grafts, pre-orthodontic surgery of an impacted tooth, salivary lithiasis surgery, benign oral mucosal tumors, periapical endodontic bone surgery, closure of oro-antral communication, gingivectomy","style":"cell"},{"t":"p","html":"Same measures + blood derivatives (fibrinogen/thrombin), electrocoagulation, CBCT for position of the alveolar-antral artery","style":"cell"}],[{"t":"p","html":"Not advised","style":"cell_b"},{"t":"p","html":"Unilateral inferior alveolar block; autologous symphyseal graft (prefer heterologous/synthetic)","style":"cell"},{"t":"p","html":"Control aspiration imperative in case of RA","style":"cell"}],[{"t":"p","html":"Contraindicated","style":"cell_b"},{"t":"p","html":"Hemorrhagic procedures if technical platform/experience insufficient; bilateral inferior alveolar block (lateropharyngeal hematoma); symphyseal harvesting (floor-of-mouth hematoma)","style":"cell"},{"t":"p","html":"—","style":"cell"}]]},{"t":"p","html":"* mechanical hemostasis + sutures + resorbable local hemostatics ± synthetic glue, tranexamic acid 10% mouthwash. Maxillary bone tissue often allows DOAC/VKA/antiplatelet agents (AAP) to be maintained with reinforced local hemostasis.","style":"note"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Practical management (2026 update vs 2015):</b> No-risk and low-risk procedures → continue VKA (INR≤4) and DOACs without skipping a dose (segment the interventions if possible; if an additional bleeding risk factor on DOAC, skip the evening before + the morning). High-risk procedures → DOAC/VKA interruption mandatory; <b>proposed DOAC protocol</b>: last dose at D-3 excluding CKD (D-5 if dabigatran and GFR&lt;50, or apixaban/rivaroxaban and GFR&lt;30), resumption at 48-72h. VKA: 2015 recommendations unchanged. Multidisciplinary discussion if both bleeding and thrombotic risk are high.","style":"body_sm"}},{"t":"section","text":"ENT surgery — classification by subspecialty  —  French Society of ENT and Head and Neck Surgery (SFORL)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Subspecialty","style":"head_w"},{"t":"p","html":"Low risk (no discontinuation)","style":"head_w"},{"t":"p","html":"High risk (anticoagulant discontinuation)","style":"head_w"}],[{"t":"p","html":"Otology","style":"cell_b"},{"t":"p","html":"Examination under GA, foreign body removal, transtympanic tube (ATT), myringotomy, bone-anchor abutment placement","style":"cell"},{"t":"p","html":"Otoplasty, meatoplasty/canaloplasty, tympanic membrane surgery, ossicular chain, cholesteatoma, cochlear/middle-ear/bone-anchored implants, petrosectomies*, endolymphatic sac surgery*, paragangliomas*, trans-labyrinthine*/retrosigmoid*/supra-petrous* approaches","style":"cell"}],[{"t":"p","html":"Rhinology","style":"cell_b"},{"t":"p","html":"Nasal cavity endoscopy without biopsy, radiofrequency/coblation turbinoplasty, placement of subcutaneous nasal valve implant, reduction of nasal bone fracture, removal of intranasal foreign body, nasal fossa lesion biopsy, posterior nasal cryotherapy","style":"cell"},{"t":"p","html":"Turbinoplasty with microdebrider/scissors, removal of adenoids by endonasal approach, meatotomy, medial maxillectomy, sphenoidotomy, ethmoidectomy, frontal sinus surgery, intranasal polypectomy, septoplasty, rhinoseptoplasty, drainage of septal abscess, closure of septal perforation, correction of nasal valve, sclerotherapy (Osler-Rendu), intranasal cauterization, ligation of sphenopalatine/ethmoidal artery, closure of endonasal meningeal breach, skull base/sinonasal tumor surgery","style":"cell"}],[{"t":"p","html":"Laryngology","style":"cell_b"},{"t":"p","html":"Suspension laryngoscopy with simple biopsy, limited endoscopic excision of a benign lesion, endolaryngeal injection (excluding abdominal fat), simple laryngotracheal dilatation, endoscopic Wendler laryngoplasty","style":"cell"},{"t":"p","html":"Laryngeal injection with abdominal fat harvesting, voice feminization laryngoplasty by external approach","style":"cell"}],[{"t":"p","html":"Head and neck oncology","style":"cell_b"},{"t":"p","html":"Panendoscopy of the upper aerodigestive tract (UADT), Zenker's diverticulum by endoscopic approach, simple lymphadenectomy, urgent tracheotomy (to be discussed)","style":"cell"},{"t":"p","html":"Oncologic surgery without reconstruction* (partial*/total* laryngectomy, pharyngolaryngectomy*, oropharyngectomy*, base-of-tongue resection*, glossectomy*, floor-of-mouth resection (pelvectomy)*, maxillectomy*...), surgery with free/pedicled flap*, neck dissection*, tracheotomy, salivary gland surgery, thyroidectomy/parathyroidectomy, thyroglossal duct cyst, cervicotomy, Zenker's diverticulum by cervicotomy, Adam's apple reduction","style":"cell"}],[{"t":"p","html":"Sleep","style":"cell_b"},{"t":"p","html":"Endoscopy under induced sleep","style":"cell"},{"t":"p","html":"Tonsillectomy, velar surgery, expansion pharyngoplasty, base-of-tongue resection (endoscopic/robotic), partial epiglottectomy, orthognathic surgery","style":"cell"}],[{"t":"p","html":"Pediatric ENT","style":"cell_b"},{"t":"p","html":"Transtympanic tube (ATT), subcutaneous dermoid cysts, endoscopic laryngeal surgery in children","style":"cell"},{"t":"p","html":"Tonsillectomy*, adenoidectomy*, external-approach surgery of the larynx/trachea in children, nasopharyngeal angiofibromas*, external-approach orbitotomy, thyroglossal duct cyst (KTT), lymphatic malformations, branchial cysts/fistulas","style":"cell"}]]},{"t":"p","html":"* Particular situations at very high risk: delayed resumption at 72h and/or short-half-life/reversible anticoagulant as bridging. Tonsillectomy/adenoidectomy: delayed postoperative bleeding risk (1-2% of cases, severe forms possible).","style":"note"},{"t":"section","text":"Endoscopic procedures  —  French Society of Digestive Endoscopy (SFED)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk<br/>(no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(anticoagulant discontinuation)","style":"head_w_c"}],[{"t":"p","html":"Diagnostic procedures ± biopsies#","style":"cell"},{"t":"p","html":"Polypectomy / mucosectomy / submucosal dissection","style":"cell"}],[{"t":"p","html":"Biliary or pancreatic stents","style":"cell"},{"t":"p","html":"ERCP with sphincterotomy","style":"cell"}],[{"t":"p","html":"Diagnostic endoscopic ultrasound","style":"cell"},{"t":"p","html":"Ampullectomy*","style":"cell"}],[{"t":"p","html":"Simple/double-balloon enteroscopy without polypectomy","style":"cell"},{"t":"p","html":"Endoscopic ultrasound with biopsy","style":"cell"}],[{"t":"p","html":"Placement of esophageal, enteral or colonic stent","style":"cell"},{"t":"p","html":"Therapeutic endoscopic ultrasound","style":"cell"}],[{"t":"p","html":"Percutaneous gastrostomy","style":"cell"},{"t":"p","html":"Dilatation of strictures","style":"cell"}],[{"t":"p","html":"Esophageal radiofrequency","style":"cell"},{"t":"p","html":"Treatment of varices","style":"cell"}],[{"t":"p","html":"Argon plasma coagulation (APC)","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Spiral enteroscopy","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Treatment of postoperative fistulas","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Endoscopic necrosectomy","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"POEM","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Endoscopic gastroplasty","style":"cell"},{"t":"p","html":"","style":"cell"}]]},{"t":"p","html":"# Any colonoscopy must be considered as potentially hemorrhagic (high frequency of polyps). * With the exception of ampullectomy, endoscopic procedures (even high-risk) can be performed under aspirin.","style":"note"},{"t":"section","text":"Visceral surgery  —  SFCD, ACHBPT, SOFFCO-MM, SFCP-CH","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Society","style":"head_w"},{"t":"p","html":"Low risk","style":"head_w"},{"t":"p","html":"High risk","style":"head_w"}],[{"t":"p","html":"SFCD (digestive surgery)","style":"cell_b"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Benign and malignant colorectal surgery; benign and malignant esophagogastric surgery","style":"cell"}],[{"t":"p","html":"ACHBPT (hepato-bilio-pancreatic)","style":"cell_b"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Hepatectomy, pancreatectomy, cholecystectomy, liver or pancreas transplantation","style":"cell"}],[{"t":"p","html":"SOFFCO-MM (obesity surgery)","style":"cell_b"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Gastric band, sleeve, Roux-en-Y/omega bypass, biliopancreatic diversion + duodenal switch, Nissen-Sleeve, SADI-S, transit bipartition, endo-sleeve, any revision of bariatric surgery","style":"cell"}],[{"t":"p","html":"SFCP-CH (abdominal wall surgery)","style":"cell_b"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Hernia repair (inguinal, femoral, umbilical, linea alba), incisional hernia, evisceration","style":"cell"}]]},{"t":"p","html":"All these procedures are classified as high bleeding risk (anticoagulant discontinuation). Particularities: hepatectomy with prosthetic vascular reconstruction → discuss early anticoagulation. Pancreatic transplantation → continuous IV heparin 72h. Abdominal wall surgery (complex hernia/incisional hernia) → delay curative resumption to 48h (high thromboembolic risk, e.g. mechanical valve) or 72h (lower risk) because of the risk of abdominal wall hematoma (3.6% in a series of 3384 patients).","style":"note"},{"t":"section","text":"Proctologic surgery  —  French National Society of Coloproctology (SNFCP)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low (can be performed under effective anticoagulation)","style":"head_w_c"},{"t":"p","html":"High (curative resumption at 48-72h)","style":"head_w_c"},{"t":"p","html":"Exceptional (delayed resumption >72h, or different drug)","style":"head_w_c"}],[{"t":"p","html":"Formalin application (formolisation)","style":"cell"},{"t":"p","html":"Electrocoagulation of extensive condylomatosis","style":"cell"},{"t":"p","html":"Hemorrhoid surgery (any technique)","style":"cell"}],[{"t":"p","html":"Incision of superficial abscess","style":"cell"},{"t":"p","html":"Fissurectomy with or without anoplasty","style":"cell"},{"t":"p","html":"Transanal excision of rectal tumor","style":"cell"}],[{"t":"p","html":"Gluing of a fistula tract","style":"cell"},{"t":"p","html":"Excision of pilonidal sinus","style":"cell"},{"t":"p","html":"Drainage of a complex suppuration","style":"cell"}],[{"t":"p","html":"Electrocoagulation of limited condylomatosis","style":"cell"},{"t":"p","html":"Laser/radiofrequency treatment of pilonidal sinus","style":"cell"},{"t":"p","html":"Surgery involving extensive skin resections","style":"cell"}],[{"t":"p","html":"Laser/radiofrequency treatment of anal fistula","style":"cell"},{"t":"p","html":"","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Drainage and/or laying open of a low anal fistula","style":"cell"},{"t":"p","html":"","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Sphincter-sparing surgery (rectal advancement flap FLAP; intersphincteric ligation LIFT)","style":"cell"},{"t":"p","html":"","style":"cell"},{"t":"p","html":"","style":"cell"}]]},{"t":"p","html":"This whole classification is based on expert agreements. Hemorrhoid surgery: very prolonged bleeding risk (delayed bleeding from eschar separation up to D20, overall incidence 6-8%). VKA: bleeding rate 23% vs 4% without anticoagulant (RR=5.8). DOAC: marked excess risk if resumed before D15 (33% vs 8%); increased bleeding risk in case of bridging with LMWH. In patients at low thromboembolic risk, late resumption (>D15) or bridging at preventive dose limits complications.","style":"note"},{"t":"section","text":"Gynecologic procedures  —  French National College of Gynecologists and Obstetricians (CNGOF)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk<br/>(no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(anticoagulant discontinuation)","style":"head_w_c"}],[{"t":"p","html":"Diagnostic hysteroscopy, polyps, synechiae, septum, endometrial thermocoagulation, IUD removal","style":"cell"},{"t":"p","html":"Endoscopic vaginal surgery: fibroid resection","style":"cell"}],[{"t":"p","html":"Superficial puncture (lymphocele...)","style":"cell"},{"t":"p","html":"All vaginal/vulvar surgeries: hysterectomies, prolapse, TOT/TVT incontinence, fistula, vulvar plasties, genital mutilation, conization, cervical amputation","style":"cell"}],[{"t":"p","html":"Drainage of superficial abscesses (Bartholinitis, breast abscess)","style":"cell"},{"t":"p","html":"Exploratory laparoscopy#","style":"cell"}],[{"t":"p","html":"Salpingectomy by laparoscopy (especially 3-5mm trocar)#","style":"cell"},{"t":"p","html":"Laparoscopic surgery: hysterectomy, cystectomy, endometriosis, adnexectomy","style":"cell"}],[{"t":"p","html":"Biopsy of cervix, endometrium, vulva, breast*","style":"cell"},{"t":"p","html":"Abdominal-approach surgeries / laparotomies (hysterectomies...)","style":"cell"}],[{"t":"p","html":"Treatment of incontinence with bulking agents, botulinum toxin","style":"cell"},{"t":"p","html":"Breast surgery: partial mastectomies/sentinel node, internal mammary chain dissections (RMI), lipomodelling...","style":"cell"}],[{"t":"p","html":"Breast procedure under local anesthesia, superficial low-risk lumpectomy","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Skin lesion*","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Percutaneous implantable port (CIP)*","style":"cell"},{"t":"p","html":"","style":"cell"}]]},{"t":"p","html":"* Skin/breast biopsies/CIP/trocar orifices may require compression. # No clear consensus: rather discontinuation of anticoagulants for all laparoscopies, but salpingectomy with 3-5mm trocars rather classified as low risk.","style":"note"},{"t":"section","text":"Urologic procedures  —  French Association of Urology (AFU)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk (no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk (discontinuation — resumption 48-72h)","style":"head_w_c"}],[{"t":"p","html":"Urethral catheterization","style":"cell"},{"t":"p","html":"Abdominal or retroperitoneal surgery (open or laparoscopic — includes AVH [adénomectomie par voie haute] and kidney transplantation)","style":"cell"}],[{"t":"p","html":"Intravesical instillations","style":"cell"},{"t":"p","html":"Vaginal-approach surgery (incontinence/prolapse)","style":"cell"}],[{"t":"p","html":"Intracavernous injections","style":"cell"},{"t":"p","html":"Perineal-approach surgery (urethra, penectomy, male sphincter, penile implant...)","style":"cell"}],[{"t":"p","html":"Cystostomy change","style":"cell"},{"t":"p","html":"Scrotal or inguinal surgery (including vasectomy)","style":"cell"}],[{"t":"p","html":"Change of nephrostomy tube","style":"cell"},{"t":"p","html":"Percutaneous nephrostomy#","style":"cell"}],[{"t":"p","html":"Placement/change of JJ stent","style":"cell"},{"t":"p","html":"Percutaneous nephrolithotomy (PCNL)","style":"cell"}],[{"t":"p","html":"Placement/change of ureteral catheter","style":"cell"},{"t":"p","html":"Ureteroscopy#","style":"cell"}],[{"t":"p","html":"Removal of JJ stent","style":"cell"},{"t":"p","html":"Extracorporeal lithotripsy","style":"cell"}],[{"t":"p","html":"Urethrocystoscopy","style":"cell"},{"t":"p","html":"Drainage of a deep collection#","style":"cell"}],[{"t":"p","html":"Drainage of a superficial collection","style":"cell"},{"t":"p","html":"Transrectal prostate biopsy","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Transperineal prostate biopsy*","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Kidney biopsy","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"TURB/TURP/bladder-neck incision","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Prostate enucleation","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Prostate photovaporization*","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Minimally invasive treatments of BPH","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Sacral root neuromodulation","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Intradetrusor injection of botulinum toxin","style":"cell"}]]},{"t":"p","html":"* Value of discontinuation less certain, to be discussed case by case. # Approach may differ in emergency situations. Resumption possibly delayed beyond 48-72h if: persistent hematuria, PCNL with multiple punctures/bleeding, uncontrolled bleeding — discuss a surgical procedure to allow resumption. Resumption to be considered at the latest at 3 weeks in the absence of rebleeding.","style":"note"},{"t":"section","text":"Plastic, reconstructive and aesthetic surgery  —  French Society of Plastic Surgery (SoFCPRE)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Low risk<br/>(no discontinuation)","style":"head_w_c"},{"t":"p","html":"High risk<br/>(anticoagulant discontinuation)","style":"head_w_c"}],[{"t":"p","html":"Dermatologic surgery with excision-suture without skin graft or flap*","style":"cell"},{"t":"p","html":"Plastic and reconstructive surgery of the face, breast or silhouette#","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Skin graft","style":"cell"}],[{"t":"p","html":"","style":"cell"},{"t":"p","html":"Flaps","style":"cell"}]]},{"t":"p","html":"* Outpatient management is not recommended; hospitalization preferable for monitoring. # Post-procedural resumption most often with curative-dose heparins, with delayed resumption of oral anticoagulants. The benefit-risk balance must be systematically positive in aesthetic surgery.","style":"note"},{"t":"section","text":"Orthopedic surgery — classification by subspecialty (1/2)  —  SOFCOT, SFA, SFCR, GSF-GETO, SFHG, SFCM","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Subspecialty","style":"head_w"},{"t":"p","html":"Low risk","style":"head_w"},{"t":"p","html":"High risk","style":"head_w"}],[{"t":"p","html":"Tumors","style":"cell_b"},{"t":"p","html":"Percutaneous biopsies# (Tru-Cut/trocar under ultrasound or CT guidance)","style":"cell"},{"t":"p","html":"Open biopsy, all resection procedures; osteomedullary biopsies","style":"cell"}],[{"t":"p","html":"Spine","style":"cell_b"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"All arthrodesis/canal release surgeries (cervical, thoracic, lumbar), expansion surgery, cementoplasty/vertebroplasty, placement of cranial halo£","style":"cell"}],[{"t":"p","html":"Hip and knee","style":"cell_b"},{"t":"p","html":"Hip puncture or infiltration*","style":"cell"},{"t":"p","html":"All hip and knee surgeries","style":"cell"}]]},{"t":"p","html":"# Biopsies for suspected renal/thyroid metastasis or on an aneurysmal lesion on MRI: often high risk. * Expert opinion. £ Extradural hematomas reported during halo placement (inner table perforation).","style":"note"},{"t":"section","text":"Orthopedic surgery — classification by subspecialty (2/2)  —  SOFCOT, SFA, SFCR, GSF-GETO, SFHG, SFCM","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Subspecialty","style":"head_w"},{"t":"p","html":"Low risk","style":"head_w"},{"t":"p","html":"High risk","style":"head_w"}],[{"t":"p","html":"Arthroscopy — Shoulder","style":"cell_b"},{"t":"p","html":"Diagnostic arthroscopy, subacromial decompression/biceps tenotomy, synovectomy","style":"cell"},{"t":"p","html":"Rotator cuff repair, bone or capsulolabral stabilization surgery","style":"cell"}],[{"t":"p","html":"Arthroscopy — Hip","style":"cell_b"},{"t":"p","html":"Diagnostic arthroscopy, synovectomy","style":"cell"},{"t":"p","html":"Capsulotomy, bone or cartilage procedures","style":"cell"}],[{"t":"p","html":"Arthroscopy — Knee","style":"cell_b"},{"t":"p","html":"Diagnostic arthroscopy, simple meniscectomy","style":"cell"},{"t":"p","html":"Ligamentoplasty, multiligament repair, microfractures/cartilage procedures, synovectomy","style":"cell"}],[{"t":"p","html":"Arthroscopy — Ankle","style":"cell_b"},{"t":"p","html":"Diagnostic arthroscopy","style":"cell"},{"t":"p","html":"Ligamentoplasty, microfractures/cartilage procedures, synovectomy","style":"cell"}],[{"t":"p","html":"Hand","style":"cell_b"},{"t":"p","html":"Hand surgery@, carpal tunnel (any technique), digital cysts, digital/nail lesions, trigger finger, digital surgeries","style":"cell"},{"t":"p","html":"Dupuytren, ulnar nerve transposition, lunate/scaphoid grafts or other major bone procedure (osteotomy, curettage/graft)","style":"cell"}]]},{"t":"p","html":"@ For VKA, ideally prefer an INR≤2. Resumption of curative anticoagulation: 48-72h for tumors and arthroscopy (expert opinion, extrapolated from general surgery).","style":"note"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Spine — resumption of anticoagulation:</b> fragile and heterogeneous data. A Swiss cohort (332 patients on VKA) showed a x3.4 risk of postoperative bleeding (mainly extraspinal hematomas 3.3% vs 0.6%), increased in case of mechanical valve or aPTT prolongation on D1-D2. Conversely, resumption of DOACs after D3 was associated with 5% thromboembolic events. <b>Overall: individualized resumption between D3 and D7</b> according to the thrombotic/bleeding risk profile; in case of high bleeding risk, resumption with LMWH and delayed bridging to oral anticoagulants.","style":"body_sm"}},{"t":"section","text":"Neurosurgery  —  French Society of Neurosurgery (SFNC)","color":"navy"},{"t":"panel","tone":"crit","content":{"t":"p","html":"<b>Absolute principle:</b> no scheduled neurosurgical procedure is performed under curative anticoagulation — not even a neurostimulator generator change. The bleeding risk of any neurosurgical procedure is <b>high or very high</b>, never low.","style":"body"}},{"t":"table","rows":[[{"t":"p","html":"Low risk","style":"head_w_c"},{"t":"p","html":"High risk","style":"head_w_c"},{"t":"p","html":"Very high risk (optimal hemostasis required)","style":"head_w_c"}],[{"t":"p","html":"None (0)","style":"cell"},{"t":"p","html":"Spine surgery without dural opening","style":"cell"},{"t":"p","html":"Spine surgery with dural opening or cranial surgery, glial tumor resection, vestibular schwannoma resection (cerebellopontine angle), intracanal (spinal canal) cervical meningioma resection, ventriculoperitoneal shunt, placement of SEEG electrodes","style":"cell"}]]},{"t":"p","html":"SEEG: stereo-electroencephalography. For very high risk (any cranial surgery + spine with dural opening): target INR≤1.2 (VKA) or last DOAC dose at D-5 — intervals extended compared with the standard scheme (Q3, p.1). Surgery without dural opening: management identical to standard high risk (VKA INR≤1.5; DOAC D-3 excluding CKD).","style":"note"},{"t":"p","html":"Resumption: intracranial surgery most often around D10. Spine surgery: see orthopedic data above (individualized resumption D3-D7, LMWH bridging if high bleeding risk).","style":"note"}]},{"title":"Particular situations & sources","items":[{"t":"section","text":"Peri-procedural stroke (Q9)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"9.1","style":"cell_b"},{"t":"p","html":"If peri-procedural stroke is suspected: urgent brain imaging (parenchyma + vessels); contact a neurovascular team (reperfusion possible up to 24h); supine position, NO antithrombotic before imaging; respect hypertension up to 220/120 mmHg.","style":"cell"},{"t":"chip","label":"1+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"9.2","style":"cell_b"},{"t":"p","html":"After ischemic stroke in a patient with arterial thromboembolic disease (e.g. AF): resume curative anticoagulation with DOAC within 4 days, or within 48h if minor stroke.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"Long-term left ventricular assist device — LVAD (Q8)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"8.1","style":"cell_b"},{"t":"p","html":"VKA + curative resumption possible at 24-48h: DO NOT interrupt VKA; temporary reversal with PCC alone (without vitamin K), dose according to pre-procedure INR for a target INR &lt;1.5 (~20 IU/kg); resume VKA the same evening at the usual dose without heparin bridging; daily INR check until target (2-3).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"8.2","style":"cell_b"},{"t":"p","html":"Other cases at high bleeding risk: stop VKA, pre-procedural bridging with curative-dose LMWH (1st injection evening of D-3, last one at the latest the morning of D-1, without anti-Xa monitoring); resumption of VKA within the first 24 hours, without post-procedural heparin bridging.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"section","text":"Extreme weight (Q11)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Agreement","style":"head_w_c"}],[{"t":"p","html":"11.1","style":"cell_b"},{"t":"p","html":"Weight ≥ 100 kg requiring peri-procedural bridging: use curative-dose LMWH without laboratory monitoring as first-line; UFH only as second-line.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"11.2","style":"cell_b"},{"t":"p","html":"Weight ≥ 100 kg on LMWH: do not exceed the doses recommended for 100 kg — e.g. 18 000 IU x1/day (tinzaparin, dalteparin, nadroparin) or 10 000 IU x2/day (enoxaparin).","style":"cell"},{"t":"chip","label":"AE"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"11.3","style":"cell_b"},{"t":"p","html":"Weight ≥ 100 kg on curative continuous IV UFH: start at a reduced dose compared with the usual regimen (e.g. 1500 IU/h i.e. 36 000 IU/day whatever the weight), then adapt as in the general population.","style":"cell"},{"t":"chip","label":"AE"},{"t":"p","html":"Strong","style":"cell_c"}],[{"t":"p","html":"11.4","style":"cell_b"},{"t":"p","html":"Weight &lt; 50 kg requiring peri-procedural bridging: curative-dose LMWH as first-line, adjusted to weight according to the SmPC; UFH as second-line.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Strong","style":"cell_c"}]]},{"t":"p","html":"DOACs and VKA: prescribed according to the same dosing/monitoring modalities as the general population whatever the weight or BMI (except DOAC dosing according to SmPC if &lt;50 kg).","style":"note"},{"t":"panel","tone":"crit","content":{"t":"p","html":"<b>On-call points of vigilance:</b><br/>&bull; Never perform a neuraxial or neurosurgical procedure without having checked the discontinuation interval AND, in case of doubt (CKD, extreme weight, dabigatran), without measuring the residual concentration if available.<br/>&bull; Vitamin K: prefer the oral route (anaphylactic risk described with IV, rare but severe).<br/>&bull; Any complex VTE situation (APS, CTEPH, HIT, recurrence on treatment) requires multidisciplinary advice before any decision on discontinuation/bridging.<br/>&bull; To classify the bleeding risk of a specific procedure (ENT, orthopedics, visceral, neurosurgery...), see the specialty appendix above, reproduced from the full text (p.79-116).","style":"body"}},{"t":"section","text":"Sources and traceability","color":"grey"},{"t":"p","html":"<b>Source document:</b> Formalized Expert Recommendations (RFE) \"Management of anticoagulants for a scheduled invasive procedure\" (\"Gestion des anticoagulants pour une procédure invasive programmée\"). Coordinated by the Perioperative Hemostasis Interest Group (Groupe d'Intérêt en Hémostase Péri-Opératoire, GIHP), in collaboration with the French Society of Anesthesia and Intensive Care and Perioperative Medicine (SFAR) and 25 other learned societies (SFC, SFMV, SFNV, SFTH, SFNDT, INNOVTE, SFPT, SFCO, SFED, SFCD, ACHBPT, SOFFCO-MM, SFCP-CH, SNFCP, AFU, CNGOF, FRI, SFR, SOFCOT, SFA, SFCM, SFHG, GSF-GETO, SFCR, SFNC, SFORL, SoFCPRE, SFCTCV, SCVE).","style":"source"},{"t":"p","html":"<b>Main authors:</b> A. Godier, A. Mansour, S. Motte, S. Roullet, B. Iung, P. Albaladejo, P. Mismetti et al.","style":"source"},{"t":"p","html":"<b>Version:</b> 20 April 2026 — Validated by the SFAR Board of Directors on 18 March 2026.","style":"source"},{"t":"p","html":"<b>Methodology:</b> GRADE (overall level of evidence + strength of recommendation via vote, strong agreement if ≥70% agreement and <20% opposition).","style":"source"},{"t":"p","html":"<b>Source URL:</b> https://sfar.org/wp-content/uploads/2026/04/RFE-20.4.2026-deifinitif-et-validei.pdf","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this document is an independent summary fiche, produced as a memory aid for on-call situations. It reproduces all the graded recommendations and the specialty classification tables of the RFE, but does not replace the full text (detailed rationale, ~180 complete bibliographic references) and is neither published nor validated by the SFAR. In case of doubt or complex situation, refer to the full text and/or to a specialist opinion (hemostasis, cardiology, surgical specialty concerned).","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"2.2","grade":"2+","fr":"AOD (apixaban, dabigatran, édoxaban, rivaroxaban) : sauter la prise de la veille au soir ET celle du matin de la procédure (quel que soit le schéma), reprise aux doses habituelles ≥ 6h après le geste.","en":"DOACs (apixaban, dabigatran, edoxaban, rivaroxaban): skip the dose of the evening before AND that of the morning of the procedure (whatever the regimen), resume at usual doses ≥ 6h after the procedure."},{"ref":"AOD anti-Xa (apixaban, édoxaban, rivaroxaban)","ref_en":"Anti-Xa DOACs (apixaban, edoxaban, rivaroxaban)","grade":"2+","fr":"J-3 si fonction rénale normale ; J-5 si risque hémorragique très élevé (neurochirurgie intracrânienne, neuraxial)","en":"D-3 if normal renal function; D-5 if very high bleeding risk (intracranial neurosurgery, neuraxial)"},{"ref":"5.2","grade":"1-","fr":"Sans ATCD d'AVC/AIT/embolie systémique : PAS de relais héparinique pré-procédural.","en":"Without history of stroke/TIA/systemic embolism: NO pre-procedural heparin bridging."},{"ref":"6.1","grade":"2+","fr":"Relais pré-procédural systématique par HBPM dose curative 2x/j (1ère inj. soir J-3, dernière matin J-1), sans contrôle anti-Xa.","en":"Systematic pre-procedural bridging with curative-dose LMWH twice daily (1st injection evening of D-3, last one morning of D-1), without anti-Xa monitoring."},{"ref":"7.15","grade":"1-","fr":"Contentions élastiques graduées : NON recommandées quel que soit le risque thromboembolique.","en":"Graduated elastic compression stockings: NOT recommended whatever the thromboembolic risk."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER (provenance) : contrairement aux fiches 2026 récentes, cette fiche n'a ni script de construction (build/fiche_anticoagulants.py absent) ni texte source dans sources/ : la traduction anglaise a été faite à partir du seul JSON français et n'a pas pu être recoupée avec le PDF officiel dans l'atelier (URL : https://sfar.org/wp-content/uploads/2026/04/RFE-20.4.2026-deifinitif-et-validei.pdf). Recoupement avec la source indispensable à la relecture médicale (fiche à 668 chaînes, nombreuses doses et délais).","À VÉRIFIER (doses et délais) : tous les délais d'arrêt (J-6, J-5, J-4, J-3, J-2), les seuils INR (≤ 1,5 ; ≤ 1,2 ; ≤ 4 ; ≤ 2), les doses d'AOD selon le DFGe, les doses d'HBPM/HNF/tinzaparine/énoxaparine (175 UI/kg, 100 UI/kg, 4 500 UI, 2 000 UI, 333 UI/kg puis 250 UI/kg/12h, 5 000 UI x2/j, 18 000 UI, 10 000 UI x2/j, 1 500 UI/h), CCP ~20 UI/kg, vitamine K 2 à 5 mg, apixaban 2,5 mg x2 (≥ 2 critères) ont été recopiés à l'identique ; le contrôle automatique FR/EN des nombres et unités ne relève aucun écart, mais la relecture doit les confronter à la source (criticité maximale, CDC §9.3).","À VÉRIFIER (renvois de mise en page) : le texte français contient des renvois à la pagination du PDF de l'atelier (« cf. p.1 », « cf. p.2 », « annexes p.79-116 », « tableau ci-dessous », « voir l'annexe par spécialité ci-avant ») ; ils ont été traduits tels quels et n'ont plus de sens dans un affichage web par fiche : à réécrire lors de l'import (ou à remplacer par des ancres).","À VÉRIFIER (droits) : l'annexe « Classification du risque hémorragique par spécialité » est annoncée comme une « reproduction fidèle » des tableaux de chaque société partenaire (texte intégral, annexes p.79-116) : CDC §12.4 interdit la reproduction à l'identique des tableaux ; statut juridique de la source à valider avant publication (y compris de la version traduite).","À VÉRIFIER (termes de spécialité) : sigles français dont l'équivalent anglais n'a pas pu être confirmé sans la source — « AVH » (glosé « adénomectomie par voie haute » entre crochets), « RMI » (curages, chirurgie du sein — laissé en sigle), « trituration d'une articulation périphérique » (rendu littéralement « trituration »), « pelvectomie » (laissé tel quel), « formolisation » (rendu « formalin application (formolisation) »), « ATT » (aérateur transtympanique → transtympanic tube), « KTT » (kyste du tractus thyréoglosse), « CIP » (chambre implantable percutanée), « GFR » utilisé pour « DFG » dans quelques cellules. Marques françaises conservées : Coumadine®, Préviscan®, Sintrom®.","À VÉRIFIER : les colonnes « Accord » (« Fort ») sont traduites « Strong » ; les puces de grade (2+, 1+, 1-, 2-, AE) sont recopiées telles quelles de la fiche française, sans recontrôle contre la source dans cette passe (voir point de provenance ci-dessus).","À VÉRIFIER (incohérence de la fiche française, relevée par l'audit) : la ligne « AOD en IRC sévère (DFGe 30-49) » emploie « sévère » pour DFGe 30-49, alors que le tableau des stades de la même fiche classe 30-49 en IRC modérée (stade 3) et 15-29 en IRC sévère (stade 4). La traduction reproduit « severe CKD (eGFR 30-49) » à l'identique ; le relecteur doit trancher selon la source.","À VÉRIFIER (terminologie corrigée après audit) : « voie haute » en gynécologie rendu « abdominal-approach » ; « pelvectomie » (ORL) rendu « floor-of-mouth resection (pelvectomy) » ; « méningiome intra-canalaire cervical » rendu « intracanal (spinal canal) » ; « infiltration canalaire superficielle/profonde » (rhumatologie) traduit « canal infiltration » — équivalent possible « tunnel infiltration » (canal carpien, tunnel tarsien) à confirmer avec la source SFR."]$mgjson$::jsonb, '2026-04-20', 'f2b46657c390356cb30fa795fdad96a37c80f73ae14617fbb650a4042c2a1a83', true
from public.documents d where d.fiche_key = 'anticoagulants'
on conflict (document_id, lang) do update set
  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"HAS · RCF","title":"Pre-urologic urine culture (ECBU) & colonization","short":"Place of the urine culture (ECBU) before urologic management and modalities of treatment of colonization.","society":"AFU / CIAFU — partenaire SFAR","version":"January 2026","validated":"published on sfar.org on 04/03/2026","methodology":"HAS (RCF)"}$mgjson$::jsonb, $mgjson${"v":1,"key":"ecbu","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"General principles & grades","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Golden rule (R1, Grade AE):</b> when a urine culture (ECBU) is <b>not recommended</b> preoperatively, it is in fact <b>not recommended to treat</b> urinary colonization, whether or not endo-urinary material is in place. The objective: reduce antibiotic iatrogenicity without increasing the postoperative infectious risk.","style":"body"}},{"t":"section","text":"Grade legend (HAS methodology — Formalized Consensus Recommendations)","color":"teal-dark"},{"t":"table","rows":[[{"t":"chip","label":"A"},{"t":"p","html":"Established scientific evidence","style":"badge_head"},{"t":"chip","label":"B"},{"t":"p","html":"Scientific presumption","style":"badge_head"},{"t":"chip","label":"C"},{"t":"p","html":"Low level of evidence","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Expert agreement","style":"badge_head"}]]},{"t":"section","text":"Diagnostic principles","color":"teal-dark"},{"t":"table","rows":[[{"t":"p","html":"Interventional or surgical procedure","style":"head_w"},{"t":"p","html":"Reference (level of evidence)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"The urine culture (ECBU) is the reference method for detecting urinary colonization.","style":"cell"},{"t":"p","html":"R1 (Q2)","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Do NOT use the urine dipstick to screen for urinary colonization.","style":"cell"},{"t":"p","html":"R2 (Q2)","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Perform the preoperative urine culture within the 10 days preceding the procedure (extendable to 15 days in case of organizational constraint).","style":"cell"},{"t":"p","html":"R3 (Q2)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Only the result of the bacterial culture matters: neither the Gram stain nor the pyuria predicts the final result.","style":"cell"},{"t":"p","html":"R4 (Q2)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Mono/bi-microbial culture: antibiogram on the species found according to the REMIC reference.","style":"cell"},{"t":"p","html":"R6 (Q2)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Polymicrobial culture (≥3 organisms): no consensus to recommend (or not) a new urine culture or a full antibiogram.","style":"cell"},{"t":"p","html":"R7 (Q2)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Urinary diversion (nephrostomy, Bricker...): no data or consensus on the sampling method to use.","style":"cell"},{"t":"p","html":"R8 (Q2)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"In case of urinary infection (and not simple colonization): the working group suggests postponing the surgical procedure until the infection has resolved.","style":"cell"},{"t":"p","html":"R1.bis (Q1)","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"Particular case of PCNL / infected stones: intraoperative urine culture on renal pelvic urine suggested (otherwise, stone culture) to adjust antibiotic therapy in case of postoperative sepsis (Grade C).","style":"note"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Context:</b> 7 to 9 million urine cultures are performed each year in France (1st examination prescribed, ~180 M€/year). Systematic screening and treatment of urinary colonization before urologic surgery are relevant only for a limited number of procedures (TURP, ureteroscopy, PCNL in particular): antibiotic overprescription has shown no infectious benefit and fuels antibiotic resistance.","style":"body_sm"}},{"t":"p","html":"In particular cases (e.g. immunocompromised patients), the clinician may depart from these recommendations if the decision is reasoned, documented and taken after multidisciplinary discussion.","style":"note"}]},{"title":"Decision table — urine culture indicated","items":[{"t":"section","text":"Preoperative urine culture INDICATED","color":"red"},{"t":"table","rows":[[{"t":"p","html":"Interventional or surgical procedure","style":"head_w"},{"t":"p","html":"Reference (level of evidence)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Transurethral resection of the prostate (TURP)","style":"cell"},{"t":"p","html":"ElMalik 2000 (NP2)","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Prostate enucleation for BPH (HoLEP, ThuLEP, GreenLEP, bipolar)","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Transurethral resection of the bladder (TURB)","style":"cell"},{"t":"p","html":"Kohada 2019, Kutchukian 2024","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Pyeloureteral junction repair (JJ stent)","style":"cell"},{"t":"p","html":"See CIAFU recommendation","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Ureteroplasty","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Diagnostic and/or therapeutic ureteroscopy","style":"cell"},{"t":"p","html":"Martov 2015, Sohn 2013 — see CLAFU recommendation","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Urethrotomy","style":"cell"},{"t":"p","html":"Noble 2022 (NP4)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Urethroplasty","style":"cell"},{"t":"p","html":"Noble 2022 (NP4)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Placement / change of nephrostomy tube, mono-J or JJ stent","style":"cell"},{"t":"p","html":"See CIAFU recommendation","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Percutaneous nephrolithotomy (PCNL)","style":"cell"},{"t":"p","html":"+ renal pelvic urine if possible — see CLAFU recommendation","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Urodynamic assessment","style":"cell"},{"t":"p","html":"Egrot 2018 — strong agreement","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Decision table — urine culture not indicated","items":[{"t":"table","rows":[[{"t":"p","html":"Interventional or surgical procedure","style":"head_w"},{"t":"p","html":"Reference (level of evidence)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Radical prostatectomy","style":"cell"},{"t":"p","html":"Bourgi 2025b (NP4)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"BPH treatment with UROLIFT® / prostatic artery embolization","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Surgical adenomectomy","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prostate biopsy (transperineal or transrectal)","style":"cell"},{"t":"p","html":"See CCAFU / CIAFU recommendation","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Partial or total cystectomy (whatever the type of diversion)","style":"cell"},{"t":"p","html":"Haider 2019, Kyoda 2010","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Cystoscopy (whatever the indication)","style":"cell"},{"t":"p","html":"Herr 2012-2016 (concordant studies)","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Implantation of artificial urinary sphincter","style":"cell"},{"t":"p","html":"Kavoussi 2017 (NP4)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Intravesical instillations (chemotherapy, BCG, hyaluronic acid...)","style":"cell"},{"t":"p","html":"Herr 2012-2020 (concordant studies)","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Botulinum toxin A injection / sacral root neuromodulation","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Partial or total nephrectomy / nephroureterectomy","style":"cell"},{"t":"p","html":"Bruyere 2025, Ayoub 2024","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Adrenalectomy / renal artery embolization","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Kidney biopsy or thermoablation of a renal tumor","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Placement or change of peritoneal dialysis catheter","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Retrograde urethrocystography","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Placement of penile implant","style":"cell"},{"t":"p","html":"Kavoussi 2017 (NP4)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Placement of testicular prosthesis / scrotal or penile surgery without prosthesis","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Placement, removal or change of urinary catheter, suprapubic catheter","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Radiotherapy, brachytherapy, placement of prostatic fiducial markers","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Positive urine culture, antibiotic therapy & sources","items":[{"t":"section","text":"No consensus (neither recommended nor excluded)","color":"amber"},{"t":"p","html":"Steam thermotherapy (Rezum®) • Focused ultrasound (HIFU) • Prolapse / incontinence repair (women and men) • Macroplastique injection • Kidney transplantation • Extracorporeal lithotripsy. For these procedures, the benefit-risk balance (antibiotic resistance vs unproven infectious risk) tips toward <b>non-prescription</b> according to the majority of the working group.","style":"body"},{"t":"section","text":"Management of a positive urine culture (confirmed colonization)","color":"teal-dark"},{"t":"table","rows":[[{"t":"p","html":"Interventional or surgical procedure","style":"head_w"},{"t":"p","html":"Reference (level of evidence)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Appropriate antibiotic treatment if indicated, regardless of the quantity of micro-organism isolated.","style":"cell"},{"t":"p","html":"R1 (Q3)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Duration: start 48h before the procedure, continue at least until D0 and at most 48h after → total 3 to 5 days.","style":"cell"},{"t":"p","html":"R2 (Q3)","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"PCNL: systematically treat the colonization (optimal duration not consensual in France).","style":"cell"},{"t":"p","html":"R3 (Q3)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Preoperative fungal urinary colonization: no data or consensus to recommend or not a treatment.","style":"cell"},{"t":"p","html":"R4.bis (Q3)","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Polymicrobial culture (≥3 organisms): no consensus to recommend or not an antibiotic treatment.","style":"cell"},{"t":"p","html":"R5 (Q3)","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"default","content":{"t":"table","rows":[[{"t":"p","html":"<b>Order of preference of antibiotics</b> (even in case of ESBL/MRSA, prefer a single, effective drug according to the antibiogram, with good urinary diffusion, little harm to the microbiota, PO preferred) — Grade AE:","style":"body"}],[{"t":"table","rows":[[{"t":"p","html":"<b>1<super rise=2 size=6>st</super> line</b><br/>Fosfomycin-trometamol<br/>Nitrofurantoin<br/>Pivmecillinam<br/>Trimethoprim","style":"cell_c"},{"t":"p","html":"<b>2<super rise=2 size=6>nd</super> line</b><br/>Amoxicillin<br/>Cotrimoxazole","style":"cell_c"},{"t":"p","html":"<b>3<super rise=2 size=6>rd</super> line</b><br/>Amoxicillin +<br/>clavulanic acid","style":"cell_c"},{"t":"p","html":"<b>4<super rise=2 size=6>th</super> line</b><br/>Fluoroquinolones<br/>Cefixime","style":"cell_c"},{"t":"p","html":"<b>5<super rise=2 size=6>th</super> line</b><br/>Other<br/>antibiotics*","style":"cell_c"}]]}]]}},{"t":"p","html":"* 5th line = other antibiotics according to the antibiogram, if the first 4 lines are not suitable (resistance, allergy...). If the decision is made to treat a polymicrobial urine culture without an antibiogram usable per strain: prefer Fosfomycin-trometamol, Nitrofurantoin, Pivmecillinam or Trimethoprim (R6, Grade AE).","style":"note"},{"t":"section","text":"Sources and traceability","color":"grey"},{"t":"p","html":"<b>Source document:</b> Good practice recommendation \"Place of the urine culture (ECBU) before urologic surgical or interventional management in adults and modalities of treatment in case of colonization\" (\"Place de l'ECBU avant une prise en charge urologique chirurgicale ou interventionnelle chez l'adulte et modalités de traitement en cas de colonisation\"). Developed by the AFU Professional Practice Committee (CPP-AFU) and the AFU Infectious Diseases Committee (CIAFU), with the AFUF, the SF2H, the SFM, the <b>SFAR</b>, Renaloo and Le Lien.","style":"source"},{"t":"p","html":"<b>Version:</b> Summary (short text) — January 2026, validated version. Published on the SFAR website on 4 March 2026.","style":"source"},{"t":"p","html":"<b>Methodology:</b> Formalized Consensus Recommendations (RCF) — HAS methodological guide 2011. Grades A/B/C according to the level of evidence, or Expert Agreement (AE).","style":"source"},{"t":"p","html":"<b>Source URL:</b> urofrance.org/wp-content/uploads/2026/03/Reco_ECBU_Synthese_23.02.2023_MEL.pdf — relayed on sfar.org","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this document is an independent summary fiche, produced as a memory aid for on-call situations. It does not replace the full text of the recommendation (complete rationale of 154 pages, detailed levels of evidence, exhaustive table) and is neither published nor validated by the AFU, the CIAFU or the SFAR. In case of a complex or unlisted clinical situation, refer to the full text and/or to an infectious disease/urology specialist opinion.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"R1 (Q2)","grade":"A","fr":"L'ECBU est la méthode de référence pour dépister une colonisation urinaire.","en":"The urine culture (ECBU) is the reference method for detecting urinary colonization."},{"ref":"R2 (Q2)","grade":"B","fr":"Ne PAS utiliser la bandelette urinaire pour dépister une colonisation urinaire.","en":"Do NOT use the urine dipstick to screen for urinary colonization."},{"ref":"R3 (Q2)","grade":"AE","fr":"Réaliser l'ECBU préopératoire dans les 10 jours précédant l'intervention (extensible à 15 j si contrainte organisationnelle).","en":"Perform the preoperative urine culture within the 10 days preceding the procedure (extendable to 15 days in case of organizational constraint)."},{"ref":"R4 (Q2)","grade":"C","fr":"Seul le résultat de la culture bactérienne compte : ni le Gram ni la leucocyturie ne préjugent du résultat définitif.","en":"Only the result of the bacterial culture matters: neither the Gram stain nor the pyuria predicts the final result."},{"ref":"R1.bis (Q1)","grade":"AE","fr":"En cas d'infection urinaire (et non simple colonisation) : le groupe de travail suggère de reporter l'intervention chirurgicale jusqu'à résolution de l'infection.","en":"In case of urinary infection (and not simple colonization): the working group suggests postponing the surgical procedure until the infection has resolved."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER (provenance) : cette fiche n'a ni script de construction (build/fiche_ecbu.py absent) ni texte source dans sources/ ; la traduction anglaise est faite à partir du seul JSON français et n'a pas pu être recoupée avec le PDF dans l'atelier.","À VÉRIFIER (URL et date) : l'URL citée dans la fiche (« urofrance.org/wp-content/uploads/2026/03/Reco_ECBU_Synthese_23.02.2023_MEL.pdf ») ne correspond pas à l'URL de la bibliothèque (…/2026/03/Reco_ECBU_Synthese_04.03.2026_MEL.pdf) : nom de fichier daté 23.02.2023 dans la fiche vs 04.03.2026 dans la bibliothèque. La méta indique « Janvier 2026 » (version) et « publiée sfar.org le 04/03/2026 » ; date retenue pour l'ordre de traitement : 2026-03-04 (mise en ligne SFAR). URL source (obligatoire pour la publication, CDC §9.2) à corriger avant import.","À VÉRIFIER (attribution) : le badge « HAS · RCF » (repris à l'identique) peut laisser croire à une recommandation HAS ; le document source est une recommandation de bonne pratique de l'AFU (CPP-AFU/CIAFU) avec la SFAR, élaborée selon la méthodologie HAS des Recommandations par Consensus Formalisé (RCF). Vérifier le libellé exact avant affichage (règle « pas de logo ni d'élément protégé » et attribution correcte de la société auteure).","À VÉRIFIER (numérotation) : la numérotation des recommandations comporte des irrégularités héritées de la fiche française (Q2 : R1, R2, R3, R4, R6, R7, R8 — pas de R5 ; Q3 : R1, R2, R3, R4.bis, R5 ; « R1.bis (Q1) ») ; vérifier avec la source qu'aucune recommandation n'est omise. Traduit tel quel.","À VÉRIFIER (grades) : les puces A / B / C / AE sont recopiées de la fiche française (méthodologie HAS/RCF : A = preuve scientifique établie, B = présomption scientifique, C = faible niveau de preuve, AE = accord d'experts) ; les références « NP2 », « NP4 » (niveau de preuve) sont conservées telles quelles. Points clés : lignes R1 (Q2), R2 (Q2), R3 (Q2), R4 (Q2) et R1.bis (Q1) de la fiche française.","À VÉRIFIER : le tableau « ECBU indiqué / non indiqué » liste des actes avec références bibliographiques (ElMalik 2000, Herr 2012-2020, etc.) : reproduction proche de la source (CDC §12.4). Sigles : ECBU conservé (urine culture), NLPC → PCNL, RTUP → TURP, RTUV → TURB, HBP → BPH ; CIAFU, CLAFU, CCAFU conservés (comités AFU) ; « REMIC » (référentiel de microbiologie médicale) conservé.","À VÉRIFIER : le libellé « 2ème/3ème... intention » utilise des balises <super> propres au générateur PDF (reportlab) ; elles sont conservées à l'identique dans les deux langues et devront être normalisées à l'import."]$mgjson$::jsonb, '2026-03-04', '80f93658dacc436fe14725482d8309f3d2b856e61b267cceff88646e653ca90a', true
