insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"SFAR/SFNCM/AFDN/FCVD — RBP (good practice recommendation), adopted by the HAS Board 03/09/2026","title":"Clinical nutrition in adults — perioperative & critical care","short":"SFAR/SFNCM/AFDN/FCVD, \"Clinical nutrition in adults in the perioperative and critical care setting\" (\"Nutrition clinique de l'adulte en contexte périopératoire et en soins critiques\"), Good Practice Recommendation (RBP), adopted by the Board (Collège) of the HAS on 03/09/2026 — very recent document found through a web search (absent from this site's usual index at the date of its publication). CLINICALLY UPDATES TWO fiches already on this site: \"Artificial nutrition in intensive care\" (SFAR RFE 2014) and \"Perioperative nutrition\" (2011), kept for their historical value — this document merges the two scopes. Covers 2 fields, 13 questions: undernutrition and HAS diagnostic criteria (common to both fields); peri-/postoperative nutritional strategies and the role of the dietitian; nutritional targets in critical care according to the clinical phase (shock/multiple organ failure, stabilization, rehabilitation); digestive tolerance of enteral nutrition (prokinetics, protocolized abdominal massage); monitoring, efficacy and refeeding syndrome (\"syndrome de renutrition inappropriée\"). 40 recommendations (GRADE 1: 11, GRADE 2: 9, expert opinion: 16, no recommendation: 3, regulatory reminder: 1) — count verified as exactly identical to the one announced by the source document itself, no discrepancy.","society":"SFAR / SFNCM / AFDN / FCVD","version":"2026","validated":"Adopted by the HAS Board (Collège) on 03/09/2026","methodology":"GRADE grid — GRADE 1/2 (strong/weak, for or against), AE (expert opinion, \"avis d'experts\"), no recommendation (chip \"0/\"), regulatory reminder (chip \"RÉGL\", outside GRADE) — 40 recommendations (GRADE 1: 11, GRADE 2: 9, AE: 16, 0/: 3, RÉGL: 1), count identical to the one announced by the source"}$mgjson$::jsonb, $mgjson${"v":1,"key":"nutrition_clinique_2026","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Perioperative & critical care clinical nutrition — Fields 1 and 2","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Very recent document</b> (adopted by the HAS Board on 03/09/2026) — found through a web search (absent from <code>library_final.json</code> at the time of publication). <b>UPDATES</b> TWO fiches already on this site: \"Artificial nutrition in intensive care\" (SFAR RFE 2014) and \"Perioperative nutrition\" (2011), kept for their historical value — this document merges the two scopes. <b>Excluded from scope:</b> pediatric populations, micronutrients (trace elements/vitamins, see the 2022 European recommendations), detailed prescribing outside clinical nutrition.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"1-"},{"t":"chip","label":"2+"},{"t":"chip","label":"2-"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>GRADE grid</b> — <b>1+/1-</b>: strong recommendation, for/against; <b>2+/2-</b>: weak recommendation, for/against; <b>AE</b>: expert opinion; <b>0/</b>: no recommendation. One item (R2.9.1) carries a distinct <b>RÉGL</b> chip: regulatory reminder, not a GRADE grade. 40 recommendations (GRADE 1: 11, GRADE 2: 9, AE: 16, no recommendation: 3, regulatory: 1) — count identical to the one announced by the source, verified exact.","style":"badge_head"}]]},{"t":"section","text":"Field 1 — 1.1 Screening for undernutrition (perioperative)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"1.1.1","style":"cell_b"},{"t":"p","html":"Intermediate- or high-risk surgery: screen for undernutrition or risk of undernutrition to predict perioperative morbidity and mortality (HAS diagnostic criteria — table below).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"1.1.2","style":"cell_b"},{"t":"p","html":"Same setting: use a clinical-biological score adapted to the patient and their surgery to predict morbidity and mortality.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.1.3","style":"cell_b"},{"t":"p","html":"Same setting: measure preoperative serum albumin to qualify the severity of undernutrition and predict morbidity and mortality.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Diagnosis of undernutrition (HAS)</b>","style":"cell_b"},{"t":"p","html":"<b>Criteria</b>","style":"cell_b"}],[{"t":"p","html":"1 HAS phenotypic criterion","style":"cell"},{"t":"p","html":"Weight loss ≥5 %/1 month or ≥10 %/6 months or ≥10 % of usual pre-illness weight; OR BMI <18.5 kg/m² if <70 years / <22 kg/m² if ≥70 years; OR reduced strength (grip strength and/or chair-stand test); OR reduced muscle mass (imaging/bioimpedance/DEXA if available).","style":"cell"}],[{"t":"p","html":"1 HAS etiologic criterion","style":"cell"},{"t":"p","html":"Reduced food intake; OR malabsorption/maldigestion; OR aggression situation (intermediate- or high-risk surgery, cancer context, or acute critical illness in critical care).","style":"cell"}],[{"t":"p","html":"Diagnosis made if","style":"cell"},{"t":"p","html":"1 single phenotypic criterion + 1 single etiologic criterion (sufficient among all those listed).","style":"cell"}],[{"t":"p","html":"Severity — serum albumin","style":"cell"},{"t":"p","html":"Moderate: 30-35 g/L. Severe: ≤ 30 g/L (prognostic value).","style":"cell"}],[{"t":"p","html":"Scores","style":"cell"},{"t":"p","html":"GNRI (Geriatric Nutritional Risk Index) and CONUT (Controlling Nutritional Status score) in the perioperative setting; in critical care, there is no specific screening score, but the mNUTRIC score (modified Nutrition Risk in Critically ill) is used for risk stratification once the patient is admitted — every patient admitted to critical care is considered at nutritional risk.","style":"cell"}]]},{"t":"p","html":"Figures 1 and 3 of the source (merged) — diagnostic criteria are identical in the perioperative and critical care settings; only the risk-screening methods differ (GNRI/CONUT scores vs. mNUTRIC).","style":"source"},{"t":"section","text":"Field 1 — 1.2/1.3/1.4 Peri- and postoperative nutritional strategy & dietitian","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"1.2.1","style":"cell_b"},{"t":"p","html":"Elective intermediate/high-risk surgery: prehabilitation program stratified on the patient's risk, including nutritional care, to reduce certain postoperative complications (notably infectious ones).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.2.2","style":"cell_b"},{"t":"p","html":"Undernourished patients, same setting: the experts suggest that preoperative artificial nutrition would reduce complications and length of stay.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.3","style":"cell_b"},{"t":"p","html":"Patients not selected according to their nutritional status, same setting: no recommendation on the value of preoperative nutritional therapy.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"1.2.4","style":"cell_b"},{"t":"p","html":"Digestive or ENT cancer surgery: no recommendation on the value of pre- or perioperative immunonutrition.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"1.3.1","style":"cell_b"},{"t":"p","html":"Intermediate/high-risk surgery: resume oral and/or artificial nutrition as early as possible to reduce postoperative morbidity.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"1.3.2","style":"cell_b"},{"t":"p","html":"Same setting: aim for an energy target of 20-25 kcal/kg/day and a protein target of 1-1.3 g/kg/day, to be reached progressively after surgery.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.3.3","style":"cell_b"},{"t":"p","html":"Same setting: combine the different routes of administration in order of priority — oral, enteral, then parenteral — if the targets are not reached by a single route.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.4.1","style":"cell_b"},{"t":"p","html":"Elective intermediate/high-risk surgery: involve a dietitian throughout the perioperative pathway (reduces complications, limits weight loss, improves attainment of nutritional targets and the financial valuation of stays).","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 2 — 2.1/2.2 Undernutrition & timing of initiation (critical care)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"2.1.1","style":"cell_b"},{"t":"p","html":"Patients hospitalized in critical care: screen for undernutrition to predict morbidity and mortality (HAS criteria — table on the previous page).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.1.2","style":"cell_b"},{"t":"p","html":"Same setting: qualify the severity of undernutrition to predict morbidity and mortality.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.2.1","style":"cell_b"},{"t":"p","html":"In the absence of contraindication: start nutritional support within 48 hours of admission.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 2 — 2.3/2.4/2.5 Nutritional targets according to the clinical phase","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"2.3.1","style":"cell_b"},{"t":"p","html":"Shock / multiple organ failure: maintain a low energy target to reduce morbidity.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.3.2","style":"cell_b"},{"t":"p","html":"Same setting: do not exceed a maximum energy target of 10 kcal/kg/day to reduce morbidity and mortality.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.3.3","style":"cell_b"},{"t":"p","html":"Same setting: do not exceed a maximum protein target of 0.4 g/kg/day to reduce morbidity and mortality.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.3.4","style":"cell_b"},{"t":"p","html":"Same setting, at equivalent energy target: use enteral or parenteral nutrition interchangeably (no demonstrated superiority on mortality).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.3.5","style":"cell_b"},{"t":"p","html":"Same setting: do not combine enteral and parenteral nutrition to reach the energy target.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"2.4.1","style":"cell_b"},{"t":"p","html":"Stabilized patients: do not exceed an energy target of 20 kcal/kg/day to reduce morbidity and mortality.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.4.2","style":"cell_b"},{"t":"p","html":"Same setting: progressively increase energy intake between 10 and 20 kcal/kg according to tolerance, to reduce morbidity and mortality.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.4.3","style":"cell_b"},{"t":"p","html":"Same setting: do not exceed a protein target of 0.9 g/kg/day to reduce morbidity and mortality.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.4.4","style":"cell_b"},{"t":"p","html":"Same setting, at equivalent energy target: use enteral nutrition, parenteral nutrition or their combination interchangeably (no superiority of either route on mortality).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.5.1","style":"cell_b"},{"t":"p","html":"Rehabilitation phase: multimodal nutritional strategy including physical exercise, to improve quality of life and functional recovery.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"2.5.2","style":"cell_b"},{"t":"p","html":"Same setting: aim for a target between 20-25 kcal/kg/day and 1.2-1.5 g of protein/kg/day to reduce morbidity and mortality.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.5.3","style":"cell_b"},{"t":"p","html":"Rehabilitation phase with acute kidney injury without renal replacement therapy: maintain a moderate target of 0.9 g/kg/day (no demonstrated benefit of higher intakes).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"2.5.4","style":"cell_b"},{"t":"p","html":"Rehabilitation phase under renal replacement therapy: aim for a protein intake of 1.5 g/kg/day to compensate for the losses induced by the replacement therapy.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Non-nutritional calories</b>","style":"cell_b"},{"t":"p","html":"<b>Equivalence</b>","style":"cell_b"}],[{"t":"p","html":"Conversion factors","style":"cell"},{"t":"p","html":"1 g of glucose = 4 kcal; 1 mL of propofol 1 % = 1.1 kcal (intake divided by 2 with propofol 2 %); 1 g of citrate ≈ 3 kcal (citrate renal replacement therapy).","style":"cell"}],[{"t":"p","html":"Example of cumulative intake","style":"cell"},{"t":"p","html":"Propofol 1 % 150 mg/h (15 mL/h) ≈ 400 kcal/24h + 5 % glucose solution 500 mL/day = 100 kcal/24h + citrate replacement therapy ≈ 200 kcal/24h → 700 kcal/24h ≈ 10 kcal/kg/24h for a 70 kg patient.","style":"cell"}],[{"t":"p","html":"Practical rule","style":"cell"},{"t":"p","html":"Non-nutritional calories must be included in the assessment of energy intake before starting or increasing nutritional support; if they exceed the target appropriate to the clinical condition, delay the start of nutritional support.","style":"cell"}]]},{"t":"p","html":"Figure 5 of the source, attached to the low energy targets (R2.3.1-R2.3.3). Contraindications to the enteral route (Figure 4): uncontrolled upper gastrointestinal bleeding, suspected/confirmed intestinal ischemia, bowel obstruction, abdominal compartment syndrome, high-output digestive fistula without distal access.","style":"source"},{"t":"section","text":"Field 2 — 2.6 Improving the digestive tolerance of enteral nutrition","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"2.6.1","style":"cell_b"},{"t":"p","html":"Upper digestive intolerance (vomiting, regurgitation): use prokinetics as first-line — erythromycin (100-250 mg 3 times/day slow IV) or metoclopramide (10 mg 3 times/day slow IV), alone or in combination, for 48-72h.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.6.2","style":"cell_b"},{"t":"p","html":"Do not prefer intermittent enteral nutrition over continuous enteral nutrition to improve digestive tolerance.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"2.6.3","style":"cell_b"},{"t":"p","html":"Persistent upper digestive intolerance despite prokinetics: prefer administration at a post-pyloric or jejunal site as an alternative to the gastric site.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"2.6.4","style":"cell_b"},{"t":"p","html":"Use enteral solutions containing fiber to reduce transit disorders (diarrhea, constipation).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.6.5","style":"cell_b"},{"t":"p","html":"Do not use laxatives prophylactically to prevent constipation.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"2.6.6","style":"cell_b"},{"t":"p","html":"Concomitant opioid treatment: do not use PAMORAs (peripherally acting mu-opioid receptor antagonists) to prevent or treat constipation.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"2.6.7","style":"cell_b"},{"t":"p","html":"Perform protocolized abdominal massages (protocol below), in the absence of contraindication, to improve comfort and digestive tolerance.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Protocolized abdominal massage</b>","style":"cell_b"},{"t":"p","html":"<b>Modalities</b>","style":"cell_b"}],[{"t":"p","html":"Sequence (4 steps)","style":"cell"},{"t":"p","html":"1. Pressure and stroking in a clockwise direction — 2. Tapping with 4 fingers along the colonic frame — 3. Kneading (right colon from bottom to top, left colon from top to bottom) — 4. Vibrations (abdominal wall stimulated with the palm of the hand).","style":"cell"}],[{"t":"p","html":"Frequency","style":"cell"},{"t":"p","html":"Morning and evening, total duration 15 min (set-up + 3 min/step), 3 consecutive days. Enteral nutrition stopped 30 min beforehand, patient supine.","style":"cell"}],[{"t":"p","html":"Who / contraindications","style":"cell"},{"t":"p","html":"Trained paramedical staff (nurse/nursing assistant); contraindicated in case of abdominal tumor, peritonitis, ascites, ileus or obstruction, digestive bleeding, recent abdominal surgery, abdominal trauma, formal refusal by the patient.","style":"cell"}]]},{"t":"p","html":"Figure 7 of the source, attached to R2.6.7.","style":"source"},{"t":"section","text":"Field 2 — 2.7/2.8/2.9 Monitoring, efficacy & dietitian","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"2.7.1","style":"cell_b"},{"t":"p","html":"Enteral and/or parenteral nutrition: structured and regular clinical and biological monitoring, to assess digestive/metabolic tolerance early and adapt the strategy.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.7.2","style":"cell_b"},{"t":"p","html":"Enteral nutrition in intensive care: do not collect or measure the volume of gastric residue to assess tolerance.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"2.7.3","style":"cell_b"},{"t":"p","html":"Measure plasma phosphate, potassium and magnesium concentrations daily to detect refeeding syndrome during the first 3 to 5 days (full protocol below).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.8.1","style":"cell_b"},{"t":"p","html":"Clinical and/or biological monitoring to assess the efficacy of nutritional support — short term: regular weighing, weekly prealbumin; medium term: muscle mass (imaging/bioimpedance/DEXA); long term: functional tests.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.8.2","style":"cell_b"},{"t":"p","html":"No recommendation on the value of indirect calorimetry to guide nutritional intake.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"2.9.1","style":"cell_b"},{"t":"p","html":"Reminder: the paramedical team must include a dietitian \"as often as needed\" (decree no. 2022-694 of 26/04/2022), to better define protein-energy needs and optimize attainment of nutritional targets.","style":"cell"},{"t":"chip","label":"RÉGL"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Refeeding syndrome (\"syndrome de renutrition inappropriée\", SRI)</b>","style":"cell_b"},{"t":"p","html":"<b>Detail</b>","style":"cell_b"}],[{"t":"p","html":"Definition","style":"cell"},{"t":"p","html":"Clinical and biological manifestations related to fluid-electrolyte and vitamin disturbances when nutrition is resumed after undernutrition or prolonged fasting: hypophosphatemia, hypokalemia, hypomagnesemia (± vitamin B1 deficiency).","style":"cell"}],[{"t":"p","html":"Manifestations","style":"cell"},{"t":"p","html":"Cardiorespiratory (arrhythmia, anasarca, left heart failure, acute respiratory failure); neurological (encephalopathy, seizure); muscular (paresthesia, rhabdomyolysis); hematological (pancytopenia, hemolysis).","style":"cell"}],[{"t":"p","html":"Risk factors","style":"cell"},{"t":"p","html":"BMI < 18.5 kg/m²; recent weight loss (5-10 %); reduced intake (≥50-75 %) or prolonged fasting; hypoK/hypoPh/hypoMg; chronic disease (cancer, chronic alcoholism, malabsorption, neurodegenerative disease, anorexia); polymedication (diuretics, PPIs, resumption/initiation of insulin).","style":"cell"}],[{"t":"p","html":"Prevention","style":"cell"},{"t":"p","html":"Start at ≈ 10 kcal/kg/day, progressive increase over 7 to 10 days in 25 % steps according to tolerance (daily electrolyte panel + ECG monitoring); thiamine 200-300 mg/day; correct electrolyte disturbances before starting nutrition; micronutrients at daily dose.","style":"cell"}],[{"t":"p","html":"Alert threshold","style":"cell"},{"t":"p","html":"Fall of 10-20 % in phosphate, potassium or magnesium, or phosphatemia fall > 0.16 mmol/L.","style":"cell"}],[{"t":"p","html":"Management","style":"cell"},{"t":"p","html":"Reduce intake or stop for 24-48h; IV supplementation with daily monitoring; then resume slowly and progressively.","style":"cell"}]]},{"t":"p","html":"Figure 9 of the source, attached to R2.7.3 — the most actionable protocol in the document beyond the 40 recommendations themselves.","style":"source"},{"t":"section","text":"Sources and disclaimer","color":"grey"},{"t":"p","html":"<b>Source document:</b> SFAR/SFNCM/AFDN/FCVD, \"Clinical nutrition in adults in the perioperative and critical care setting\" (\"Nutrition clinique de l'adulte en contexte périopératoire et en soins critiques\"), Good Practice Recommendation (RBP), adopted by the HAS Board (Collège) on 03/09/2026.","style":"source"},{"t":"p","html":"<b>Source URL:</b> https://sfar.org/nutrition-clinique-de-ladulte-en-contexte-perioperatoire-et-en-soins-critiques/","style":"source"},{"t":"p","html":"<b>Coverage:</b> the 40 recommendations of the document (Fields 1 and 2, 13 questions) are reproduced in full (GRADE 1: 11, GRADE 2: 9, expert opinion: 16, no recommendation: 3, regulatory reminder: 1) — count identical to the one announced by the source itself, verified by exhaustive recount. Clinically updates/supersedes the fiches \"Artificial nutrition in intensive care\" (SFAR RFE 2014) and \"Perioperative nutrition\" (2011), kept on this site for their historical value. 5 of the document's 9 figures (genuinely actionable content absent from the text of the recommendations) are reproduced as compact tables; the other 4, redundant with the already complete text of the recommendations, are not (disclosed at the head of the script). GRADE/PICO methodology not reproduced (non-clinical).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this fiche is an independent summary of the 40 recommendations of this reference document. It does not replace the full text. This fiche is neither published nor validated by the SFAR, the SFNCM, the AFDN, the FCVD or the HAS.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"1.3.1","grade":"1+","fr":"Chirurgie à risque intermédiaire/élevé : reprendre le plus précocement possible une nutrition orale et/ou artificielle pour diminuer la morbidité postopératoire.","en":"Intermediate/high-risk surgery: resume oral and/or artificial nutrition as early as possible to reduce postoperative morbidity."},{"ref":"2.2.1","grade":"AE","fr":"En l'absence de contre-indication : instaurer un support nutritionnel dans les 48 heures suivant l'admission.","en":"In the absence of contraindication: start nutritional support within 48 hours of admission."},{"ref":"2.3.1","grade":"1+","fr":"État de choc / défaillance multiviscérale : maintenir une cible énergétique basse pour diminuer la morbidité.","en":"Shock / multiple organ failure: maintain a low energy target to reduce morbidity."},{"ref":"2.4.1","grade":"1+","fr":"Patients stabilisés : ne pas dépasser une cible énergétique de 20 kcal/kg/jour pour diminuer la morbi-mortalité.","en":"Stabilized patients: do not exceed an energy target of 20 kcal/kg/day to reduce morbidity and mortality."},{"ref":"2.7.3","grade":"AE","fr":"Mesurer quotidiennement les concentrations plasmatiques de phosphate, potassium et magnésium pour détecter un syndrome de renutrition inappropriée pendant les 3 à 5 premiers jours (protocole complet ci-dessous).","en":"Measure plasma phosphate, potassium and magnesium concentrations daily to detect refeeding syndrome during the first 3 to 5 days (full protocol below)."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER : le signe +/- des grades GRADE 1 / GRADE 2 (puces 1+, 1-, 2+, 2-) n'est PAS imprimé dans le tableau de synthèse de la source (qui ne porte que « 1 », « 2 », « AE », « ABS » ou « Rappel à la réglementation »). Il a été déduit du libellé de chaque recommandation lors de la construction de la fiche française (ex. « ne pas utiliser/privilégier/associer/recueillir » = signe négatif : R2.3.5, R2.6.2, R2.6.5, R2.6.6, R2.7.2 ; « ne pas dépasser [plafond chiffré] » = signe positif). Le cahier des charges (§4.1) interdit tout grade déduit : le relecteur doit soit valider ce codage, soit remplacer les puces par « GRADE 1 » / « GRADE 2 » sans signe. La version anglaise recopie les puces françaises à l'identique.","À VÉRIFIER : la fiche française contient des notes internes de l'atelier (« trouvé via recherche web », « absent de library_final.json », « disclosed en tête de script », renvois aux fiches 2011/2014 « conservées sur ce site ») dans le panneau d'introduction, la couverture et la méta (short/methodology) ; elles sont traduites telles quelles mais ne doivent pas être publiées en l'état.","À VÉRIFIER : les tableaux (critères HAS de dénutrition, calories non nutritionnelles, massage abdominal, syndrome de renutrition inappropriée) reprennent des figures de la source de façon très proche ; le cahier des charges §12.4 demande une reformulation éditoriale et interdit la reproduction à l'identique des tableaux — statut juridique de la source à valider avant publication.","À VÉRIFIER : l'étiquette « AE » (avis d'experts) est conservée telle quelle dans la version anglaise (grade identique dans toutes les langues, CDC §7) ; l'équivalent anglais usuel « expert opinion » figure dans chip_legend. « RBP » = Recommandation de Bonne Pratique, rendu « Good Practice Recommendation »."]$mgjson$::jsonb, '2026-09-03', 'aa24f63dce7f049293cc883fe7216d56f5ad234b23d0d4f96f741e6bd30d45bd', true
from public.documents d where d.fiche_key = 'nutrition_clinique_2026'
on conflict (document_id, lang) do update set
  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"SFMU/SFAR — RFE, up to date at 25/06/2026","title":"Procedural sedation in the emergency medicine setting","short":"SFMU/SFAR, \"Procedural sedation in the emergency medicine setting\" (\"Sédation procédurale en structure de médecine d'urgence\"), RFE (formalized expert recommendations), up to date at 25/06/2026 — very recent document found through a web search (absent from this site's usual index at the date of its publication). CLINICALLY UPDATES the fiche \"Procedural sedation in the emergency medicine setting\" (SFMU/SFAR RFE 2010), kept on this site for its historical value. Scope: adults, excluding pregnancy, intravenous route only. Covers 4 fields and 17 PICO questions: indication for sedation (alternatives such as regional anesthesia); at-risk patients — when to proceed or not (ASA, morbid obesity, OSAHS, elderly patients, fasting, acute alcohol intoxication, opioids already received); safety conditions (capnography, oxygenation, criteria for calling the anesthesiologist); how to perform it (sedation scales, choice of drugs including ketamine-propofol, electrical cardioversion, post-procedure monitoring with MASS/mPADSS scores, checklist). 34 recommendations actually counted in the body of the text (GRADE 1: 1, GRADE 2: 4, AE: 26, no recommendation: 3) — the document itself announces 36 in its summary (1 GRADE 1, 3 GRADE 2, 29 AE, 3 absences); discrepancy disclosed in the fiche, not resolved after a complete re-read of the 17 questions.","society":"SFMU / SFAR","version":"2026","validated":"Up to date at 25/06/2026","methodology":"GRADE grid — GRADE 1 (strong recommendation), GRADE 2 (weak recommendation), AE (expert opinion), no recommendation (chip \"0/\") — 34 items counted in the body of the text (GRADE 1: 1, GRADE 2: 4, AE: 26, 0/: 3) vs 36 announced by the document's summary (1/3/29/3) — unresolved source discrepancy"}$mgjson$::jsonb, $mgjson${"v":1,"key":"sedation_procedurale_2026","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Procedural sedation in the emergency setting — Fields 1 to 4","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Very recent document</b> (up to date at 25/06/2026) — found outside this repository's usual process (absent from <code>library_final.json</code> at the date of its publication), through a web search. <b>CLINICALLY UPDATES</b> the fiche \"Procedural sedation in the emergency medicine setting\" (SFMU/SFAR RFE 2010), kept on this site for its historical value. <b>Scope:</b> adults, excluding pregnancy, intravenous route only (inhaled route out of scope); does not address patients managed out of hospital without access to the patient and/or incarcerated patients (no literature).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"2+"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>GRADE grid</b> — <b>1+</b>: strong recommendation; <b>2+</b>: weak/optional recommendation; <b>AE</b>: expert opinion (strong agreement required); <b>0/</b>: no recommendation (insufficient literature — not to be confused with a graded negative recommendation). <b>Unresolved count discrepancy:</b> the document announces 36 recommendations (1 GRADE 1, 3 GRADE 2, 29 AE, 3 absences) in its summary, but the body of the text contains only 34 (1 GRADE 1, <b>4</b> GRADE 2, <b>26</b> AE, 3 absences) — checked twice by a complete re-read of the 17 questions; discrepancy inherent to the source, not resolved.","style":"badge_head"}]]},{"t":"section","text":"Field 1 — Indication for procedural sedation in the emergency setting","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Item","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Peripheral trauma procedures","style":"cell_b"},{"t":"p","html":"For peripheral trauma procedures (reduction of a dislocation or fracture), the experts suggest that a trained physician perform local or regional anesthesia as an effective and safe alternative to procedural sedation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Other painful procedures","style":"cell_b"},{"t":"p","html":"For the performance of painful procedures (other than peripheral trauma), the experts suggest not favoring an alternative to procedural sedation, none having demonstrated better efficacy or tolerance.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 2 — At-risk patients: when to proceed, or not to proceed?","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Item","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Pre-sedation assessment","style":"cell_b"},{"t":"p","html":"The experts suggest using the ASA scale before sedation in order to identify patients at risk of complications (ASA score — table below).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Morbid obesity — indication","style":"cell_b"},{"t":"p","html":"In patients with morbid obesity (BMI ≥ 40 kg/m²), the experts suggest considering them at high risk of respiratory events and discussing the indication case by case, making sure that the necessary resources can be mobilized.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Morbid obesity — modalities","style":"cell_b"},{"t":"p","html":"If sedation cannot be delayed in a patient with morbid obesity (BMI > 40 kg/m²): titrate the drugs, dose on ideal body weight for highly lipophilic agents (midazolam, propofol, fentanyl, sufentanil), and reinforce respiratory monitoring during/after.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"OSAHS","style":"cell_b"},{"t":"p","html":"In a patient with known or suspected obstructive sleep apnea-hypopnea syndrome (OSAHS — STOP-BANG questionnaire, table below), the experts suggest taking into account the increased risk of respiratory complications in order to make sedation safe.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Elderly patient — titration","style":"cell_b"},{"t":"p","html":"In elderly patients, the experts suggest titrating sedative agents to reduce the total dose administered, in order to maintain efficacy and safety.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Elderly patient — drugs","style":"cell_b"},{"t":"p","html":"In elderly patients, the experts suggest preferentially using propofol alone or combined with ketamine.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Non-fasting patient","style":"cell_b"},{"t":"p","html":"The experts suggest not delaying procedural sedation in order to respect fasting, for safety purposes.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Acute alcohol intoxication / impaired consciousness","style":"cell_b"},{"t":"p","html":"The literature does not allow a recommendation to be made on performing procedural sedation in a patient with impaired consciousness in the context of acute alcohol intoxication.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Opioids received — monitoring","style":"cell_b"},{"t":"p","html":"In a patient who has received more than 0.15 mg/kg of IV morphine equivalent, and/or an opioid less than 15 min before sedation, the experts suggest prolonging monitoring of vital signs (Tmax delays of strong opioids — table below).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Opioids — avoid before sedation","style":"cell_b"},{"t":"p","html":"The experts suggest not administering an IV or transmucosal opioid to an emergency patient if procedural sedation is planned within 30 minutes, when an analgesic of equivalent efficacy is available.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>ASA</b>","style":"cell_b"},{"t":"p","html":"<b>Definition</b>","style":"cell_b"}],[{"t":"p","html":"ASA I","style":"cell"},{"t":"p","html":"Normal healthy person.","style":"cell"}],[{"t":"p","html":"ASA II","style":"cell"},{"t":"p","html":"Mild organic disease, well controlled, without target-organ involvement.","style":"cell"}],[{"t":"p","html":"ASA III","style":"cell"},{"t":"p","html":"Severe organic disease without short-term life threat, with functional limitation.","style":"cell"}],[{"t":"p","html":"ASA IV","style":"cell"},{"t":"p","html":"Disabling organic disease that is a constant threat to life.","style":"cell"}],[{"t":"p","html":"ASA V","style":"cell"},{"t":"p","html":"Moribund patient, life expectancy < 24h without surgery.","style":"cell"}],[{"t":"p","html":"ASA VI","style":"cell"},{"t":"p","html":"Brain-dead state, organ donor.","style":"cell"}]]},{"t":"p","html":"Table 3 of the source — ASA (American Society of Anesthesiologists) score, reproduced in full.","style":"source"},{"t":"table","rows":[[{"t":"p","html":"<b>STOP-<br/>BANG</b>","style":"cell_b"},{"t":"p","html":"<b>Item (1 point if yes)</b>","style":"cell_b"}],[{"t":"p","html":"S","style":"cell"},{"t":"p","html":"Loud snoring (louder than talking / audible through a closed door).","style":"cell"}],[{"t":"p","html":"T","style":"cell"},{"t":"p","html":"Frequent tiredness/sleepiness during the day.","style":"cell"}],[{"t":"p","html":"O","style":"cell"},{"t":"p","html":"Observed stops in breathing during sleep.","style":"cell"}],[{"t":"p","html":"P","style":"cell"},{"t":"p","html":"Known or treated high blood pressure.","style":"cell"}],[{"t":"p","html":"B","style":"cell"},{"t":"p","html":"BMI > 35 kg/m².","style":"cell"}],[{"t":"p","html":"A","style":"cell"},{"t":"p","html":"Age > 50 years.","style":"cell"}],[{"t":"p","html":"N","style":"cell"},{"t":"p","html":"Neck circumference > 41 cm (female) or > 43 cm (male).","style":"cell"}],[{"t":"p","html":"G","style":"cell"},{"t":"p","html":"Male sex.","style":"cell"}]]},{"t":"p","html":"Table 4 of the source (Chung et al., 2008) — probability of OSAHS: low 0-2, intermediate 3-4, high ≥ 5.","style":"source"},{"t":"section","text":"Field 3 — Safety conditions","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Item","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Capnography","style":"cell_b"},{"t":"p","html":"The experts suggest using continuous capnography in order to reduce the incidence of hypoxemia and to detect apnea earlier.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Oxygenation — indication","style":"cell_b"},{"t":"p","html":"It is recommended to administer oxygen by high-concentration mask before and during the procedure in order to reduce the occurrence of hypoxemic episodes.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Oxygenation — monitoring","style":"cell_b"},{"t":"p","html":"The experts suggest careful clinical monitoring of ventilation in addition to capnography, since oxygenation may delay the detection of hypoventilation or apnea.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Criteria for calling the anesthesiologist (MAR)","style":"cell_b"},{"t":"p","html":"Criteria requiring a call to an anesthesiologist-intensivist (MAR): respiratory depression requiring bag-valve-mask ventilation despite airway opening by mandibular subluxation; SBP < 90 mmHg despite 500 mL of crystalloids; poorly tolerated arrhythmia; vomiting with suspected aspiration; failure of the procedure despite the protocol being respected; need for orotracheal intubation; cardiorespiratory arrest.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 4 — How to perform it (1/2)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Item","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Repeated assessment","style":"cell_b"},{"t":"p","html":"The experts suggest that the depth of sedation be reassessed repeatedly, in particular with a non-dissociative sedative agent, until normal alertness returns.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Sedation scale — protocol","style":"cell_b"},{"t":"p","html":"The experts suggest that a sedation scale be detailed and its use encouraged in a departmental protocol.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Choice of scale","style":"cell_b"},{"t":"p","html":"Since none has been validated in the emergency medicine setting, the experts cannot recommend one over another among the Ramsay score, the OAA/S or the ASA definitions of the sedation continuum (including dissociative sedation, specific to ketamine).","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Midazolam + opioids","style":"cell_b"},{"t":"p","html":"It is recommended not to use the midazolam + opioid combination for procedural sedation.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ketamine + propofol","style":"cell_b"},{"t":"p","html":"It is recommended to use the ketamine-propofol combination in comparison with ketamine alone or propofol alone.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ketamine + propofol — dosing","style":"cell_b"},{"t":"p","html":"Suggested initial dose: ketamine 0.5 mg/kg + propofol 0.5 mg/kg, to be titrated in steps of 0.25 mg/kg, with vigilance beyond a total dose of 1 mg/kg.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Slow injection","style":"cell_b"},{"t":"p","html":"The experts suggest slow intravenous injection (for example 30 seconds to 1 minute) for the administration of the drugs.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"One syringe per drug","style":"cell_b"},{"t":"p","html":"When drugs are combined, the experts suggest using one syringe per drug.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Remimazolam","style":"cell_b"},{"t":"p","html":"Given the literature data, the experts are not able to make a recommendation regarding the use of remimazolam.","style":"cell"},{"t":"chip","label":"0/"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Drug / route</b>","style":"cell_b"},{"t":"p","html":"<b>Form</b>","style":"cell_b"},{"t":"p","html":"<b>Time to peak plasma concentration (Tmax)</b>","style":"cell_b"}],[{"t":"p","html":"Morphine IV","style":"cell"},{"t":"p","html":"Injection","style":"cell"},{"t":"p","html":"5–10 min","style":"cell"}],[{"t":"p","html":"Morphine SC","style":"cell"},{"t":"p","html":"Injection","style":"cell"},{"t":"p","html":"30–60 min","style":"cell"}],[{"t":"p","html":"Morphine oral","style":"cell"},{"t":"p","html":"Immediate release","style":"cell"},{"t":"p","html":"30–90 min","style":"cell"}],[{"t":"p","html":"Morphine oral","style":"cell"},{"t":"p","html":"Extended release","style":"cell"},{"t":"p","html":"2–4 h","style":"cell"}],[{"t":"p","html":"Oxycodone oral","style":"cell"},{"t":"p","html":"Immediate release","style":"cell"},{"t":"p","html":"1–2 h","style":"cell"}],[{"t":"p","html":"Oxycodone oral","style":"cell"},{"t":"p","html":"Extended release","style":"cell"},{"t":"p","html":"3–4 h","style":"cell"}],[{"t":"p","html":"Fentanyl buccal/sublingual","style":"cell"},{"t":"p","html":"Tablet/film","style":"cell"},{"t":"p","html":"20–60 min","style":"cell"}],[{"t":"p","html":"Fentanyl transdermal","style":"cell"},{"t":"p","html":"Patch","style":"cell"},{"t":"p","html":"12–24 h (steady state 48–72 h)","style":"cell"}],[{"t":"p","html":"Fentanyl IV","style":"cell"},{"t":"p","html":"Injection","style":"cell"},{"t":"p","html":"2–5 min","style":"cell"}],[{"t":"p","html":"Hydromorphone oral","style":"cell"},{"t":"p","html":"Immediate release","style":"cell"},{"t":"p","html":"30–60 min","style":"cell"}],[{"t":"p","html":"Hydromorphone IV","style":"cell"},{"t":"p","html":"Injection","style":"cell"},{"t":"p","html":"5 min","style":"cell"}]]},{"t":"p","html":"Tables 5+6 of the source, merged — Tmax delays of strong opioids (used in the emergency setting, or that may have been received before the procedure), to be read alongside the recommendations on opioids (Field 2).","style":"source"},{"t":"section","text":"Field 4 — How to perform it (2/2)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Item","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Cardioversion — technique","style":"cell_b"},{"t":"p","html":"The experts suggest brief, titrated procedural sedation, to allow the shock while limiting the risk of hemodynamic worsening.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Cardioversion — drugs to avoid","style":"cell_b"},{"t":"p","html":"The experts suggest not using midazolam or opioids for cardioversion.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Cardioversion — drug","style":"cell_b"},{"t":"p","html":"The experts suggest favoring propofol monotherapy.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Cardioversion — propofol dosing","style":"cell_b"},{"t":"p","html":"Titration in 20 mg steps, with particular vigilance beyond 0.5 mg/kg.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Post-sedation monitoring","style":"cell_b"},{"t":"p","html":"It is recommended to use continuous monitored surveillance (ECG, non-invasive BP, SpO2) for at least the first 30 minutes after the end of the procedure.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Monitoring — capnography","style":"cell_b"},{"t":"p","html":"The experts suggest using capnography in addition to oximetry, for early detection of hypoventilation and apnea after the procedure.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Score for stopping monitored surveillance","style":"cell_b"},{"t":"p","html":"The experts suggest using the Modified Aldrete Score System (MASS) with a threshold ≥ 9/10 (table below).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Hospital discharge score","style":"cell_b"},{"t":"p","html":"The experts suggest using the modified Post-Anesthetic Discharge Scoring System (mPADSS) with a threshold ≥ 9/10 (table below).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Checklist / protocol","style":"cell_b"},{"t":"p","html":"The experts suggest that the procedure be supported by a departmental protocol or a checklist (pre-procedure safety briefing — see below).","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>MASS — item</b>","style":"cell_b"},{"t":"p","html":"<b>Scoring</b>","style":"cell_b"}],[{"t":"p","html":"Respiration","style":"cell"},{"t":"p","html":"Deep breathing and cough = 2; dyspnea/shallow = 1; apnea = 0.","style":"cell"}],[{"t":"p","html":"SpO2","style":"cell"},{"t":"p","html":">92 % on room air = 2; needs O2 to stay >90 % = 1; <90 % even on O2 = 0.","style":"cell"}],[{"t":"p","html":"Consciousness","style":"cell"},{"t":"p","html":"Fully awake = 2; arousable when called = 1; unresponsive = 0.","style":"cell"}],[{"t":"p","html":"Circulation (vs pre-procedure baseline)","style":"cell"},{"t":"p","html":"BP ± 20 mmHg = 2; BP ± 20 to 50 mmHg = 1*; BP ± 50 mmHg = 0.","style":"cell"}],[{"t":"p","html":"Activity","style":"cell"},{"t":"p","html":"4 limbs = 2; 2 limbs = 1; unable to move a limb = 0.","style":"cell"}]]},{"t":"p","html":"Table 7 of the source — MASS, discharge threshold ≥ 9/10. *Source typo disclosed: the document literally writes \"= 50\" for this item (inconsistent with the 2/1/0 scoring of the 4 other items) — value \"1\" retained here by deduction, not verifiable otherwise.","style":"source"},{"t":"table","rows":[[{"t":"p","html":"<b>mPADSS — item</b>","style":"cell_b"},{"t":"p","html":"<b>Scoring</b>","style":"cell_b"}],[{"t":"p","html":"Vital signs (BP, HR vs baseline)","style":"cell"},{"t":"p","html":"Margin ≤ 20 % = 2; margin 20-40 % = 1*; margin > 40 % = 0.","style":"cell"}],[{"t":"p","html":"Activity","style":"cell"},{"t":"p","html":"Steady gait = 2; needs help = 1; unable to ambulate = 0.","style":"cell"}],[{"t":"p","html":"Nausea/vomiting","style":"cell"},{"t":"p","html":"Minimal/oral = 2; moderate/parenteral = 1; severe/refractory = 0.","style":"cell"}],[{"t":"p","html":"Pain","style":"cell"},{"t":"p","html":"0-3 = 2; 4-6 = 1; 7-10 = 0.","style":"cell"}],[{"t":"p","html":"Surgical bleeding","style":"cell"},{"t":"p","html":"No dressing change = 2; up to 2 = 1; > 3 = 0.","style":"cell"}]]},{"t":"p","html":"Table 8 of the source — mPADSS, discharge threshold ≥ 9/10. *Source typo disclosed: the value of this item (\"margin 20-40 %\") is absent from the text of the document itself (sentence interrupted without a figure, confirmed by visual rendering of the page) — \"1\" completed here by deduction from the 2/1/0 scoring of the other items.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Pre-procedure safety briefing</b> (table 1 of the source, attached to the checklist/protocol recommendation above): distribution of roles and responsibilities; organization of care (planned level and duration, criteria for starting); verification of identity and side of the lesion; verification of equipment (e.g. functional suction); location of rescue devices and drugs; anticipation of complications.","style":"body_sm"}},{"t":"section","text":"Sources and disclaimer","color":"grey"},{"t":"p","html":"<b>Source document:</b> SFMU/SFAR, \"Procedural sedation in the emergency medicine setting\" (\"Sédation procédurale en structure de médecine d'urgence\"), Formalized Expert Recommendations (RFE), up to date at 25/06/2026.","style":"source"},{"t":"p","html":"<b>Source URL:</b> https://sfar.org/sedation-procedurale-en-structure-de-medecine-durgence/","style":"source"},{"t":"p","html":"<b>Coverage:</b> the 34 recommendations actually counted in the body of the text (17 PICO questions, Fields 1 to 4) are reproduced in full (GRADE 1: 1, GRADE 2: 4, expert opinion: 26, no recommendation: 3). The document itself announces 36 recommendations in its summary (1 GRADE 1, 3 GRADE 2, 29 AE, 3 absences) — discrepancy disclosed, see the legend on the first page; not resolved for lack of an identifiable additional recommendation after a complete re-read. Clinically updates/supersedes the fiche \"Procedural sedation in the emergency medicine setting\" (SFMU/SFAR RFE 2010, kept on this site for its historical value). Detailed scientific rationale (studies, sample sizes, p-values, same document) not included; GRADE/PICO methodology (table 2) and organization flowchart (figure 1) not included (non-clinical).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this fiche is an independent summary of the recommendations of this reference document. It does not replace the full text or the scientific rationale. This fiche is neither published nor validated by the SFMU or the SFAR.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"Midazolam + opiacés","ref_en":"Midazolam + opioids","grade":"1+","fr":"Il est recommandé de ne pas utiliser l'association midazolam + opiacés pour une sédation procédurale.","en":"It is recommended not to use the midazolam + opioid combination for procedural sedation."},{"ref":"Kétamine + propofol","ref_en":"Ketamine + propofol","grade":"2+","fr":"Il est recommandé d'utiliser l'association kétamine-propofol en comparaison à la kétamine seule ou au propofol seul.","en":"It is recommended to use the ketamine-propofol combination in comparison with ketamine alone or propofol alone."},{"ref":"Oxygénation — indication","ref_en":"Oxygenation — indication","grade":"2+","fr":"Il est recommandé d'administrer une oxygénation par masque à haute concentration avant et pendant la procédure afin de réduire la survenue d'épisodes d'hypoxémie.","en":"It is recommended to administer oxygen by high-concentration mask before and during the procedure in order to reduce the occurrence of hypoxemic episodes."},{"ref":"Capnographie","ref_en":"Capnography","grade":"AE","fr":"Les experts suggèrent d'utiliser la capnographie en continu afin de diminuer l'incidence des hypoxémies et de détecter plus précocement les apnées.","en":"The experts suggest using continuous capnography in order to reduce the incidence of hypoxemia and to detect apnea earlier."},{"ref":"Surveillance post-sédation","ref_en":"Post-sedation monitoring","grade":"2+","fr":"Il est recommandé d'utiliser une surveillance scopée continue (ECG, PA non invasive, SpO2) pendant au moins les 30 premières minutes après la fin de la procédure.","en":"It is recommended to use continuous monitored surveillance (ECG, non-invasive BP, SpO2) for at least the first 30 minutes after the end of the procedure."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER (polarité / grade) : la recommandation R4.2.1 « il est recommandé de NE PAS utiliser l'association midazolam + opiacés » (ligne « Midazolam + opiacés ») porte la puce « 1+ ». La source imprime « GRADE 1 (recommandation forte) » sans signe et précise que le GRADE 1 couvre à la fois « il est recommandé de faire » et « il n'est pas recommandé de faire ». La puce « + » (= « pour l'intervention » dans la légende de la fiche) est donc trompeuse pour une recommandation négative, et incohérente avec la convention « ne pas = - » utilisée dans d'autres fiches du dépôt (ex. voies aériennes 2026, nutrition 2026). Décision attendue du relecteur : « GRADE 1 » sans signe, ou « 1- ». La version anglaise recopie « 1+ » à l'identique (aucun grade modifié).","À VÉRIFIER (grades) : le signe +/- de toutes les puces GRADE 1/2 (1+, 2+) est déduit (la source imprime « GRADE 1 » / « GRADE 2 » seuls) — contraire au CDC §4.1 (« jamais déduit »). Valider ou retirer les signes.","À VÉRIFIER (écart de décompte non résolu) : la synthèse de la source annonce 36 recommandations (1 GRADE 1, 3 GRADE 2, 29 AE, 3 absences ; « accord fort » pour 33) alors que le corps du texte n'en contient que 34 (1 / 4 / 26 / 3). Divergence signalée dans la fiche française (légende, couverture, méta) et reprise telle quelle en anglais. À trancher par le relecteur en confrontant la source ; ne pas publier « 34 » ou « 36 » avant cet arbitrage.","À VÉRIFIER (valeurs déduites dans les scores) : (a) MASS, item Circulation « PA ± 20 à 50 mmHg » : la source imprime littéralement « = 50 » (dans les deux exemplaires du score, tableau 7 et annexe) ; la fiche retient « 1* » par déduction du barème 2/1/0. (b) mPADSS, item Constantes vitales « marge 20 % à 40 % » : la valeur est absente du tableau 8 (phrase interrompue), mais l'exemplaire du score présent en annexe de la source (texte extrait, ~ligne 3718 de sources/sedation_procedurale_2026.txt) imprime « = 1 » — la déduction est donc corroborée par la source elle-même ; l'astérisque et la note de la fiche (« complété par déduction ») pourraient être révisés en conséquence. Les deux notes sont traduites telles quelles.","À VÉRIFIER (doses) : kétamine 0,5 mg/kg + propofol 0,5 mg/kg (palier 0,25 mg/kg, vigilance > 1 mg/kg) ; propofol cardioversion palier 20 mg, vigilance > 0,5 mg/kg ; seuil morphinique 0,15 mg/kg équivalent morphine IV ; sédation non différée à 30 min — recopiés à l'identique (contrôle automatique des nombres et unités FR/EN sans écart) mais à re-confronter à la source lors de la relecture médicale.","À VÉRIFIER (droits) : les tableaux ASA, STOP-BANG (Chung et al., 2008), Tmax des opioïdes, MASS et mPADSS reprennent des tableaux de la source (elle-même adaptée de références tierces) ; CDC §12.4 : reformulation éditoriale, pas de reproduction à l'identique — statut juridique à valider avant publication.","À VÉRIFIER : notes internes de l'atelier (« trouvé via recherche web », « absent de library_final.json », « voir légende en première page ») dans l'introduction, la couverture et la méta ; à retirer avant publication. Sigles traduits : MAR → anesthesiologist-intensivist (MAR), BAVU → bag-valve-mask, SAOS → OSAHS, IMC → BMI, PAS → SBP ; « OAA/S », « Ramsay », « STOP-BANG » conservés.","À VÉRIFIER (relevé par l'audit de traduction, présent à l'identique dans la fiche française) : (a) seuil d'IMC de l'obésité morbide « ≥ 40 kg/m² » (indication) mais « > 40 kg/m² » (modalités) dans deux lignes voisines ; (b) barème mPADSS « saignement chirurgical » : « jusqu'à 2 changements de pansement = 1 ; > 3 = 0 » — la valeur 3 n'est attribuée à aucune classe (le texte de la source imprime « plus de trois »). À comparer à la source lors de la relecture ; la traduction est fidèle à la fiche française."]$mgjson$::jsonb, '2026-06-25', 'da418416813d1959f871160d220f8176666933491cb4c2b2a9e6ca1d02204972', true
from public.documents d where d.fiche_key = 'sedation_procedurale_2026'
