  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"GRADE","title":"Traumatic brain injury — neurosurgical management","short":"Poor-prognosis factors (frailty, mydriasis, delay), acute extradural and subdural hematomas, depressed skull fractures and osteodural breaches, penetrating injuries (SPIN score), post-traumatic hydraulic disorders, pediatric particularities (neonatal EDH, shaken baby syndrome, ping-pong fracture). Appendices GOSE, mFI-5, SPIN.","society":"SFNC, avec SFNCP/SFNCL/ANARLF/SFAR/GFRUP/SFNR/SPILF/SOFMER — RPP 2025","version":"2025","validated":"V1.13, 19/03/2025, published on 19/09/2025","methodology":"GRADE"}$mgjson$::jsonb, $mgjson${"v":1,"key":"traumatisme_cranien","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Introduction, methodology","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Field:</b> neurosurgical management of traumatic brain injuries (TBI) in adults and children requiring a neurosurgical procedure at the initial phase. SFNC committee, with SFNCP, SFNCL, ANARLF, SFAR, GFRUP, SFNR, SPILF, SOFMER; GRADE® method, PICO format, 7 fields / 15 questions. <b>Explicit exclusions of the source</b> (already covered by other existing recommendations): external ventricular drainage and decompressive craniectomy, in adults as well as in children.<br/><br/><b>Results (official summary):</b> 45 items formulated; strong agreement obtained for all of them from the first round of rating. Of these 45 items, 43 are actual recommendations (39 expert opinions + 4 \"GRADE 2\") and 2 are explicit \"ABSENCE OF RECOMMENDATION\" — which reconciles the figure \"43\" displayed on the sfar.org page with the figure \"45\" of the official summary of the document itself: both are correct, they simply do not count the same thing.<br/><br/><i>First RPP led specifically by neurosurgery since 2006 — the existing French recommendations on TBI (SFAR/SFMU on mild and severe TBI, cerebral monitoring) did not cover the indications and modalities of the neurosurgical procedures themselves.</i>","style":"body"}},{"t":"section","text":"Grade legend","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"2+"},{"t":"p","html":"It is probably recommended","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"It is probably not recommended","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Expert opinion","style":"badge_head"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Simplified GRADE methodology</b> — this RPP includes neither a \"GRADE 1\" tier nor a +/- suffix printed on its tags (unlike the classic RFEs on the site): only two levels literally exist in the source text, \"GRADE 2 (STRONG AGREEMENT)\" and \"EXPERT OPINION (STRONG AGREEMENT)\". The direction (+/-) of each \"GRADE 2\" is here deduced from the literal wording of the sentence itself — \"it is probably recommended to…\" = 2+, \"it is probably not recommended to…\" = 2- — and not retyped from a source tag that does not specify it. <b>Source inconsistency noted</b> (verified by visual rendering of page 11): R6.4 uses the Grade 2 verbal formula (\"it is probably recommended\") but is literally tagged \"EXPERT OPINION\" — the printed tag prevails (chipped \"AE\" below), inconsistency reported rather than silently corrected.","style":"body_sm"}}]},{"title":"Field 1 — Poor-prognosis factors","items":[{"t":"section","text":"Field 1 — Poor-prognosis factors (emergency craniotomy, adult)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"In a patient with severe TBI theoretically requiring emergency craniotomy, but presenting characteristics considered \"beyond hope\" (leaving no prospect of a favorable prognosis), early neurosurgical abstention (before 72h) must systematically be the subject of a collegial decision, involving whenever possible three senior physicians (neurosurgeon, anesthesiologist-intensivist, rehabilitation physician).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"During on-call periods, a \"restricted collegiality\" must be implemented, involving at least 2 senior physicians to allow a better assessment of the prognosis.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"In a patient with severe TBI requiring emergency craniotomy, it is probably recommended to consider pathological frailty indices to assess the prognosis, but not in isolation to contraindicate the procedure.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"The following scores (detailed in the appendix below) may be considered pathological for assessing the prognosis: mFI-5 ≥ 2; Clinical Frailty Scale ≥ 4.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3","style":"cell_b"},{"t":"p","html":"In a patient with severe TBI requiring emergency craniotomy, the presence at presentation of non-reactive, non-regressive bilateral mydriasis (ideally assessed by automated pupillometry) must be considered a poor-prognosis factor, but must not be considered in isolation to contraindicate the procedure, in particular if the mydriasis has been present for less than 2h.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4","style":"cell_b"},{"t":"p","html":"In a patient with severe TBI requiring emergency craniotomy, the delay to management must not be taken into account in isolation in the assessment of the prognosis and the neurosurgical decision.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R5.1","style":"cell_b"},{"t":"p","html":"In patients requiring emergency craniotomy, in particular those over 65 years, it is probably recommended to consider, non-isolatedly, the presence of anticoagulant treatment (VKA or DOAC) as a poor-prognosis factor, but without this contraindicating the procedure in isolation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R5.2","style":"cell_b"},{"t":"p","html":"In a patient with severe TBI requiring emergency craniotomy, it is probably not recommended to consider the presence of antiplatelet treatment with aspirin monotherapy as a poor-prognosis factor; this must not influence the surgical indication.","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"p","html":"Early WLST (withdrawal/limitation of life-sustaining therapies, \"LATA\", &lt;72h) are the leading cause of death after severe TBI (45-87 % of in-hospital mortality). Bilateral non-reactive mydriasis: favorable outcome (GOSE&gt;4) in only 6.6 % of ASDH vs 54.3 % of EDH (meta-analysis, 82 patients); ultra-early decompression surgery (≤2h) = ~1 chance in 3 of survival. Prior anticoagulant treatment: significant excess mortality in many studies (OR 1.3 to 5.2 depending on the cohorts) — dual antiplatelet therapy (OR 4.66), warfarin (OR 5.18), DOAC (OR 5.09). Aspirin monotherapy: no difference in mortality found (review of 2447 patients on antiplatelet agents vs 4814 controls).","style":"note"},{"t":"table","rows":[[{"t":"p","html":"mFI-5 (frailty index)","style":"head_w"},{"t":"p","html":"Items (+1 each)","style":"head_w"},{"t":"p","html":"Interpretation","style":"head_w"}],[{"t":"p","html":"mFI-5","style":"cell"},{"t":"p","html":"Diabetes • Hypertension • Congestive heart failure (acute pulmonary edema &lt;30d) • COPD • Dependent (non-independent)","style":"cell"},{"t":"p","html":"0 = not frail • 1 = vulnerable • ≥2 = frail","style":"cell"}]]}]},{"title":"Field 2 — Extradural hematomas","items":[{"t":"section","text":"Field 2 — Extradural hematomas","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R6.1","style":"cell_b"},{"t":"p","html":"In a patient with TBI associated with an extradural hematoma (EDH), emergency surgical evacuation must be performed in one or more of the following circumstances: GCS ≤ 8; mydriasis; volume &gt; 30 mL; midline shift &gt; 5 mm; brainstem compression; sign of active bleeding (swirl sign).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R6.2","style":"cell_b"},{"t":"p","html":"Conservative treatment must be favored in case of EDH of arterial origin without clinical and radiological signs of severity (see R6.1).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R6.3","style":"cell_b"},{"t":"p","html":"For an EDH of venous origin, the benefit-risk balance of conservative management must be assessed case by case, including in the presence of signs of severity, given the surgical difficulties (dural sinus tear).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R6.4","style":"cell_b"},{"t":"p","html":"If conservative treatment is decided, close clinical monitoring must be carried out in a center with a neurosurgery department.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R6.5","style":"cell_b"},{"t":"p","html":"In case of conservative treatment, it is probably recommended to perform a systematic control CT scan at 6 hours post-trauma (if the first CT scan was done before H6), or earlier in case of clinical worsening.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"EDH &gt;25-30mL = increased risk of neurological deterioration. Swirl sign (active bleeding): present in 14-30 % of EDH, mean GOS 3.58 vs 4.43 without this sign. Posterior fossa EDH: surgery if volume &gt;10mL, thickness &gt;15mm or shift &gt;5mm (Brain Trauma Foundation). 98.1 % of EDH reach their final size between 5 and 6h post-trauma — hence the targeted control CT scan at H6; repeated CT scan at 2h if early clinical deterioration. Particular attention if a contralateral lesion is operated (risk of rapid worsening of the remaining EDH after contralateral decompression).","style":"note"}]},{"title":"Field 3 — Acute subdural hematomas","items":[{"t":"section","text":"Field 3 — Acute subdural hematomas","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R7.1","style":"cell_b"},{"t":"p","html":"Emergency surgical evacuation of an acute subdural hematoma (ASDH) must be performed in the following circumstances, cumulatively: age &lt;65 years (or 65-80 years with a low frailty score) AND impaired consciousness (GCS≤8 and/or GCS≤12 but rapid loss of ≥2 GCS points) not explained by another mechanism, or refractory intracranial hypertension AND radiological criteria (thickness &gt;10mm and/or midline shift &gt;5mm).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R7.2","style":"cell_b"},{"t":"p","html":"In case of rebleeding within a chronic subdural hematoma, delayed, less invasive surgery must be considered.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R7.3","style":"cell_b"},{"t":"p","html":"Outside the circumstances above, conservative treatment must be preferred, with a control CT scan: urgently if unfavorable clinical course; early (7-10d) if antithrombotic treatment is reintroduced; at a distance (3-4 weeks) in other cases.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"Classic Brain Trauma Foundation criteria (GCS≤8 and/or thickness&gt;10mm and/or shift&gt;5mm) established on old series of young patients — nuanced here by age and frailty. Initial GCS of 3: mortality 65-100 %. Bilateral mydriasis associated with an ASDH: mortality 66.4 %, favorable outcome (GOS≥4) in only 6.6 % (meta-analysis, 82 patients). Surgical benefit demonstrated on mortality (absolute reduction 23-40 %) but not on neurological outcome (2 concordant recent studies, including the CENTER-TBI cohort, 1407 patients).","style":"note"}]},{"title":"Field 4 — Depressed skull fractures & osteodural breaches","items":[{"t":"section","text":"Field 4 — Depressed skull fractures and osteodural breaches of the skull base","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R8.1","style":"cell_b"},{"t":"p","html":"In case of depressed skull fracture, rapid surgical management (within 24h) must be performed, in order to improve the neurological or cosmetic prognosis, in one or more of the following circumstances: complex/contaminated wound or signs of local infection; suspected dural tear/pneumocephalus; CSF leak; significant mass effect; other neurosurgical lesion(s); major cosmetic damage.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R8.2","style":"cell_b"},{"t":"p","html":"In case of depressed fracture of the frontal sinuses, reduction/osteosynthesis of the anterior wall must be performed, in the absence of a major defect of the posterior wall, an obvious dural breach, or involvement of the nasofrontal ducts. Otherwise, the procedure must be completed by cranialization of the frontal sinuses.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R8.3","style":"cell_b"},{"t":"p","html":"In case of non-penetrating TBI associated with a depressed fracture and a seizure, secondary antiepileptic prophylaxis must be initiated; primary prophylaxis must not be systematic.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R9.1","style":"cell_b"},{"t":"p","html":"In case of traumatic osteomeningeal breach (BOM), rapid surgery (within 24h) must be performed only in case of a major dural defect associated with abundant CSF leak. If there is a neurosurgical indication for other associated lesions, closure of the BOM during the same operative session is not advised in case of intracranial hypertension.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R9.2","style":"cell_b"},{"t":"p","html":"Surgery must be considered in case of non-abundant CSF leak refractory to conservative treatment beyond 7 days.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R9.3","style":"cell_b"},{"t":"p","html":"Conservative treatment of BOM must be combined with bed rest with the head of the bed raised at 30°, as well as prescription of laxatives, antitussives and antiemetics for at least 72h.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R9.4","style":"cell_b"},{"t":"p","html":"The following vaccinations must be performed or updated: anti-pneumococcal (15-valent conjugate vaccine in those under 18 years, 1 dose in those over 2 years; or 20-valent in those over 18 years, 1 dose not followed by a non-conjugate vaccine); anti-Haemophilus influenzae (1 dose); anti-meningococcal B and ACYW (catch-up according to the general recommendations: meningococcus ABCYW before 2 years and ACYW before 25 years).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R9.5","style":"cell_b"},{"t":"p","html":"The search for a traumatic BOM must begin with a CT scan in bone window (millimetric slices) and an MRI including high-resolution 3DT2 sequences. In case of persistent doubt, CT myelography followed by radionuclide cisternography may be performed.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"Depressed fractures: lesions generally of good prognosis; any open depressed fracture requires ruling out a dural breach (= penetrating TBI, field 5). Reconstruction preferably with titanium osteosynthesis. CSF leaks: occur in 0.3-39 % of skull base fractures; &gt;50 % within 48h, 70 % within 7d. Risk of meningitis: 0.24 % at 24h, cumulative ~1.3 %/day (first 15 days) then 7.4 %/week (1st month) — drop from 30.6 % (before surgery) to 4 % (after) in case of persistent leak. Conservative treatment (head raised 30° + laxatives/antitussives/antiemetics 48-72h): resolution in 39.5-68 % of cases on D2-3. Small defects (≤1cm): endoscopic endonasal approach; defects &gt;1cm: transcranial (high) approach. No systematic antibiotic prophylaxis in case of simple skull base fracture (SFAR/SPILF RFE 2023), except in case of neurosurgical intervention.","style":"note"}]},{"title":"Field 5 — Penetrating TBI","items":[{"t":"section","text":"Field 5 — Penetrating traumatic brain injuries","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R10.1","style":"cell_b"},{"t":"p","html":"The risk of mortality (SPIN score, Maritzburg score) must be assessed and taken into account, non-isolatedly, in the indication for emergency surgical intervention.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R10.2","style":"cell_b"},{"t":"p","html":"In a patient with a Glasgow score ≥ 5, emergency neurosurgical management must be offered.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R10.3","style":"cell_b"},{"t":"p","html":"Neurosurgical management must be discussed case by case for patients with a Glasgow score ≤ 4, in the absence of non-reactive bilateral mydriasis and in the absence of CT lesions of poor prognosis (see criteria below).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R10.4","style":"cell_b"},{"t":"p","html":"In case of major cortical destruction, primary antiepileptic prophylaxis must be given for a period of at least 7 days, in order to reduce the short-term seizure risk.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R10.5","style":"cell_b"},{"t":"p","html":"The following vaccinations must be performed or updated: in a person not up to date, tetanus vaccination combined with an injection of 250 IU of human tetanus immunoglobulin in case of extensive wound, penetrating with foreign body or treated late; anti-meningococcal B and ACYW (catch-up according to the general recommendations: meningococcus ABCYW before 2 years and ACYW before 25 years); anti-Haemophilus influenzae (1 dose); anti-pneumococcal (15-valent conjugate vaccine in those under 18 years, 1 dose in those over 2 years; or 20-valent in those over 18 years, 1 dose not followed by a non-conjugate vaccine).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R11.1","style":"cell_b"},{"t":"p","html":"Intracranial vascular lesions must be systematically sought by CT angiography.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R11.2","style":"cell_b"},{"t":"p","html":"This work-up must be completed by six-vessel digital subtraction cerebral angiography in the presence of one or more of the following factors: detection/doubt of a vascular lesion on CT angiography; pterional and/or fronto-orbital injury; multiple dural violation; trajectory/hematoma close to the main vascular axes; blast TBI (closed or penetrating) with GCS &lt;8; vasospasm on transcranial Doppler and/or unexplained spontaneous drop in PtiO2.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R11.3","style":"cell_b"},{"t":"p","html":"In case of symptomatic or asymptomatic intracranial vascular lesion at high risk of rupture and/or neurological worsening, emergency treatment must be discussed.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence of recommendation</b> — on the modality (endovascular or surgical) of treatment of a post-traumatic intracranial vascular lesion, which must be discussed collegially (R11.4).","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R11.5","style":"cell_b"},{"t":"p","html":"In the absence of identification of an initial intracranial vascular lesion, new cerebrovascular imaging must be repeated approximately 14 days after the trauma.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"Penetrating TBI: mortality up to 85 %; aggressive management increases survival. Initial GCS = main prognostic factor (0 % good prognosis if GCS 6-8 managed conservatively vs 24 % if operated; 77.8 % good results if GCS≥9 operated). Surgery ideally within 5h (reduction of infectious risk). Intracranial vascular lesions: up to 60 % of penetrating TBI; post-traumatic aneurysms 20-50 % incidence, mortality up to 50 % in case of rupture. Angiography = gold standard (CT angiography less sensitive). Early epilepsy (7d): 14-20 % incidence. Antibiotic prophylaxis: amoxicillin-clavulanic acid 2g, continued 24-48h if soiled wound (SFAR/SPILF RFE 2023).","style":"note"},{"t":"table","rows":[[{"t":"p","html":"SPIN score (prognosis of penetrating TBI)","style":"head_w"},{"t":"p","html":"Items","style":"head_w"},{"t":"p","html":"Points","style":"head_w"}],[{"t":"p","html":"SPIN","style":"cell"},{"t":"p","html":"Motor GCS (1-5 → 0; 6 → 9) • Pupils (bilaterally non-reactive → 0; unilateral → 4; ruptured globe → 6; normal → 9) • Self-inflicted injury (yes → 0; no → 4) • Transfer from another hospital (no → 0; yes → 4) • Sex (male → 0; female → 4) • ISS (≥56 → 0; 41-55 → 1; 25-40 → 5; ≤24 → 10) • INR (≥2.1 → 0; 1.4-2 → 6; ≤1.3 → 12)","style":"cell"},{"t":"p","html":"Score ≥ 35: 98 % survival. Score ≤ 20: 3 % survival.","style":"cell"}]]},{"t":"p","html":"<b>CT criteria of poor prognosis in penetrating TBI:</b> multilobar or bihemispheric trajectory (excluding bilateral frontal lobe lesions) • trans-ventricular trajectory • trajectory crossing the geographic center of the brain • oblique trajectory in the 3 planes (x, y and z) • diffuse fragmentation • large volume of contused brain • major intracerebral hemorrhage • subarachnoid hemorrhage • posterior fossa wound with brainstem involvement • \"tram-track\" sign (hemorrhage on either side of a dark central track in a perforating wound) • midline shift &gt; 10 mm • compressed or obliterated basal cisterns.","style":"body_sm"}]},{"title":"Field 6 — Post-traumatic hydraulic disorders","items":[{"t":"section","text":"Field 6 — Post-traumatic hydraulic disorders","color":"navy"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Two entities to distinguish</b> — <b>Hygroma:</b> CSF collection generally stable (rarely progressive), unilateral, no neurological sign, normal ICP. <b>External hydrocephalus:</b> progressive CSF collection (on successive CT scans), generally bilateral, AND neurological worsening AND/OR elevated ICP.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R12.1","style":"cell_b"},{"t":"p","html":"In case of hygroma, conservative treatment must be given as first-line.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R12.2","style":"cell_b"},{"t":"p","html":"In case of external hydrocephalus, the CSF must be drained (lumbar puncture or external lumbar drain), after confirmation on CT scan of: patency of the basal cisterns AND absence of midline shift &gt; 10mm AND absence of tonsillar herniation. In case of intracranial hypertension, this option must be considered only after failure of first-line measures.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R12.3","style":"cell_b"},{"t":"p","html":"In case of external lumbar drain for external hydrocephalus, the reference zero must be placed at the level of the external auditory meatus. In case of intracranial hypertension, continuous ICP monitoring must be performed, and the lumbar drainage back-pressure must not be lowered below 10 mmHg. Lumbar drainage must be interrupted in case of a pressure gradient &gt; 5 mmHg between the ICP and the lumbar CSF pressure.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"Systematic review of 10 studies (221 patients) on external lumbar drain (ELD) in TBI: mean ICP reduction of -17.1 mmHg (-59.1 %). Complications: meningitis 5.7 % (12/208), tonsillar herniation 7.1 % (21/295) — occurring mainly in studies with back-pressure 0 or +5cmH2O. CT criteria used in all studies: free basal cisterns, no significant mass effect, no shift &gt;5-10mm, no uncal/tonsillar herniation. External lumbar drainage was not retained as a therapeutic measure for post-traumatic intracranial hypertension by the 2019 Seattle international conference.","style":"note"}]},{"title":"Field 7 — Pediatric particularities","items":[{"t":"section","text":"Field 7 — Pediatric particularities","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R13.1","style":"cell_b"},{"t":"p","html":"In the newborn (&lt;1 month) with TBI associated with an extradural hematoma (EDH), emergency surgical evacuation must be performed in the presence of clinical or radiological signs of severity (midline shift &gt;5mm, brainstem compression).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R13.2","style":"cell_b"},{"t":"p","html":"In the absence of consensus on the optimal surgical technique, less invasive approaches must be favored before resorting to craniotomy: puncture of the cephalohematoma, puncture via a skull fracture, or epidural puncture (notably if EDH without fracture or cephalohematoma).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R13.3","style":"cell_b"},{"t":"p","html":"In the absence of signs of severity (see R13.1), a conservative approach must be favored, with close monitoring in an intensive care unit (frequent clinical examinations and control imaging).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R14.1","style":"cell_b"},{"t":"p","html":"In the infant (&lt;2 years) with non-accidental TBI associated with a subdural hematoma, rapid surgical management must be performed, preferably by drainage.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence of recommendation</b> — on the use of decompressive craniectomy in non-accidental TBI in infants (R14.2).","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Ref.","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R14.3","style":"cell_b"},{"t":"p","html":"Conservative management must be considered in the presence of a chronic subdural hematoma of small thickness (&lt;10mm), well tolerated clinically, with close monitoring and imaging control.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R15.1","style":"cell_b"},{"t":"p","html":"In the infant (&lt;2 years) with a depressed \"ping-pong\" type fracture, emergency surgical management must be performed in case of intracranial hypertension, or significant mass effect on the parenchyma, or intracranial hematoma, or peri-encephalic CSF collection.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R15.2","style":"cell_b"},{"t":"p","html":"In the absence of the above criteria, conservative management must be favored initially; surgical management may be re-evaluated in the absence of favorable evolution.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"Neonatal EDH: rare (incidence of post-instrumental intracranial hemorrhages 0.4-1 %), often of venous origin, tendency to liquefy rapidly — conservative approach if thickness &lt;20mm, without shift or clinical deterioration; surgery if volume &gt;30mL, thickness &gt;15mm, shift &gt;5mm. Neonatal craniotomy: avoid fixation with osteosynthesis material (subsequent skull growth). Shaken baby syndrome (infant SDH): entity with no adult equivalent (blood + CSF mixture); poor prognosis correlated with initial clinical severity, not with shunt complications; transfontanellar subdural puncture as first-line if intracranial hypertension, subdural-peritoneal shunt if recurrence; role of decompressive craniectomy not established in this specific context (\"Big Black Brain\" on admission = contraindication). \"Ping-pong\" fracture: incidence 1-2.5/10 000 live births; review of 228 infants — 30 % surgery, 30 % aspiration, 40 % conservative, &gt;96 % favorable neurological outcome whatever the type of management.","style":"note"}]},{"title":"Summary, appendices, sources & traceability","items":[{"t":"section","text":"Summary and key messages","color":"navy"},{"t":"p","html":"• Decision of early neurosurgical abstention (before 72h) = always collegial (3 senior physicians, or 2 in restricted on-call). Frailty (mFI-5≥2, CFS≥4), non-reactive bilateral mydriasis and delay to management = prognostic factors to consider but never decisive in isolation.<br/>• EDH: emergency evacuation if GCS≤8, mydriasis, volume&gt;30mL, shift&gt;5mm, brainstem compression, swirl sign. Conservative if arterial without severity or venous case by case — control CT scan at H6.<br/>• ASDH: emergency evacuation if age&lt;65 years (or low frailty) AND impaired consciousness/refractory intracranial hypertension AND thickness&gt;10mm/shift&gt;5mm. Conservative otherwise, with CT scan adapted to the context.<br/>• Depressed skull fracture: surgery within 24h if complex/contaminated wound, dural breach/pneumocephalus, CSF leak, mass effect, or major cosmetic damage. Frontal sinuses: preserve if posterior wall/nasofrontal ducts intact, otherwise cranialize. Osteomeningeal breach: surgery if major defect + abundant CSF leak, otherwise conservative (head raised 30°, laxatives/antitussives/antiemetics ≥72h) then surgery if failure &gt;7d.<br/>• Penetrating TBI: GCS≥5 → emergency neurosurgical management; GCS≤4 without mydriasis or unfavorable CT criteria → case-by-case discussion. Systematic CT angiography ± six-vessel angiography according to criteria. Surgery ideally &lt;5h. Vaccinations and antibiotic prophylaxis up to date.<br/>• Hydraulic disorders: hygroma = conservative; external hydrocephalus = drainage after strict CT verification (free cisterns, shift&lt;10mm, no herniation).<br/>• Pediatrics: neonatal EDH often manageable medically (minimally invasive approaches before craniotomy); non-accidental infant SDH = rapid drainage, severity correlated with the initial clinical presentation; \"ping-pong\" fracture = conservative unless signs of severity, favorable prognosis in &gt;96 % of cases whatever the management.","style":"body"},{"t":"section","text":"Appendices — GOSE","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"GOSE","style":"head_w"},{"t":"p","html":"Level","style":"head_w"},{"t":"p","html":"Outcome","style":"head_w"}],[{"t":"p","html":"1","style":"cell"},{"t":"p","html":"Death","style":"cell"},{"t":"p","html":"Poor neurological outcome","style":"cell"}],[{"t":"p","html":"2","style":"cell"},{"t":"p","html":"Vegetative state","style":"cell"},{"t":"p","html":"Poor neurological outcome","style":"cell"}],[{"t":"p","html":"3","style":"cell"},{"t":"p","html":"Lower severe disability (totally dependent)","style":"cell"},{"t":"p","html":"Poor neurological outcome","style":"cell"}],[{"t":"p","html":"4","style":"cell"},{"t":"p","html":"Upper severe disability (highly dependent)","style":"cell"},{"t":"p","html":"Poor neurological outcome","style":"cell"}],[{"t":"p","html":"5","style":"cell"},{"t":"p","html":"Lower moderate disability (partially dependent)","style":"cell"},{"t":"p","html":"Good neurological outcome","style":"cell"}],[{"t":"p","html":"6","style":"cell"},{"t":"p","html":"Upper moderate disability (partial return to work/school)","style":"cell"},{"t":"p","html":"Good neurological outcome","style":"cell"}],[{"t":"p","html":"7","style":"cell"},{"t":"p","html":"Lower good recovery (mild sequelae)","style":"cell"},{"t":"p","html":"Good neurological outcome","style":"cell"}],[{"t":"p","html":"8","style":"cell"},{"t":"p","html":"Upper good recovery (complete recovery)","style":"cell"},{"t":"p","html":"Good neurological outcome","style":"cell"}]]},{"t":"section","text":"Sources and traceability","color":"grey"},{"t":"p","html":"<b>Source document:</b> \"Neurosurgical management of traumatic brain injuries in adults and children at the initial phase\" (\"Prises en charge neurochirurgicales des traumatismes cranio-encéphaliques de l'adulte et de l'enfant à la phase initiale\") — RPP of the SFNC, with SFNCP/SFNCL/ANARLF/SFAR/GFRUP/SFNR/SPILF/SOFMER. V1.13, 19/03/2025 (R. Manet, A. Dagain, H. de Courson, J.F. Payen), published on sfar.org on 19/09/2025.","style":"source"},{"t":"p","html":"<b>Methodology:</b> simplified GRADE® with 2 levels (\"GRADE 2\" and \"Expert opinion\", without \"GRADE 1\" tier or printed +/- suffix) — the +/- direction of each \"GRADE 2\" is deduced from the literal wording of the sentence, disclosure on page 1. Source inconsistency noted and reported (R6.4, verified by visual rendering) rather than silently corrected.","style":"source"},{"t":"p","html":"<b>Coverage:</b> 45 items reproduced in full (R1.1-R15.2) — 43 actual recommendations + 2 \"Absence of recommendation\" (R11.4, R14.2). Appendices reproduced: GOSE (above), mFI-5 (Field 1), SPIN score and CT criteria of poor prognosis in penetrating TBI (Field 5). The Clinical Frailty Scale (9 levels), transcribed from a source image (page 50, without text layer), is not fully reproduced here for reasons of space — refer to the full text for its complete version; only the threshold retained by the experts (CFS ≥ 4 = frail) is cited (R2.2). Explicit exclusions of the source itself: external ventricular drainage and decompressive craniectomy (adult and child), already covered by other existing recommendations.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this document is an independent summary fiche, produced as a memory aid. It reproduces all the recommendations of the RPP but does not replace the full text and is neither published nor validated by the SFNC/SFAR. In case of doubt, refer to the full text, subsequent recommendations and/or a specialist opinion.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"R1.1","grade":"AE","fr":"Chez le patient présentant un TC grave, nécessitant théoriquement une craniotomie en urgence, mais présentant des caractéristiques jugées « dépassées » (ne laissant aucun espoir de pronostic favorable), l'abstention neurochirurgicale précoce (avant 72h) doit systématiquement faire l'objet d'une décision collégiale, impliquant chaque fois que possible trois médecins séniors (neurochirurgien, anesthésiste-réanimateur, médecin rééducateur).","en":"In a patient with severe TBI theoretically requiring emergency craniotomy, but presenting characteristics considered \"beyond hope\" (leaving no prospect of a favorable prognosis), early neurosurgical abstention (before 72h) must systematically be the subject of a collegial decision, involving whenever possible three senior physicians (neurosurgeon, anesthesiologist-intensivist, rehabilitation physician)."},{"ref":"R2.1","grade":"2+","fr":"Chez un patient victime de TC grave nécessitant une craniotomie en urgence, il est probablement recommandé de considérer les indices de fragilité pathologiques pour évaluer le pronostic, mais pas de manière isolée pour contre-indiquer le geste.","en":"In a patient with severe TBI requiring emergency craniotomy, it is probably recommended to consider pathological frailty indices to assess the prognosis, but not in isolation to contraindicate the procedure."},{"ref":"R3","grade":"AE","fr":"Chez un patient présentant un TC grave nécessitant une craniotomie en urgence, la présence à la prise en charge d'une mydriase bilatérale aréactive non régressive (idéalement évaluée par pupillométrie automatisée) doit être considérée comme un facteur de mauvais pronostic, mais ne doit pas être considérée de manière isolée pour contre-indiquer le geste, en particulier si la mydriase est installée depuis moins de 2h.","en":"In a patient with severe TBI requiring emergency craniotomy, the presence at presentation of non-reactive, non-regressive bilateral mydriasis (ideally assessed by automated pupillometry) must be considered a poor-prognosis factor, but must not be considered in isolation to contraindicate the procedure, in particular if the mydriasis has been present for less than 2h."},{"ref":"R6.1","grade":"AE","fr":"Chez le patient présentant un TC associé à un hématome extra-dural (HED), il faut réaliser l'évacuation chirurgicale en urgence dans l'une ou plusieurs des circonstances suivantes : GCS ≤ 8 ; mydriase ; volume &gt; 30 mL ; déviation de la ligne médiane &gt; 5 mm ; compression du tronc cérébral ; signe de saignement actif (swirl sign).","en":"In a patient with TBI associated with an extradural hematoma (EDH), emergency surgical evacuation must be performed in one or more of the following circumstances: GCS ≤ 8; mydriasis; volume &gt; 30 mL; midline shift &gt; 5 mm; brainstem compression; sign of active bleeding (swirl sign)."},{"ref":"R7.1","grade":"AE","fr":"Il faut réaliser l'évacuation chirurgicale en urgence d'un hématome sous-dural aigu (HSDA) dans les circonstances suivantes, cumulativement : âge &lt;65 ans (ou 65-80 ans avec score de fragilité faible) ET troubles de vigilance (GCS≤8 et/ou GCS≤12 mais perte rapide de ≥2 points de GCS) non expliqués par un autre mécanisme, ou HTIC réfractaire ET critères radiologiques (épaisseur &gt;10mm et/ou déviation de la ligne médiane &gt;5mm).","en":"Emergency surgical evacuation of an acute subdural hematoma (ASDH) must be performed in the following circumstances, cumulatively: age &lt;65 years (or 65-80 years with a low frailty score) AND impaired consciousness (GCS≤8 and/or GCS≤12 but rapid loss of ≥2 GCS points) not explained by another mechanism, or refractory intracranial hypertension AND radiological criteria (thickness &gt;10mm and/or midline shift &gt;5mm)."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER (grades, déjà signalé dans la fiche française) : la source ne porte que « GRADE 2 (ACCORD FORT) » et « AVIS D'EXPERTS (ACCORD FORT) », sans signe ni GRADE 1 ; le signe des 4 puces GRADE 2 (R2.1 = 2+, R5.1 = 2+, R5.2 = 2-, R6.5 = 2+) a été déduit du libellé (« il est probablement recommandé » / « il n'est probablement pas recommandé »). Le CDC (§4.1) interdit tout grade déduit : valider ce codage ou remplacer par « GRADE 2 ». La version anglaise recopie les puces à l'identique et traduit à l'identique la déclaration de méthodologie.","À VÉRIFIER (incohérence source, déjà signalée) : R6.4 est présentée comme utilisant la formule « il est probablement recommandé » mais taguée « AVIS D'EXPERTS » (puce AE, le tag imprimé faisant foi). Le libellé de la ligne R6.4 affichée dans la fiche (« il faut effectuer une surveillance clinique rapprochée… ») ne contient pas cette formule, contrairement à R6.5 (« il est probablement recommandé de réaliser un scanner… », puce 2+) : le relecteur doit confirmer sur la page 11 de la source que la disclosure vise bien la bonne ligne. Traduit tel quel.","À VÉRIFIER (décompte) : 45 items (R1.1-R15.2) = 43 recommandations + 2 absences (R11.4, R14.2) ; la page web sfar.org annonce « 43 », le résumé officiel « 45 » — divergence expliquée dans la fiche (les deux chiffres comptent des choses différentes) et reprise en anglais ; à confirmer par le relecteur avant d'afficher un nombre de recommandations.","À VÉRIFIER (périmètre partiel) : l'échelle Clinical Frailty Scale (9 niveaux, transcrite d'une image source sans couche texte) n'est pas reproduite (seul le seuil CFS ≥ 4 est cité) ; la source exclut elle-même dérivation ventriculaire externe et craniectomie décompressive.","À VÉRIFIER (termes) : TC → TBI, HED → EDH, HSDA → ASDH, HTIC → intracranial hypertension, LATA → WLST (withdrawal/limitation of life-sustaining therapies, glosé), embarrure → depressed skull fracture, BOM (brèche ostéoméningée) conservé en sigle, hygrome → hygroma, « syndrome du bébé secoué » → shaken baby syndrome ; « PtiO2 », « swirl sign », « Big Black Brain », scores SPIN / Maritzburg, GOSE conservés. Les doses et seuils (vaccins, immunoglobulines antitétaniques 250 UI, amoxicilline-acide clavulanique 2 g, seuils de volume/épaisseur/déviation, mmHg) sont recopiés à l'identique : le contrôle automatique FR/EN des nombres et unités ne relève aucun écart.","À VÉRIFIER (fiche très volumineuse en contenu de discussion) : les paragraphes de synthèse de la littérature (OR, pourcentages, séries de patients) sont traduits intégralement pour rester fidèles à la fiche française ; le relecteur peut décider de ne pas les publier (les statistiques citées sont propres à la source et n'ont pas été recontrôlées ici).","À VÉRIFIER (sigle) : « RPP » n'est pas développé dans la fiche française ni traduit (« First RPP led specifically by neurosurgery… ») ; à confirmer avec la source (recommandation pour la pratique professionnelle ?). « voie haute » (fuite de LCS, défect > 1 cm) rendu « transcranial (high) approach »."]$mgjson$::jsonb, '2025-09-19', 'd9d2cb83a98c1f9d7b79fba455914f6e120e2d09064e60c219bed80059efbf84', true
from public.documents d where d.fiche_key = 'traumatisme_cranien'
on conflict (document_id, lang) do update set
  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"SFAR/SFMU/SRLF — RBP HAS, 03/09/2026","title":"Organization of the management of in-hospital life-threatening emergencies","short":"SFAR/SFMU/SRLF (+ CARO/ADARPEF/GFRUP/SFPC), \"Recommendations for the organization of the management of in-hospital life-threatening emergencies\" (\"Recommandations pour l'organisation de la prise en charge des urgences vitales intra-hospitalières\", UVIH), RBP (good practice recommendation) endorsed by the HAS, adopted by the HAS Board (Collège) on 3 September 2026 — published on the same day as \"Management of the adult airway in the operating room\", very recent document found through a web search (absent from this site's usual index at the date of its publication). Covers 4 fields: setting up and triggering the UVIH pathway (written institutional procedure, advance reflection on the level of therapeutic commitment, single number such as \"2222\"), material conditions and human resources (standardization of emergency carts and response bags, minimum team composition), monitoring and operating arrangements (institutional registry, morbidity and mortality reviews, breaking news to relatives, mandatory FGSU2 training), and organizational specificities (facilities without continuous medical presence, mixed adult/pediatric activity, visitors and staff). 39 recommendations (grade 2: 4, expert opinion: 30, no recommendation: 4, regulatory obligation: 1), verified by cross-checking against the summary table of the source document itself. Notable disclosed particularity: one recommendation (FGSU2 training) is labelled \"regulatory obligation\" by the source, not a GRADE recommendation — a reminder of an existing legal obligation (Order of 3 March 2006 as amended), given a distinct chip rather than merged into the expert opinions. Inconsistency in the title of Field 3 in the source's summary table disclosed (corrected here by cross-checking against the table of contents). The 2 visual cognitive aids (adult/child) published separately by the SFAR are not reproduced here — disclosed, direct links in the Sources section.","society":"SFAR / SFMU / SRLF / CARO / ADARPEF / GFRUP / SFPC","version":"2026","validated":"HAS Board (Collège de la HAS) (RBP endorsement, 03/09/2026)","methodology":"GRADE grid — grade 2 (weak recommendation, the only numeric tier present), AE (expert opinion), no recommendation (chip \"0/\"), regulatory obligation (chip \"RÉGL\", outside GRADE) — 39 recommendations (grade 2: 4, AE: 30, 0/: 4, RÉGL: 1)"}$mgjson$::jsonb, $mgjson${"v":1,"key":"urgences_vitales_ih_2026","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Organization of the management of in-hospital life-threatening emergencies","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Very recent document</b> (adopted by the HAS Board on 3 September 2026, published on the same day as \"Management of the adult airway in the operating room\") — found outside this repository's usual process (absent from <code>library_final.json</code> at the date of its publication), through a web search. <b>Scope:</b> hospitalized adult, pediatric and pregnant patients, as well as visitors/staff of the facility in a life-threatening emergency. <b>Not reproduced here</b> (disclosed): 2 visual cognitive aids (adult/child) published separately by the SFAR — direct links in the Sources section.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"2+"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"chip","label":"RÉGL"},{"t":"p","html":"<b>GRADE grid</b> — <b>2+</b>: weak/optional recommendation FOR the intervention (the only numeric tier present here — no strong \"grade 1\" recommendation in this document); <b>AE</b>: expert opinion; <b>0/</b>: no recommendation (insufficient data); <b>RÉGL</b>: regulatory obligation (not a GRADE recommendation — reminder of an existing legal obligation, 1 occurrence, disclosed). Very recent document: adopted by the HAS Board on 3 September 2026.","style":"badge_head"}]]},{"t":"section","text":"Field 1 — Setting up and triggering the UVIH pathway","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"UVIH pathway","style":"cell_b"},{"t":"p","html":"It is recommended to set up an institutional UVIH pathway in order to improve the quality of patient care.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Written procedure","style":"cell_b"},{"t":"p","html":"The experts suggest that an institutional UVIH procedure be drawn up by a multidisciplinary team with an identified medical lead.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Written procedure","style":"cell_b"},{"t":"p","html":"The experts suggest a written, explicit, standardized institutional UVIH procedure accessible to all, comprising 4 components: early detection, activation, intervention and debriefing.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Therapeutic commitment","style":"cell_b"},{"t":"p","html":"The experts suggest that the drafting of the UVIH procedure be accompanied, beforehand, by advance reflection on the level of individual therapeutic commitment of hospitalized patients in the event of clinical deterioration.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Therapeutic commitment","style":"cell_b"},{"t":"p","html":"The experts suggest that this advance reflection may lead, where appropriate, to a collegial procedure in accordance with the French Public Health Code (LAT — limitation or withdrawal of treatment; art. L1110-5-1 and R4127-37-2), a decision to be recorded in the medical file.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Early warning scores","style":"cell_b"},{"t":"p","html":"In hospitalized patients (adults and children), the literature does not allow a conclusion on a benefit of early warning scores compared with clinical monitoring based on vital signs alone.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Single number","style":"cell_b"},{"t":"p","html":"It is recommended to set up a single number for triggering the specialized team.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Single number","style":"cell_b"},{"t":"p","html":"The experts suggest, in line with European proposals, that this single number be \"2222\".","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Single number","style":"cell_b"},{"t":"p","html":"The experts suggest that this number be reachable via DECT phones, hospital landlines and professional mobile phones.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Call triage","style":"cell_b"},{"t":"p","html":"Outside the obstetric setting, the literature is insufficient to determine whether call triage by a person who is not a member of the specialized team improves management.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Call triage","style":"cell_b"},{"t":"p","html":"In obstetric patients, the experts suggest NOT setting up call triage by a person who is not a member of the specialized team.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 2 — Material conditions and human resources","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Emergency cart","style":"cell_b"},{"t":"p","html":"It is recommended to standardize emergency carts within a given facility.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Emergency cart","style":"cell_b"},{"t":"p","html":"For facilities with adult, pediatric and neonatal activity, the experts suggest distinguishing standardized adult, pediatric and neonatal carts, positioned according to the activity of the units.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Emergency cart","style":"cell_b"},{"t":"p","html":"For units with specific needs, the experts suggest keeping the additional necessary equipment close to the emergency cart.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Emergency cart","style":"cell_b"},{"t":"p","html":"The experts suggest that each unit ensure the maintenance of the sealed emergency cart.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Emergency cart","style":"cell_b"},{"t":"p","html":"The literature does not allow an exhaustive list of the specific equipment of emergency carts, applicable to all facilities, to be issued.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Response bag","style":"cell_b"},{"t":"p","html":"The literature does not allow an exhaustive, applicable list of the specific equipment of the specialized UVIH team's response bag to be recommended.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Response bag","style":"cell_b"},{"t":"p","html":"At facility level, the experts suggest standardizing the specific equipment of the specialized UVIH team's response bag.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Response bag","style":"cell_b"},{"t":"p","html":"The experts suggest that the response bag include, at a minimum, the equipment needed to: oxygenate/ventilate/access the airway; connect to a monitor and monitor; establish IV/IO access and administer IV/IO drugs; manage cardiac arrest and shock.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Response bag","style":"cell_b"},{"t":"p","html":"The experts suggest that the UVIH response team have BOTH an adult bag AND a pediatric bag.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Response bag","style":"cell_b"},{"t":"p","html":"The experts suggest that the units taking part in UVIH teams ensure the maintenance of their sealed response bags.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Obstetrics","style":"cell_b"},{"t":"p","html":"In the event of cardiac arrest in a pregnant woman, the experts suggest that the specialized obstetric UVIH team travel with a surgical kit for an on-site cesarean section.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Cognitive aids","style":"cell_b"},{"t":"p","html":"The experts suggest that first responders to a UVIH use a cognitive aid placed on the emergency carts.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Team composition","style":"cell_b"},{"t":"p","html":"When the facility has on-site medical cover competent in critical care, the experts suggest that the specialized UVIH team include at least one senior physician and one registered nurse, trained in the management of life-threatening emergencies.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 3 — Monitoring and operating arrangements of the pathway","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Monitoring","style":"cell_b"},{"t":"p","html":"The experts suggest setting up a single institutional registry for monitoring the UVIH pathway.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Monitoring","style":"cell_b"},{"t":"p","html":"The experts suggest setting up regular morbidity and mortality reviews devoted to monitoring the UVIH pathway.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Breaking news to relatives","style":"cell_b"},{"t":"p","html":"In the event of death following a UVIH, the experts suggest that breaking the news to relatives (with priority to the person of trust) be carried out and documented by the physician responsible for the patient or, failing that, the physician who intervened, accompanied if possible by the caregivers who took part in the care.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Breaking news to relatives","style":"cell_b"},{"t":"p","html":"The experts suggest that the organization of breaking news to relatives be formalized in the institutional UVIH procedure.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Presence of relatives","style":"cell_b"},{"t":"p","html":"When conditions allow, the experts suggest offering relatives the option of being present during cardiopulmonary resuscitation if they wish.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Training — obligation","style":"cell_b"},{"t":"p","html":"In accordance with French legislation (Order of 3 March 2006 as amended, art. L4021-1 of the Public Health Code), it is MANDATORY for all healthcare professionals to hold a valid certificate of Level 2 Emergency Procedures and Care Training (CESU).","style":"cell"},{"t":"chip","label":"RÉGL"}],[{"t":"p","html":"Training","style":"cell_b"},{"t":"p","html":"It is recommended to train healthcare professionals in the management of a UVIH by simulation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Training","style":"cell_b"},{"t":"p","html":"The experts suggest that facilities formalize, with the support of the CESU (emergency care teaching centers), a structured institutional UVIH training program, with traceability and monitoring of coverage and performance indicators.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Training","style":"cell_b"},{"t":"p","html":"The experts suggest that the training cover detection of clinical deterioration, alerting, activation of specialized teams and management of life-threatening emergencies.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Training","style":"cell_b"},{"t":"p","html":"The experts suggest that cardiac arrest resuscitation training in non-UVIH teams be repeated annually.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Training","style":"cell_b"},{"t":"p","html":"The experts suggest that training be delivered in a multiprofessional group and accompanied by a debriefing led by trained staff.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 4 — Organizational specificities & sources","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Without 24/7 medical presence","style":"cell_b"},{"t":"p","html":"During periods with medical presence competent in critical care, the experts suggest that the organization of UVIH management be similar to that usually recommended, even without a downstream critical care unit.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Without 24/7 medical presence","style":"cell_b"},{"t":"p","html":"During periods without medical presence competent in critical care, the experts suggest that the initial response rely on local intervention protocols and immediate recourse to the SAMU (French emergency medical service).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mixed adult/pediatric activity","style":"cell_b"},{"t":"p","html":"In facilities with mixed activity that have a physician competent in pediatric critical care, the experts suggest distinguishing two separate UVIH teams and procedures (adult and child).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Visitor / staff member","style":"cell_b"},{"t":"p","html":"For a visitor or staff member in a UVIH situation, the experts suggest following the same procedure as for hospitalized patients.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources and disclaimer","color":"grey"},{"t":"p","html":"<b>Source document:</b> SFAR/SFMU/SRLF (+ CARO/ADARPEF/GFRUP/SFPC), \"Recommendations for the organization of the management of in-hospital life-threatening emergencies\" (\"Recommandations pour l'organisation de la prise en charge des urgences vitales intra-hospitalières\"), Good Practice Recommendation (RBP) endorsed by the HAS, adopted by the HAS Board (Collège) on 3 September 2026.","style":"source"},{"t":"p","html":"<b>Source URL:</b> https://sfar.org/organisation-de-la-prise-en-charge-des-urgences-vitales-intra-hospitalieres/","style":"source"},{"t":"p","html":"<b>Visual tools not reproduced here (disclosed):</b> UVIH cognitive aid — ADULT, UVIH cognitive aid — CHILD, both published separately and downloadable from the source URL above.","style":"source"},{"t":"p","html":"<b>Coverage:</b> the 39 recommendations of the document's summary table (Fields 1 to 4) are reproduced in full (grade 2: 4, AE: 30, no recommendation: 4, regulatory obligation: 1). Inconsistency in the title of \"Field 3\" in the source's summary table disclosed (see the script's docstring) — the correct title, confirmed by the table of contents and the Method section of the same document, is used here. Detailed scientific rationale (same document, not reproduced) not included.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this fiche is an independent summary of the 39 recommendations of this reference document. It does not replace the full text, the scientific rationale, or the cognitive aids published separately by the SFAR. This fiche is neither published nor validated by the SFAR, the HAS, or the associated societies.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"Filière UVIH","ref_en":"UVIH pathway","grade":"2+","fr":"Il est recommandé de mettre en place une filière UVIH institutionnelle afin d'améliorer la qualité de prise en charge des patients.","en":"It is recommended to set up an institutional UVIH pathway in order to improve the quality of patient care."},{"ref":"Numéro unique","ref_en":"Single number","grade":"2+","fr":"Il est recommandé de mettre en place un numéro unique pour le déclenchement de l'équipe spécialisée.","en":"It is recommended to set up a single number for triggering the specialized team."},{"ref":"Chariot d'urgence","ref_en":"Emergency cart","grade":"2+","fr":"Il est recommandé de standardiser les chariots d'urgence au sein d'un même établissement.","en":"It is recommended to standardize emergency carts within a given facility."},{"ref":"Formation","ref_en":"Training","grade":"2+","fr":"Il est recommandé de former les professionnels de santé à la prise en charge d'une UVIH par simulation.","en":"It is recommended to train healthcare professionals in the management of a UVIH by simulation."},{"ref":"Formation — obligation","ref_en":"Training — obligation","grade":"RÉGL","fr":"Conformément à la législation française (Arrêté du 3 mars 2006 modifié, art. L4021-1 du Code de la Santé Publique), il est OBLIGATOIRE que tous les professionnels de santé disposent d'une attestation valide de Formation aux Gestes et Soins d'Urgence de niveau 2 (CESU).","en":"In accordance with French legislation (Order of 3 March 2006 as amended, art. L4021-1 of the Public Health Code), it is MANDATORY for all healthcare professionals to hold a valid certificate of Level 2 Emergency Procedures and Care Training (CESU)."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER : le signe « + » des 4 puces « 2+ » n'est pas imprimé par la source (elle porte « grade 2 » seul) ; il a été ajouté lors de la construction de la fiche française parce que les 4 libellés sont formulés « il est recommandé de… » (pour l'intervention). Le cahier des charges (§4.1) interdit tout grade déduit : valider ce codage ou remplacer par « grade 2 » sans signe. La version anglaise recopie les puces françaises à l'identique.","À VÉRIFIER : la recommandation « Formation — obligation » porte la puce « RÉGL » (rappel d'une obligation légale : arrêté du 3 mars 2006 modifié, art. L4021-1 CSP), qui n'est pas un grade GRADE. Le statut de cet énoncé (recommandation ou simple rappel réglementaire) et la formulation exacte de la référence légale doivent être validés par le relecteur ; le libellé « Formation aux Gestes et Soins d'Urgence de niveau 2 (CESU) » est repris tel quel de la fiche française (la méta anglaise utilise l'abréviation « FGSU2 » du texte français ; l'intitulé officiel de la formation est à confirmer).","À VÉRIFIER : le PDF source utilisé pour la fiche française est le fichier étiqueté « ARGUMENTAIRE » (82 pages) sur sa page de garde, et non un fichier « Recommandation » distinct ; le tableau de synthèse (pages 63-67) a servi de texte de référence. Confirmer auprès de la page SFAR que ce fichier est bien la version de référence.","À VÉRIFIER : le titre du « Champ 3 » est erroné dans le tableau de synthèse de la source (même titre que le Champ 2) ; le titre corrigé (table des matières) est utilisé — divergence déjà signalée dans la fiche française et reprise à l'identique en anglais.","À VÉRIFIER : notes internes de l'atelier (« trouvé via recherche web », « absent de library_final.json », « voir docstring du script ») présentes dans l'introduction, la couverture et la méta ; traduites telles quelles, à retirer avant toute publication.","À VÉRIFIER : sigles français conservés faute d'équivalent anglais officiel : UVIH (urgences vitales intra-hospitalières), DECT, CESU, SAMU ; « FGSU2 » cité dans la méta."]$mgjson$::jsonb, '2026-09-03', 'f0c5d0e76a0b27c8f28e0b4661430c4354b8029618ca863a294fc56ee5a247be', true
from public.documents d where d.fiche_key = 'urgences_vitales_ih_2026'
on conflict (document_id, lang) do update set
  card_json = excluded.card_json, presentation_json = excluded.presentation_json,
  key_points = excluded.key_points, a_verifier = excluded.a_verifier,
  source_publication_date = excluded.source_publication_date, fr_a_jour = excluded.fr_a_jour,
  status = case when public.document_translations.content_sha256 = excluded.content_sha256
    then public.document_translations.status else 'brouillon' end,
  content_sha256 = excluded.content_sha256, imported_at = now();

insert into public.document_translations (document_id, lang, card_json, presentation_json, key_points, a_verifier, source_publication_date, content_sha256, fr_a_jour)
select d.id, 'en', $mgjson${"badge":"SFAR/CARORL/CARO/FHS/SFORL — RBP HAS, 03/09/2026","title":"Airway management in adults in the operating room","short":"SFAR/CARORL/CARO/FHS/SFORL (+ CORASSO), \"Airway management in adults in the operating room\" (\"Prise en charge des voies aériennes de l'adulte au bloc opératoire\"), Good Practice Recommendation (RBP) endorsed by the HAS, adopted by the HAS Board (Collège) on 3 September 2026 — very recent document, found through a web search (absent from this site's usual index at the date of its publication). Covers 3 fields: airways WITHOUT predictable difficulty (first-line videolaryngoscopy, 2nd-generation supraglottic devices, high-flow nasal oxygenation during procedural sedation, capnography), DIFFICULT airways whether anticipated or not (apneic oxygenation strategies, 2nd-generation supraglottic devices in case of difficult mask ventilation, SMS-technique cricothyroidotomy in a \"cannot intubate, cannot oxygenate\" situation), and human factors/organizational dimensions (simulation, competence-maintenance thresholds per technique, briefing/debriefing/defusing, morbidity and mortality review). 28 recommendations (grade 1: 1, grade 2: 13, expert opinion: 13, no recommendation: 1), verified by cross-checking against the summary table of the source document itself. CLINICALLY UPDATES/SUPERSEDES the fiches \"Difficult intubation and extubation in anesthesia in adults\" (RFE 2017) and \"Airway management in adult anesthesia, excluding difficult intubation\" (Consensus Conference 2002/2003), both kept on this site for their historical value. Explicitly excludes pediatrics and critical care (choice of the source). The 7 visual algorithms/cognitive aids published separately by the SFAR (printable tools) are not reproduced here — disclosed, direct links in the Sources section of the fiche.","society":"SFAR / CARORL / CARO / FHS / SFORL / CORASSO","version":"2026","validated":"HAS Board (Collège de la HAS) (RBP endorsement, 03/09/2026)","methodology":"GRADE grid — grade 1 (strong recommendation), grade 2 (weak recommendation), AE (expert opinion), no recommendation (chip \"0/\") — 28 recommendations (grade 1: 1, grade 2: 13, AE: 13, 0/: 1), no \"against\" recommendation graded numerically"}$mgjson$::jsonb, $mgjson${"v":1,"key":"voies_aeriennes_bloc_2026","lang":"en","chip_legend":{"1+/1-":"strong recommendation, for / against (GRADE)","2+/2-":"weak recommendation, for / against (GRADE)","AE":"expert opinion (avis d'experts) — label kept as in the French source","0/":"no recommendation (absence de recommandation)","RÉGL":"regulatory reminder, not a GRADE grade (rappel réglementaire)"},"sections":[{"title":"Airway management in adults in the operating room","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Very recent document</b> (adopted by the HAS Board on 3 September 2026) — found outside this repository's usual process (absent from <code>library_final.json</code> at the date of its publication), through a web search. <b>Updates/supersedes</b> two documents already covered by this repository: the <code>intubation_difficile_adulte</code> fiche (SFAR RFE 2017) for Field 2, and the <code>voies_aeriennes_adulte</code> fiche (SFAR Consensus Conference 2002/2003) for Field 1 — these two older fiches remain available on the site (historical value) but are clinically outdated by this reference document. <b>Explicit scope of the source:</b> adult patients in the operating room or interventional technical suite — explicitly excludes pediatrics and critical care. <b>Not reproduced here</b> (disclosed): 7 visual figures/algorithms (cognitive aids, decision flowcharts) published separately by the SFAR as standalone printable tools — direct links in the Sources section.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"2+"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>GRADE grid</b> — <b>1</b>: strong recommendation (high-quality randomized trials); <b>2</b>: weak recommendation (moderate quality or marginally relevant benefit) — the <b>+</b> suffix indicates a recommendation FOR the intervention (no \"against\" recommendation graded numerically in this document); <b>AE</b>: expert opinion (benefit/risk balance undetermined); <b>0/</b>: no recommendation (insufficient data, 1 occurrence). VLS = videolaryngoscope/videolaryngoscopy. Very recent document: adopted by the HAS Board on 3 September 2026.","style":"badge_head"}]]},{"t":"section","text":"Field 1 — Airways without predictable difficulty","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"VLS","style":"cell_b"},{"t":"p","html":"In the absence of predictive criteria for difficult intubation, it is recommended to use a videolaryngoscope as first-line rather than a direct laryngoscope to increase first-attempt success.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"VLS","style":"cell_b"},{"t":"p","html":"In the absence of predictive criteria for difficult intubation, it is recommended to use a videolaryngoscope as first-line rather than a direct laryngoscope to reduce the complications associated with tracheal intubation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Neuromuscular blockade","style":"cell_b"},{"t":"p","html":"In patients without predictive criteria for difficult intubation, the experts suggest administering a neuromuscular blocking agent when using a videolaryngoscope to facilitate tracheal intubation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Supraglottic devices","style":"cell_b"},{"t":"p","html":"Without risk factors for a full stomach, under controlled mechanical ventilation, when the positioning and the surgical technique allow it, it is recommended to prefer 2nd-generation supraglottic devices to tracheal intubation to reduce perioperative respiratory complications.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Supraglottic devices","style":"cell_b"},{"t":"p","html":"Without risk factors for a full stomach, for elective abdominopelvic surgery (including laparoscopic), it is recommended to prefer 2nd-generation supraglottic devices to tracheal intubation to reduce perioperative respiratory complications.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Supraglottic devices","style":"cell_b"},{"t":"p","html":"Without risk factors for a full stomach, under controlled mechanical ventilation, it is recommended to use 2nd-generation supraglottic devices in order to reduce the incidence of postoperative sore throat.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Obstetrics (>16 WA)","style":"cell_b"},{"t":"p","html":"In pregnant women after 16 weeks of amenorrhea (WA), under controlled mechanical ventilation, the experts suggest NOT using a supraglottic device rather than tracheal intubation, in order to reduce intraoperative respiratory complications.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Obstetrics (<16 WA)","style":"cell_b"},{"t":"p","html":"In pregnant women before 16 weeks of amenorrhea (WA), the experts suggest applying the recommendations in force for the adult patient in order to improve intraoperative respiratory safety.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Gastric ultrasound","style":"cell_b"},{"t":"p","html":"In adult patients, the literature does not allow a conclusion on the value of gastric ultrasound in the decision to perform rapid-sequence induction to prevent the risk of aspiration.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Procedural sedation","style":"cell_b"},{"t":"p","html":"For procedures and/or populations at risk of desaturation, it is recommended to use high-flow nasal oxygenation rather than low-flow oxygenation, to reduce the incidence of desaturation episodes during the procedure.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Procedural sedation","style":"cell_b"},{"t":"p","html":"For procedures and/or populations at risk of desaturation, it is recommended to use high-flow nasal oxygenation rather than low-flow oxygenation, to reduce procedure interruptions and upper-airway maneuvers.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Apneic sedation","style":"cell_b"},{"t":"p","html":"During an airway procedure performed in apnea without tracheal intubation, the experts suggest using high-flow nasal oxygenation rather than low-flow oxygen therapy, to delay desaturation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Capnography","style":"cell_b"},{"t":"p","html":"During procedural sedation with spontaneous ventilation, it is recommended to monitor capnography in order to detect any apnea and avoid desaturation, including with high-flow nasal oxygenation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Capnography","style":"cell_b"},{"t":"p","html":"During high-flow nasal oxygenation in apnea, the experts suggest minimizing the duration of apnea as much as possible, even in the absence of desaturation, to prevent the risk of hypercapnia.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Field 2 — Difficult airways (anticipated or not)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Preox. + HFNO","style":"cell_b"},{"t":"p","html":"After well-conducted preoxygenation, in case of anticipated difficult intubation in a patient who is a priori ventilable (including obese or full-stomach patients), it is recommended to set up high-flow nasal oxygenation during laryngoscopy, to prolong the time without desaturation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Obstetrics","style":"cell_b"},{"t":"p","html":"In obstetrics, in case of tracheal intubation without an indication to maintain spontaneous ventilation, the experts suggest maintaining nasal oxygenation (low or high flow) during the apneic phase, to prolong the time without desaturation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Video vs fiberscope","style":"cell_b"},{"t":"p","html":"In case of anticipated difficult intubation in a patient who is a priori NOT ventilable (indication to maintain spontaneous ventilation), provided there is sufficient mouth opening, an experienced operator and fiberoptic-guidance equipment available, it is recommended to use either videolaryngoscopy or fiberoptic bronchoscopy interchangeably to ensure successful intubation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Supraglottic devices","style":"cell_b"},{"t":"p","html":"In case of difficult intubation AND difficult mask ventilation (including in pregnant women), it is recommended to use a 2nd-generation supraglottic device as first-line rather than a 1st-generation device or an intubation-dedicated device (such as the LMA-Fastrach®), to rapidly restore oxygenation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Supraglottic devices","style":"cell_b"},{"t":"p","html":"After restoring effective ventilation through a 2nd-generation supraglottic device (including in pregnant women), in case of a formal indication for intubation, it is recommended to use a fiberscope rather than blind intubation to guide the tube.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"\"Cannot intubate, cannot oxygenate\"","style":"cell_b"},{"t":"p","html":"In case of impossible intubation AND ventilation despite a 2nd-generation supraglottic device (including in pregnant women), it is recommended to perform cricothyroidotomy as first-line using the SMS technique (Scalpel - long bent-tip introducer [mandrin long béquillé] - intubation tube), rather than other emergency subglottic access techniques.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Field 3 — Human factors & organizational dimensions","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Category","style":"head_w"},{"t":"p","html":"Recommendation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Initial training","style":"cell_b"},{"t":"p","html":"In the initial training of anesthesiology-critical care residents and IADE (nurse anesthetist) students in difficult airway management, it is recommended to organize a simulation program in addition to theoretical training, to improve individual and collective performance.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Continuing training","style":"cell_b"},{"t":"p","html":"In the continuing training of anesthesiologist-intensivists and IADEs, it is recommended to organize a simulation program in addition to theoretical training, to improve individual and collective performance.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Frequency of practice","style":"cell_b"},{"t":"p","html":"To prepare for difficult airway management, the experts suggest performing the procedures regularly (in simulation and/or in real situations), to improve individual and collective performance.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Briefing","style":"cell_b"},{"t":"p","html":"In anticipation of difficult airway management, the experts suggest holding a briefing involving all the actors concerned (and if possible the patient), to improve individual and collective performance.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mental preparation","style":"cell_b"},{"t":"p","html":"To prepare for difficult airway management, the experts suggest using mental preparation techniques, to improve individual and collective performance.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Defusing","style":"cell_b"},{"t":"p","html":"After a difficult airway management complicated by an adverse event, the experts suggest carrying out a \"defusing\" immediately after the event, to maintain psychological safety.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Debriefing","style":"cell_b"},{"t":"p","html":"After a difficult airway management, the experts suggest holding a debriefing involving all the actors concerned (IADE, anesthesiologist-intensivist, theatre nurse, surgeon), to improve future performance and provide support to the professionals.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"M&M review","style":"cell_b"},{"t":"p","html":"After a difficult airway management complicated by an adverse event, the experts suggest carrying out a morbidity and mortality review, to improve future individual and collective performance.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Table 1 — Minimum number of procedures for satisfactory performance (expert opinion)</b>","style":"body"},{"t":"table","rows":[[{"t":"p","html":"Technique","style":"head_w"},{"t":"p","html":"Threshold","style":"head_w"},{"t":"p","html":"Comment","style":"head_w"}],[{"t":"p","html":"Videolaryngoscopy","style":"cell"},{"t":"p","html":">15 procedures","style":"cell"},{"t":"p","html":"Learning to begin with simulation; maintenance of skills if the device is changed (>5 procedures).","style":"cell"}],[{"t":"p","html":"Videolaryngoscopy, hyperangulated blade","style":"cell"},{"t":"p","html":">12 procedures","style":"cell"},{"t":"p","html":"Learning by simulation; annual training such as a difficult-airway workshop.","style":"cell"}],[{"t":"p","html":"2nd-generation supraglottic device","style":"cell"},{"t":"p","html":">20 procedures","style":"cell"},{"t":"p","html":"Initial education in determining the leak pressure; maintenance if the device is changed (>5 procedures).","style":"cell"}],[{"t":"p","html":"Fiberoptic bronchoscopy for awake intubation","style":"cell"},{"t":"p","html":">15 procedures","style":"cell"},{"t":"p","html":"Learning by simulation; annual training such as a workshop.","style":"cell"}],[{"t":"p","html":"Fiberoptic bronchoscopy through a supraglottic device","style":"cell"},{"t":"p","html":">10 procedures","style":"cell"},{"t":"p","html":"Learning to begin with simulation.","style":"cell"}],[{"t":"p","html":"SMS technique (Scalpel-Bougie-Tube: \"Scalpel-Mandrin-Sonde\")","style":"cell"},{"t":"p","html":">3 procedures","style":"cell"},{"t":"p","html":"Learning exclusively outside the clinical setting.","style":"cell"}]]},{"t":"section","text":"Sources and disclaimer","color":"grey"},{"t":"p","html":"<b>Source document:</b> SFAR/CARORL/CARO/FHS/SFORL (+ CORASSO), \"Airway management in adults in the operating room\" (\"Prise en charge des voies aériennes de l'adulte au bloc opératoire\"), Good Practice Recommendation (RBP) endorsed by the HAS, adopted by the HAS Board (Collège) on 3 September 2026.","style":"source"},{"t":"p","html":"<b>Source URL:</b> https://sfar.org/prise-en-charge-des-voies-aeriennes-de-ladulte-au-bloc-operatoire/","style":"source"},{"t":"p","html":"<b>Visual tools not reproduced here (disclosed):</b> Algorithm for anticipated difficulties, Apnea strategy algorithm, Cognitive aid for intubation with spontaneous ventilation, Cognitive aid for difficult intubation in apnea, SMS-technique cricothyroidotomy, Briefing/debriefing cognitive aids, Difficult-airway certificate — all published separately and downloadable from the source URL above (\"Tools\" section).","style":"source"},{"t":"p","html":"<b>Coverage:</b> the 28 textual recommendations of the document (Fields 1 to 3) are reproduced in full (grade 1: 1, grade 2: 13, AE: 13, no recommendation: 1), verified by cross-checking against the summary table of the source itself. Updates/supersedes the fiches already on this site \"Difficult intubation and extubation in anesthesia in adults\" (RFE 2017) and \"Airway management in adult anesthesia, excluding difficult intubation\" (Consensus Conference 2002/2003), kept for their historical value. Explicitly excludes pediatrics and critical care (choice of the source itself). Detailed scientific rationale (separate document) not reproduced.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Disclaimer:</b> this fiche is an independent summary of the 28 textual recommendations of this reference document. It does not replace the full text, the scientific rationale, or the visual tools (algorithms, cognitive aids) published separately by the SFAR. This fiche is neither published nor validated by the SFAR, the HAS, or the associated societies.","style":"body_sm"}}]}]}$mgjson$::jsonb, $mgjson$[{"ref":"VLS","grade":"1+","fr":"En l'absence de critères prédictifs d'intubation difficile, il est recommandé d'utiliser un vidéolaryngoscope en première intention plutôt qu'un laryngoscope direct pour augmenter le succès à la première tentative.","en":"In the absence of predictive criteria for difficult intubation, it is recommended to use a videolaryngoscope as first-line rather than a direct laryngoscope to increase first-attempt success."},{"ref":"Dispositifs supraglott.","ref_en":"Supraglottic devices","grade":"2+","fr":"Sans facteur de risque d'estomac plein, sous ventilation mécanique programmée, lorsque l'installation et la technique chirurgicale le permettent, il est recommandé de privilégier les dispositifs supraglottiques de 2ème génération à l'intubation trachéale pour diminuer les complications respiratoires périopératoires.","en":"Without risk factors for a full stomach, under controlled mechanical ventilation, when the positioning and the surgical technique allow it, it is recommended to prefer 2nd-generation supraglottic devices to tracheal intubation to reduce perioperative respiratory complications."},{"ref":"Sédation procédurale","ref_en":"Procedural sedation","grade":"2+","fr":"Pour les procédures et/ou populations à risque de désaturation, il est recommandé d'utiliser l'oxygénation nasale à haut débit par rapport à une oxygénation bas débit, pour diminuer l'incidence des épisodes de désaturation durant la procédure.","en":"For procedures and/or populations at risk of desaturation, it is recommended to use high-flow nasal oxygenation rather than low-flow oxygenation, to reduce the incidence of desaturation episodes during the procedure."},{"ref":"Dispositifs supraglott.","ref_en":"Supraglottic devices","grade":"2+","fr":"En cas d'intubation ET ventilation au masque difficiles (y compris chez la femme enceinte), il est recommandé de recourir en première intention à un dispositif supraglottique de 2ème génération plutôt qu'à un dispositif de 1ère génération ou dédié à l'intubation (type LMA-Fastrach®), pour restaurer rapidement l'oxygénation.","en":"In case of difficult intubation AND difficult mask ventilation (including in pregnant women), it is recommended to use a 2nd-generation supraglottic device as first-line rather than a 1st-generation device or an intubation-dedicated device (such as the LMA-Fastrach®), to rapidly restore oxygenation."},{"ref":"« Cannot intubate, cannot oxygenate »","ref_en":"\"Cannot intubate, cannot oxygenate\"","grade":"2+","fr":"En cas d'intubation ET ventilation impossibles malgré un dispositif supraglottique de 2ème génération (y compris chez la femme enceinte), il est recommandé de réaliser en première intention une cricothyroïdotomie selon la technique SMS (Scalpel - Mandrin long béquillé - Sonde d'intubation), par rapport aux autres techniques d'abord sous-glottique d'urgence.","en":"In case of impossible intubation AND ventilation despite a 2nd-generation supraglottic device (including in pregnant women), it is recommended to perform cricothyroidotomy as first-line using the SMS technique (Scalpel - long bent-tip introducer [mandrin long béquillé] - intubation tube), rather than other emergency subglottic access techniques."}]$mgjson$::jsonb, $mgjson$["À VÉRIFIER : le signe « + » des puces « 1+ » / « 2+ » n'est pas imprimé par la source (qui porte « grade 1 » / « grade 2 » sans signe) ; il a été ajouté lors de la construction de la fiche française selon une convention de dépôt (« il est recommandé de… » = +). Le cahier des charges (§4.1) interdit tout grade déduit : valider ce codage ou remplacer par « grade 1 » / « grade 2 ». La version anglaise recopie les puces françaises à l'identique.","À VÉRIFIER : la ligne « Obstétrique (>16 SA) » (« les experts suggèrent de ne PAS utiliser un dispositif supraglottique… ») est une recommandation à polarité négative classée AE — le sens est porté par le texte, pas par la puce ; vérifier polarité et grade dans la source (traduction anglaise : « NOT using », en majuscules comme dans la source française).","À VÉRIFIER : « SMS (Scalpel - Mandrin long béquillé - Sonde d'intubation) » — traduction anglaise « Scalpel - long bent-tip introducer [mandrin long béquillé] - intubation tube » ; l'équivalent anglais usuel de la technique est « scalpel-bougie-tube » (repris dans le tableau 1 avec la mention du libellé français). À confirmer avec le relecteur (matériel exact).","À VÉRIFIER : abréviations françaises traduites — ONHD → HFNO (oxygénation nasale à haut débit), SA → WA (semaines d'aménorrhée), IADE conservé (infirmier anesthésiste), RMM → M&M review ; les libellés de catégories ont été raccourcis dans le tableau source (« Préox. + ONHD », « Vidéo vs fibro. ») et développés en anglais (« Preox. + HFNO », « Video vs fiberscope »).","À VÉRIFIER : notes internes de l'atelier (« trouvé via recherche web », clés `intubation_difficile_adulte`, `voies_aeriennes_adulte`, « library_final.json ») présentes dans l'introduction et la méta ; traduites telles quelles, à retirer avant publication. La fiche est annoncée comme actualisant deux fiches plus anciennes : lien de remplacement à créer dans la base (recommendation_links).","À VÉRIFIER : le tableau 1 (seuils minimaux de procédures) est une reproduction quasi identique d'un tableau de la source (CDC §12.4 : reformulation éditoriale attendue) ; statut juridique à valider."]$mgjson$::jsonb, '2026-09-03', 'b49fbd90204b901cd99c6148cdbc7016224e7c592c3e94cac338511acfa6179a', true
